  ui_story_5028_50280101_49_dialog_content = "돌무덤쥐야!",
  ui_story_5028_50280101_50_dialog_content = "에이! 왜 또 도망가는 건데?!",
  ui_story_5028_50280101_51_dialog_content = "(거의 다 잡은 거였는데... 흥!)",
  ui_story_5028_50280101_52_dialog_content = "(근데 키아로가 계속 울고 있어서 더는 쫓아갈 수가 없겠어...)",
  ui_story_5028_50280101_X52_dialog_content = "(...잠깐만, 왜 저렇게 우는 거지?)",
  ui_story_5028_50280101_X53_dialog_content = "(목이 찢어지도록 울고 있잖아... 무슨 까마귀 80마리가 합창하는 것처럼!)",
  ui_story_5028_50280101_53_dialog_content = "휴, 이번엔 또 뭐가 문제인지 봐야겠네...",
  ui_story_5028_50280101_54_dialog_content = "......",
  ui_story_5028_50280101_55_dialog_content = "루! 루!",
  ui_story_5028_50280101_56_dialog_content = "알았어, 그만 울어, 키아로. 나 왔어.",
  ui_story_5028_50280101_57_dialog_content = "...너, 나무엔 왜 올라갔어?",
  ui_story_5028_50280101_58_dialog_content = "루...",
  ui_story_5028_50280101_59_dialog_content = "......",
  ui_story_5028_50280101_60_dialog_content = "아니지...?",
  ui_story_5028_50280101_61_dialog_content = "덩치도 큰 녀석이 토끼 때문에 겁먹은 거야?",
  ui_story_5028_50280101_62_dialog_content = "루...",
  ui_story_5028_50280101_63_dialog_content = "뭐야, 고작 이런 일 때문에 돌무덤쥐를 놓친 거야?",
  ui_story_5028_50280101_64_dialog_content = "도움도 안 되는 녀석, 오늘은 하루 종일 나무에나 매달려 있어!",
  ui_story_5028_50280101_65_dialog_content = "루...",
  ui_story_5028_50280101_66_dialog_content = "루, 루.",
  ui_story_5028_50280101_67_dialog_content = "에이, 농담이야, 농담. 그렇게 불쌍하게 굴지 마.",
  ui_story_5028_50280101_68_dialog_content = "토끼 씨, 토끼 씨, 혹시 다른 데로 좀 가 줄 수 있을까?",
  ui_story_5028_50280101_69_dialog_content = "너 때문에 내 친구가 놀란 것 같거든.",
  ui_story_5028_50280101_70_dialog_content = "?!",
  ui_story_5028_50280101_71_dialog_content = "아, 아니야. 네가 무섭게 생겼다는 말은 아니야!",
  ui_story_5028_50280101_72_dialog_content = "<color=#e8d9bb>콰앙──!</color>",
  ui_story_5028_50280101_73_dialog_content = "어디 갔어! 당장 나와!",
  ui_story_5028_50280101_74_dialog_content = "사부 때문에 이게 뭐야! 왜 키아로가 날 따라오게 만든 거냐구!",
  ui_story_5028_50280101_75_dialog_content = "사고만 치고, 하나도 도움이 안 됐단 말이야!",
  ui_story_5028_50280101_76_dialog_content = "엄청 시끄럽네, 누구야?",
  ui_story_5028_50280101_77_dialog_content = "편지? 창문 수리? 아니면...",
  ui_story_5028_50280101_78_dialog_content = "나라고! 제자!",
  ui_story_5028_50280101_79_dialog_content = "제자? 어느 제자?",
  ui_story_5028_50280101_80_dialog_content = "비크",
  ui_story_5028_50280101_X80_dialog_content = "18세(?)",
  ui_story_5028_50280101_81_dialog_content = "피폐한 무직 유랑민",
  ui_story_5028_50280101_82_dialog_content = "피아! 피아라고!",
  ui_story_5028_50280101_83_dialog_content = "또 술 마셨지?! 자기 이름은 기억하고 있어?!",
  ui_story_5028_50280101_83X_dialog_content = "그거야 쉽지. 난 비크야.",
  ui_story_5028_50280101_83X1_dialog_content = "...진짜로 그걸 묻는 줄 알았어?",
  ui_story_5028_50280101_84_dialog_content = "아! 피아, 돌아왔구나.",
  ui_story_5028_50280101_85_dialog_content = "네가 뭘 하러 나갔더라...",
  ui_story_5028_50280101_86_dialog_content = "정글펄리펀트의 배설물을 수집하러 갔었나?",
  ui_story_5028_50280101_87_dialog_content = "그딴 걸 누가 하는데?!",
  ui_story_5028_50280101_88_dialog_content = "난 돌무덤쥐를 찾으러 간 거였어!",
  ui_story_5028_50280101_89_dialog_content = "아, 그랬지, 돌무덤쥐. 어때? 잡았어?",
  ui_story_5028_50280101_90_dialog_content = "거의 다 잡을 뻔했어... 그런데!",
  ui_story_5028_50280101_91_dialog_content = "이 키아로가 계속 방해했다니까! 그래서 마지막에 놓쳐버렸다구!",
  ui_story_5028_50280101_S91_dialog_content = "도망쳤구나. 그거 아깝네. 그래서 그걸 왜 잡으려는 건데?",
  ui_story_5028_50280101_S92_dialog_content = "습성을 관찰하려고 그러지! 사부가 나한테 준 숙제가 그거였잖아!",
  ui_story_5028_50280101_S93_dialog_content = "아아, 그럼 이제 노트에 「돌무덤쥐는 소심하고 사람을 무서워한다」라고 쓰면 되겠네.",
  ui_story_5028_50280101_S94_dialog_content = "하아? 그게 다야?",
  ui_story_5028_50280101_S95_dialog_content = "나머지는 천천히 해도 돼. 내가 했던 말 기억해?\n환상동물에 대한 연구는 존중을 바탕으로 이루어져야 해.",
  ui_story_5028_50280101_S96_dialog_content = "녀석들의 다양한 습성과 기질을 존중하고, 현실의 처지를 존중해야 돼.",
  ui_story_5028_50280101_S97_dialog_content = "이해하되 간섭하지 말 것, 그것이야말로 환상동물 마스터가 되기 위한 핵심이야.",
  ui_story_5028_50280101_92_dialog_content = "학문의 길은 그런 거야. 넌 아직 배워야 할 게 많아.",
  ui_story_5028_50280101_93_dialog_content = "또 거창한 말만 늘어놓네. 그런 걸 「꼰대」라고 하는 거 몰라?",
  ui_story_5028_50280101_94_dialog_content = "무슨 소리야? 난 안 늙었어!",
  ui_story_5028_50280101_X94_dialog_content = "잘생긴 남자는 절대 늙지 않는다고!",
  ui_story_5028_50280101_X95_dialog_content = "(흥, 또 겉멋이나 부리긴. 내가 그런 거나 상대해 줄 만큼 한가한 줄 알아?!)",
  ui_story_5028_50280101_95_dialog_content = "내가 이해가 안 되는 건 그러니까 왜 키아로가 날 따라다니게 놔두냐는 거야.",
  ui_story_5028_50280101_96_dialog_content = "나, 난 쟤랑 잘 안 맞는다고. 파트너로 적합하지 않아!",
  ui_story_5028_50280101_97_dialog_content = "쟤가 있으면 되는 일이 하나도 없어. 이래가지고 <color=#FFB400>환상동물 마스터</color>가 될 수 있겠냐고!",
  ui_story_5028_50280101_98_dialog_content = "그건 네가 녀석과 이야기할 수 없기 때문 아닐까?",
  ui_story_5028_50280101_99_dialog_content = "......",
  ui_story_5028_50280101_100_dialog_content = "맞아.",
  ui_story_5028_50280101_102_dialog_content = "동물과 소통하는 건 네 재능이지만, 그 재능에만 너무 의존하면 오히려 일을 망칠 수 있어.",
  ui_story_5028_50280101_103_dialog_content = "예를 들면 넌 오로리안의 언어를 알지만, 그것만으로 모두와 친구가 될 수 있을까?",
  ui_story_5028_50280101_104_dialog_content = "아, 미안. 너한테 친구가 없다는 걸 잊고 있었네.",
  ui_story_5028_50280101_105_dialog_content = "뭐, 뭐야...?!",
  ui_story_5028_50280101_106_dialog_content = "사부도 친구 없으면서 뭘 우쭐대!",
  ui_story_5028_50280101_107_dialog_content = "어른이 친구를 사귀는 건 애들이랑 다른 법이야! 네가 뭘 알아?",
  ui_story_5028_50280101_108_dialog_content = "흥, 어른들이 친구를 사귀는 건 기껏해야 술집에서 허풍이나 치는 거잖아!",
  ui_story_5028_50280101_109_dialog_content = "그, 그건...",
  ui_story_5028_50280101_110_dialog_content = "그리고 마지막엔 자기 제자한테 술값을 내달라질 않나!",
  ui_story_5028_50280101_111_dialog_content = "설마 백수 중년 남성은 전부 다 사부처럼 되는 거야?",
  ui_story_5028_50280101_112_dialog_content = "돈도 없고, 할 일도 없고, 매일 집에나 처박혀 있고!",
  ui_story_5028_50280101_113_dialog_content = "됐어! 그만! 그리고 누가 백수 중년 남성이라는 거야?!",
  ui_story_5028_50280101_S113_dialog_content = "제자가 없으면 제대로 살지도 못하는 사람이 누군데?!",
  ui_story_5028_50280101_S114_dialog_content = "항상 나가기 전에 세끼 밥도 차려줘야 되고,\n돌아오면 꼬맹이들이 어지럽힌 방도 치워야 되고.",
  ui_story_5028_50280101_S115_dialog_content = "이제 좀 자립해서 살아갈 수 없겠어? 이 어른아!",
  ui_story_5028_50280101_S116_dialog_content = "너, 너...",
  ui_story_5028_50280101_114_dialog_content = "그래도 난 네 사부라고. 사부님한테 말을 좀 부드럽게 해야 되지 않겠어?",
  ui_story_5028_50280101_X114_dialog_content = "그럼 조금 부드럽게...",
  ui_story_5028_50280101_X115_dialog_content = "(아니, 아니지, 내 말이 맞잖아!)",
  ui_story_5028_50280101_X116_dialog_content = "(이럴 때 약해지면 또 전처럼 얼렁뚱땅 넘어갈 거야.)",
  ui_story_5028_50280101_X117_dialog_content = "(내 입장을 확실하게 보여주려면 거칠게 대해야 돼. 그래! 거칠게!)",
  ui_story_5028_50280101_115_dialog_content = "그러게 제대로 신경 좀 써서 가르쳐 주지 그랬어!",
  ui_story_5028_50280101_116_dialog_content = "뭐든 다 나보고 알아서 하라고 하고, 사부는 집에 자빠져 있었잖아!",
  ui_story_5028_50280101_117_dialog_content = "지금은 더 심해져서 방해꾼까지 나한테 붙이고 말이야.",
  ui_story_5028_50280101_118_dialog_content = "대체 왜 이러는지 이유라도 좀 말해줘야 할 거 아냐!",
  ui_story_5028_50280101_119_dialog_content = "그래, 그래. 애들은 늘 이렇게 쉽게 화를 낸다니까.",
  ui_story_5028_50280101_120_dialog_content = "너 말이야. 왜 동물이랑은 소통할 수 있으면서 쟤랑은 안 되는지 생각해 봤어?",
  ui_story_5028_50280101_121_dialog_content = "모르겠어...",
  ui_story_5028_50280101_122_dialog_content = "그건 키아로가...",
  ui_story_5028_50280101_123_dialog_content = "<color=#FFB400>희귀종</color>이라서 그런 거야.",
  ui_story_5028_50280101_124_dialog_content = "희귀종?!",
  ui_story_5028_50280101_125_dialog_content = "루?",
  ui_story_5028_50280101_126_dialog_content = "우리가 연구하는 환상동물은 자연계에서도 수가 매우 적고,\n독특한 습성을 지닌 생물들이야.",
  ui_story_5028_50280101_X126_dialog_content = "그 기묘한 특성은 저들이 자신의 방식으로 루미나를 사용하는 데서 비롯되었을 거야.",
  ui_story_5028_50280101_X127_dialog_content = "그리고 희귀종은 환상동물 중에서도 가장 진귀한 종류고,\n평범한 환상동물을 훨씬 능가하는 힘을 가지고 있어.",
  ui_story_5028_50280101_127_dialog_content = "근데 왜 저렇게 멍청해 보이는데?",
  ui_story_5028_50280101_128_dialog_content = "아직 어른이 아니니까 그렇지, 바보야.",
  ui_story_5028_50280101_129_dialog_content = "희귀종은 철저한 탈피를 한번 거쳐야 하거든. 난 그걸 <color=#FFB400>「진화」</color>라고 불러.",
  ui_story_5028_50280101_130_dialog_content = "진화를 마친 키아로는 상상할 수 없을 정도로 강력해!",
  ui_story_5028_50280101_131_dialog_content = "돈이 필요하면 돌을 금으로 바꿀 수도 있어.",
  ui_story_5028_50280101_132_dialog_content = "힘을 원한다면 군대도 손쉽게 제압해서 백야성도 발아래에 둘 수 있어.",
  ui_story_5028_50280101_133_dialog_content = "권력을 원한다면 그 타고난 위압감은 그 누구도 비할 수 없어.\n북방의 여왕조차 녀석을 보면 고개를 숙일 거야!",
  ui_story_5028_50280101_134_dialog_content = "그런 대단한 녀석을 내가 큰마음 먹고 너한테 준 거라고.",
  ui_story_5028_50280101_135_dialog_content = "휴, 이게 다 내가 정성이 너무 지극한 탓이라니까.",
  ui_story_5028_50280101_136_dialog_content = "......",
  ui_story_5028_50280101_137_dialog_content = "또 허풍 치는 거지?",
  ui_story_5028_50280101_138_dialog_content = "뭐? 어, 어떻게 사부한테 그런 말을 할 수가 있어!",
  ui_story_5028_50280101_139_dialog_content = "내가 몇 번이나 말했어?",
  ui_story_5028_50280101_140_dialog_content = "작년엔 사부가 비공정을 하나 사 와서 나랑 놀러 가겠다고 했어.",
  ui_story_5028_50280101_141_dialog_content = "그래서 짐을 싸고 한참 기다렸는데, 고작 풍선 한 개만 사 가지고 왔잖아!",
  ui_story_5028_50280101_142_dialog_content = "그거야 비공정이 그렇게 비쌀 줄 몰라서 그랬지...",
  ui_story_5028_50280101_143_dialog_content = "그리고 겨울엔 나한테 중요한 과목이 있다면서 가시돌고래를 연구하라고 했어.",
  ui_story_5028_50280101_144_dialog_content = "난 3일이나 걸려서 그걸 찾았고, 그 녀석을 잡는 데도 하룻밤이 걸렸어.",
  ui_story_5028_50280101_145_dialog_content = "근데! 사부는 그걸 가지고 신발을 닦았어!",
  ui_story_5028_50280101_146_dialog_content = "아, 그건...",
  ui_story_5028_50280101_147_dialog_content = "그리고 사부는 자기가 귀족이고, 전에 가수였는데,\n수백만 명의 팬들이 따라다니는 걸 피하려고 숨어서 환상동물 연구를 시작했다고 했어.",
  ui_story_5028_50280101_148_dialog_content = "그것도 전부 가짜잖아! 다 거짓말이었어!",
  ui_story_5028_50280101_149_dialog_content = "이 희귀종도 그렇겠지!",
  ui_story_5028_50280101_X149_dialog_content = "(화나 죽겠어! 내가 이렇게 노력했는데... 사부는...)",
  ui_story_5028_50280101_X150_dialog_content = "피아, 잠깐만...",
  ui_story_5028_50280101_150_dialog_content = "<size=50>나, 난 진짜로 환상동물 마스터가 되고 싶단 말이야!</size>",
  ui_story_5028_50280101_151_dialog_content = "결국 배운 지식도 없고, 방해꾼까지 붙어버렸어...",
  ui_story_5028_50280101_152_dialog_content = "이래서야 나 혼자보다 더 손해잖아!",
  ui_story_5028_50280101_153_dialog_content = "......",
  ui_story_5028_50280101_154_dialog_content = "그렇구나. 이해했어.",
  ui_story_5028_50280101_155_dialog_content = "넌 이 사부가 더는 너한테 가르침을 줄 수 없다고 생각하는 거지?",
  ui_story_5028_50280101_156_dialog_content = "아, 그건...",
  ui_story_5028_50280101_157_dialog_content = "넌 재능이 있어. 어쩌면 내 전통적인 교육 방식이 시대에 뒤떨어진 걸지도 몰라.",
  ui_story_5028_50280101_158_dialog_content = "난 지금까지 널 어엿한 환상동물 마스터로 교육하고 있다고 생각했어.",
  ui_story_5028_50280101_159_dialog_content = "너한테 직접 해보라고 한 건 배움에 있어 체험이 무척 중요하다고 생각했기 때문이야.",
  ui_story_5028_50280101_160_dialog_content = "네 곁에 있지 않았던 건 네가 스스로 문제를 해결하는 방법을 배우길 원해서였고.",
  ui_story_5028_50280101_161_dialog_content = "근데 이제 보니 내 생각이 틀렸었던 것 같네.",
  ui_story_5028_50280101_162_dialog_content = "아, 아니... 그런 게 아니라...",
  ui_story_5028_50280101_163_dialog_content = "그것도 그래. 넌 동물과 소통하는 재능이 있으니까, 별다른 교육은 필요하지 않아.",
  ui_story_5028_50280101_164_dialog_content = "이제 졸업할 준비를 하렴.",
  ui_story_5028_50280101_165_dialog_content = "졸업?!",
  ui_story_5028_50280101_166_dialog_content = "그래, 넌 이제 더는 나 같은 사부가 필요하지 않아.",
  ui_story_5028_50280101_167_dialog_content = "내, 내 말은 그게 아니고...",
  ui_story_5028_50280101_168_dialog_content = "마침 잘됐네. 그럼 졸업식은 저 녀석으로 하자.",
  ui_story_5028_50280101_169_dialog_content = "루?",
  ui_story_5028_50280101_170_dialog_content = "뭐?",
  ui_story_5028_50280101_171_dialog_content = "그래도 이걸로 마지막인데, 제자가 원하는 걸 얻게 해 줘야겠지.",
  ui_story_5028_50280101_172_dialog_content = "키아로, 이 희귀종은 내가 너한테 주는 선물이야.",
  ui_story_5028_50280101_173_dialog_content = "네가 녀석을 무사히 진화시킬 수 있다면, 환상동물 마스터가 될 자격은 충분할 거야.",
  ui_story_5028_50280101_174_dialog_content = "이게 널 위해 준비한 내 마지막 수업이야.",
  ui_story_5028_50280101_175_dialog_content = "사부...",
  ui_story_5028_50280101_176_dialog_content = "울지 마. 환상동물 마스터가 되는 건 항상 네 꿈이었잖아.",
  ui_story_5028_50280101_177_dialog_content = "키아로를 진화시키고 날 찾아오면 네 소원이 이루어질 거야.",
  ui_story_5028_50280101_178_dialog_content = "있으나 마나 한 이 사부는... 그냥 혼자 늙어 죽게 내버려 둬.",
  ui_story_5028_50280101_179_dialog_content = "사부...",
  ui_story_5028_50280101_180_dialog_content = "근데 키아로를 진화시키는 방법은 아직 안 말해줬는데?",
  ui_story_5028_50280101_181_dialog_content = "......",
  ui_story_5028_50280101_182_dialog_content = "지금 그걸 더 신경 쓰는 거야?",
  ui_story_5028_50280101_183_dialog_content = "아니면 뭐 어쩌라고?",
  ui_story_5028_50280101_184_dialog_content = "환상동물 마스터가 되고 싶어서?",
  ui_story_5028_50280101_185_dialog_content = "응! 그건 내 꿈이니까!",
  ui_story_5028_50280101_186_dialog_content = "그, 그럼 나한테 하고 싶은 말은 하나도 없어?",
  ui_story_5028_50280101_187_dialog_content = "음... 있어!",
  ui_story_5028_50280101_188_dialog_content = "사부, 이번엔 진짜로 거짓말 아니지?",
  ui_story_5028_50280101_189_dialog_content = "너...",
  ui_story_5028_50280101_190_dialog_content = "혹시 사부도 진화 방법을 모르는 건 아니지?",
  ui_story_5028_50280101_191_dialog_content = "아니면 진화 같은 건 애초에 존재하지도 않는 건 아니고?",
  ui_story_5028_50280101_192_dialog_content = "다, 당연히 아니지!",
  ui_story_5028_50280101_193_dialog_content = "내가 언제 거짓말한 적 있었어?",
  ui_story_5028_50280101_194_dialog_content = "......",
  ui_story_5028_50280101_195_dialog_content = "그래, 이번엔 절대 거짓말이 아냐.",
  ui_story_5028_50280101_196_dialog_content = "희귀종의 진화는 확실히 어려운 일이야. 나한테도 성공할 수 있는 비법 같은 건 없어.",
  ui_story_5028_50280101_197_dialog_content = "대신 이 노트를 줄게.",
  ui_story_5028_50280101_198_dialog_content = "헤에!",
  ui_story_5028_50280101_199_dialog_content = "안에 적힌 건 내가 신중하게 설계한 시련이야.",
  ui_story_5028_50280101_200_dialog_content = "내 말 잊지 마. 가장 중요한 건 실전이야.",
  ui_story_5028_50280101_201_dialog_content = "모든 시련을 마치고 나면 키아로도 분명히 진화할 수 있을 거야.",
  ui_story_5028_50280101_202_dialog_content = "자기 자신을 믿어. 언젠간 반드시 성공할 테니까...",
  ui_story_5028_50280101_203_dialog_content = "알겠어. 고마워, 사부!",
  ui_story_5028_50280101_204_dialog_content = "그럼 지금 바로 출발할게! 바이바이!",
  ui_story_5028_50280101_205_dialog_content = "야, 잠깐만. 내 말 아직 안 끝났어...",
  ui_story_5028_50280101_206_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5028_50280101_207_dialog_content = "환상동물 마스터...",
  ui_story_5028_50280101_208_dialog_content = "키아로, 너 정말 진화할 수 있어?",
  ui_story_5028_50280101_209_dialog_content = "루!",
  ui_story_5028_50280101_210_dialog_content = "어디 보자, 엉터리 사부의 시련이 어떤 건지 한번 볼까?",
  ui_story_5028_50280101_211_dialog_content = "「희귀종 진화론」",
  ui_story_5028_50280101_212_dialog_content = "「시작에 앞서: 여기에 적혀 있는 시련은 필자 자신의 경험에 기초한다.」",
  ui_story_5028_50280101_213_dialog_content = "「어디까지나 제안일 뿐, 그 유효성을 보증하는 것은 아니다.」",
  ui_story_5028_50280101_214_dialog_content = "흥, 시작부터 책임회피냐고!",
  ui_story_5028_50280101_215_dialog_content = "근데... 하나, 둘, 셋, 넷... 방법이 꽤 많잖아.",
  ui_story_5028_50280101_216_dialog_content = "「시련 1: <color=#FFB400>아이테르</color>를 포획해 길들여서 친구가 된다.」",
  ui_story_5028_50280101_217_dialog_content = "아이테르? 그게 무슨 동물이지?",
  ui_story_5028_50280201_1_dialog_content = "시련: 아이테르 포획",
  ui_story_5028_50280201_2_dialog_content = "PlayerName, 우리 언제 놀 수 있어?",
  ui_story_5028_50280201_3_dialog_content = "조금만 기다려. 얼마 안 남았으니까.",
  ui_story_5028_50280201_4_dialog_content = "왜 지금은 안 돼? 나 기다리기 힘들어.",
  ui_story_5028_50280201_5_dialog_content = "우선 넓고 평평한 곳이 필요하거든.",
  ui_story_5028_50280201_6_dialog_content = "여긴 장애물이 잔뜩 있잖아. 야구를 할 수가 없어.",
  ui_story_5028_50280201_7_dialog_content = "오, 알았어.",
  ui_story_5028_50280201_8_dialog_content = "그럼 좀 빨리 걸으면 안 돼?",
  ui_story_5028_50280201_9_dialog_content = "하하하, 급하긴. 알았어, 좀 더 빨리 가자.",
  ui_story_5028_50280201_10_dialog_content = "<color=#e8d9bb>스슥... 스사삭...</color>",
  ui_story_5028_50280201_11_dialog_content = "이번엔 내가 공을 던질 테니까, 넌 그 배트로 공을 받아 쳐.",
  ui_story_5028_50280201_12_dialog_content = "저번에 루비가 여기서 고대 문화를 연구했거든. 그래서 루비한테 룰을 배웠어.",
  ui_story_5028_50280201_13_dialog_content = "쉽게 말하자면 공이 멀리 날아갈수록 대단한 거야.",
  ui_story_5028_50280201_14_dialog_content = "알겠지?",
  ui_story_5028_50280201_15_dialog_content = "알았어! 방망이로 공을 칠게!",
  ui_story_5028_50280201_16_dialog_content = "응! 그럼 한번 해보자!",
  ui_story_5028_50280201_17_dialog_content = "3, 2, 1...",
  ui_story_5028_50280201_18_dialog_content = "간다!",
  ui_story_5028_50280201_19_dialog_content = "<color=#e8d9bb>휙──</color>",
  ui_story_5028_50280201_20_dialog_content = "어? 왜 공을 피했어?",
  ui_story_5028_50280201_21_dialog_content = "PlayerName, 왜 날 공격했어?",
  ui_story_5028_50280201_22_dialog_content = "지금 건 공격이 아니라 투구야.",
  ui_story_5028_50280201_23_dialog_content = "「투구」?",
  ui_story_5028_50280201_24_dialog_content = "맞아. 내가 공을 너한테 던지면, 넌 그걸 되받아치는 거야.\n야구는 그렇게 하는 거야.",
  ui_story_5028_50280201_25_dialog_content = "그렇구나, 그럼 다시.",
  ui_story_5028_50280201_26_dialog_content = "좋아, 긴장하지 말고. 처음엔 못 치는 것도 자연스러운 일이니까.",
  ui_story_5028_50280201_27_dialog_content = "응.",
  ui_story_5028_50280201_28_dialog_content = "그럼 갈게! 3, 2, 1...",
  ui_story_5028_50280201_29_dialog_content = "간다!",
  ui_story_5028_50280201_30_dialog_content = "<color=#e8d9bb>휙──</color>",
  ui_story_5028_50280201_31_dialog_content = "<color=#e8d9bb>깡──!</color>",
  ui_story_5028_50280201_32_dialog_content = "와아아! 맞았어!",
  ui_story_5028_50280201_33_dialog_content = "오! 내가 쳤어!",
  ui_story_5028_50280201_34_dialog_content = "멀리 날아가고 있어!",
  ui_story_5028_50280201_35_dialog_content = "그래! 이게 바로 「홈런」이라는 거야!",
  ui_story_5028_50280201_36_dialog_content = "레비 너 어쩌면 야구에 소질이 있을지도 몰라!",
  ui_story_5028_50280201_37_dialog_content = "내가 소질이 있다고?",
  ui_story_5028_50280201_38_dialog_content = "응! 한 번에 이렇게 멀리 날릴 수 있다니, 대단하잖아!",
  ui_story_5028_50280201_39_dialog_content = "야구, 재미있어.",
  ui_story_5028_50280201_40_dialog_content = "근데 이제 어떻게 놀아?",
  ui_story_5028_50280201_41_dialog_content = "이다음엔...",
  ui_story_5028_50280201_42_dialog_content = "아... 일단 공을 주워 와야지.",
  ui_story_5028_50280201_43_dialog_content = "으아... 저렇게 멀리 날아가 버리다니, 곤란하네.",
  ui_story_5028_50280201_44_dialog_content = "미안, 다음엔 살살 칠게.",
  ui_story_5028_50280201_45_dialog_content = "아니, 아니, 널 탓하는 게 아냐. 멀리 날릴수록 좋다는 건 룰이니까!",
  ui_story_5028_50280201_46_dialog_content = "그럼 내가 공을 주우러 갈게. 내가 빠르니까.",
  ui_story_5028_50280201_47_dialog_content = "벌써 몇 분 지난 것 같은데... 레비는 왜 안 오지?",
  ui_story_5028_50280201_48_dialog_content = "<color=#e8d9bb>스슥...</color>",
  ui_story_5028_50280201_49_dialog_content = "공을 못 찾았나? 아니면 무슨 일이라도 생겼나?",
  ui_story_5028_50280201_50_dialog_content = "그러고 보니까 바이스가 이 근처엔 암귀가 출몰한다고 말했던 것 같은데...?!",
  ui_story_5028_50280201_51_dialog_content = "<color=#e8d9bb>스슥... 스슥...</color>",
  ui_story_5028_50280201_52_dialog_content = "아, 그래도 평범한 암귀는 레비의 상대가 안 되겠네.",
  ui_story_5028_50280201_53_dialog_content = "레비는...",
  ui_story_5028_50280201_54_dialog_content = "잡아!",
  ui_story_5028_50280201_55_dialog_content = "?! 그물?",
  ui_story_5028_50280201_56_dialog_content = "키아로 이 바보! 또 빗나갔잖아!",
  ui_story_5028_50280201_57_dialog_content = "이렇게 된 이상 어쩔 수 없지! 세게 나가자!",
  ui_story_5028_50280201_58_dialog_content = "너, 넌 누구야?! 나 엄청 대단한 사람이야!",
  ui_story_5028_50280201_59_dialog_content = "방금 내 옆에 있던 오로리안은 맨손으로 암귀를 수박처럼 깨트린다고!",
  ui_story_5028_50280201_60_dialog_content = "계속 다가오면 「감응 능력」으로 동료를 부를 거야!",
  ui_story_5028_50280201_61_dialog_content = "「감응 능력」? 역시 아이테르였구나!",
  ui_story_5028_50280201_62_dialog_content = "동료를 부르기 전에 잡아!",
  ui_story_5028_50280201_63_dialog_content = "키아로! 플랜B로 변경이야!",
  ui_story_5028_50280201_64_dialog_content = "루!",
  ui_story_5028_50280201_65_dialog_content = "잠깐만! 플랜B는 또 뭔데?!",
  ui_story_5028_50280201_66_dialog_content = "다가오지 마! 안 그러면 정말로 부를 거야!",
  ui_story_5028_50280201_67_dialog_content = "잡아──",
  ui_story_5028_50280201_68_option_content = "강제... 으악!",
  ui_story_5028_50280201_69_dialog_content = "내 허리!",
  ui_story_5028_50280201_70_dialog_content = "루우우!",
  ui_story_5028_50280201_71_dialog_content = "잘했어, 키아로. 그럼 계획대로 숲까지 후퇴하자!",
  ui_story_5028_50280201_72_dialog_content = "루루!",
  ui_story_5028_50280201_73_dialog_content = "이, 이거 놔! 날 어디로 데려가는 거야──!",
  ui_story_5028_50280201_74_dialog_content = "<anim type=Shake><size=45>레비── 레비──!</size></anim>",
  ui_story_5028_50280201_76_dialog_content = "나 왔어. 방금 토끼를 공으로 착각하고 한참 쫓아갔어.",
  ui_story_5028_50280201_77_dialog_content = "어? PlayerName?",
  ui_story_5028_50280201_78_dialog_content = "배트도 그대로 있네. 알겠어. 나보고 계속 홈런 연습하라는 거지?",
  ui_story_5028_50280201_79_dialog_content = "그럼 기대에 부응할게. 일단은 1000번 연습하자.",
  ui_story_5028_50280201_80_dialog_content = "루!",
  ui_story_5028_50280201_81_dialog_content = "자, 잠깐만! 이 이상한 녀석으로 날 어디까지 데려가려는 거야?!",
  ui_story_5028_50280201_82_dialog_content = "일단 좀 내려줘! 아까 허리를 부딪혀서 너무 아프다고!",
  ui_story_5028_50280201_83_dialog_content = "루?",
  ui_story_5028_50280201_84_dialog_content = "멈춰, 키아로!",
  ui_story_5028_50280201_85_dialog_content = "후우... 겨우 멈췄네. 으... 아파.",
  ui_story_5028_50280201_86_dialog_content = "키아로, 이게 플랜B에서 정했던 루트야?",
  ui_story_5028_50280201_87_dialog_content = "루루루?",
  ui_story_5028_50280201_88_dialog_content = "설마 대충 숲으로 달린 건 아니지?",
  ui_story_5028_50280201_89_dialog_content = "루...",
  ui_story_5028_50280201_90_dialog_content = "왔던 길도 안 보이잖아... 주변엔 나무밖에 없어.",
  ui_story_5028_50280201_91_dialog_content = "너, 너희 너무 경솔한 거 아냐?! 이 숲엔 암귀가 있다고!",
  ui_story_5028_50280201_92_dialog_content = "암귀?",
  ui_story_5028_50280201_93_dialog_content = "크아아──!",
  ui_story_5028_50280201_94_dialog_content = "진짜 나왔잖아!",
  ui_story_5028_50280201_95_dialog_content = "왜... 암귀가 있는 건데?!",
  ui_story_5028_50280201_96_dialog_content = "뭘 멍하니 있어?! 빨리 도망쳐!",
  ui_story_5028_50280201_97_dialog_content = "캬악!",
  ui_story_5028_50280201_98_dialog_content = "키아로!",
  ui_story_5028_50280201_99_dialog_content = "루!",
  ui_story_5028_50280201_100_dialog_content = "왜 암귀가... 왜 암귀가 있는 거야?",
  ui_story_5028_50280201_101_dialog_content = "지금 그런 말 할 때가 아니잖아! 일단 도망쳐!",
  ui_story_5028_50280201_102_dialog_content = "안 돼, 못 움직이겠어... 으...",
  ui_story_5028_50280201_103_dialog_content = "난 환상동물이랑 사이좋게 지내는 건 잘하지만... 암귀 같은 건 정말 싫어!",
  ui_story_5028_50280201_104_dialog_content = "싫어, 싫어... 아직 환상동물 마스터가 되지도 못했는데\n암귀한테 잡아먹히고 싶지 않아!",
  ui_story_5028_50280201_105_dialog_content = "생각해 보자... 분명히 뭔가 방법이 있을 거야...",
  ui_story_5028_50280201_106_dialog_content = "사부가 그랬어. 위험을 앞두고 절대 울면 안 된다고... 머리를 쓰라고 말이야!",
  ui_story_5028_50280201_107_dialog_content = "아니면 내가 시간을 벌어서 키아로랑 아이테르가 먼저 도망치게 할까?",
  ui_story_5028_50280201_108_dialog_content = "근데 내 힘만으로는... 아, 상관없어... 쟤들까지 나 때문에 휘말리게 할 순 없어!",
  ui_story_5028_50280201_109_dialog_content = "저, 저기, 일단 좀 진정해. 너 싸울 줄 알아?",
  ui_story_5028_50280201_110_dialog_content = "응... 조금 알지만 어디까지나 호신용이야.",
  ui_story_5028_50280201_111_dialog_content = "괜찮아! 보통 처음 모험을 시작했을 때 마주치는 적은 약한 편이니까!",
  ui_story_5028_50280201_112_dialog_content = "운명이란 그런 거야.",
  ui_story_5028_50280201_113_dialog_content = "그럼 내가 내 능력을 사용해서 도와줄게!",
  ui_story_5028_50280201_114_dialog_content = "지금 숲에서 뛰어다녀 봤자 더 많은 암귀를 유인할 뿐이야.",
  ui_story_5028_50280201_114X_dialog_content = "우선 쫓아오는 적들부터 쓰러트리고 다음 대책을 마련하자!",
  ui_story_5028_50280201_115_dialog_content = "근데 너무 많잖아...",
  ui_story_5028_50280201_116_dialog_content = "날 믿어!",
  ui_story_5028_50280201_117_dialog_content = "그리고 우리 둘만 있는 게 아니잖아. 네 친구도 있고!\n셋이 힘을 합치면 분명히 이길 수 있을 거야!",
  ui_story_5028_50280201_118_dialog_content = "루!",
  ui_story_5028_50280201_119_dialog_content = "응! 알겠어!",
  ui_story_5028_50280201_120_dialog_content = "근데 앞으로는 「너」라고 부르지 마! 난 세계 제일의 환상동물 마스터니까!",
  ui_story_5028_50280201_121_dialog_content = "암귀 주제에 갑자기 나와서 날 위협해?!",
  ui_story_5028_50280201_122_dialog_content = "전부 줄이나 서서 맞을 준비해!",
  ui_story_5028_50280202_1_dialog_content = "저, 정말 이겼어!",
  ui_story_5028_50280202_2_dialog_content = "대단해! 키아로! 봤어?!",
  ui_story_5028_50280202_3_dialog_content = "루! 루!",
  ui_story_5028_50280202_4_dialog_content = "헤헤~ 키아로, 너 생각보다 대단하잖아~ 나 다시 봤어!",
  ui_story_5028_50280202_5_dialog_content = "루~",
  ui_story_5028_50280202_6_dialog_content = "(둘이 껴안고 있는 틈에 얼른 갈까...)",
  ui_story_5028_50280202_7_dialog_content = "저기...",
  ui_story_5028_50280202_8_dialog_content = "(근데 여긴 암귀투성이잖아. 이대로 두고 가면 위험할 거야.)",
  ui_story_5028_50280202_9_dialog_content = "(휴...)",
  ui_story_5028_50280202_10_dialog_content = "저기, 아이테르 씨?",
  ui_story_5028_50280202_11_dialog_content = "아, 응.",
  ui_story_5028_50280202_12_dialog_content = "방금... 나랑 키아로를 도와줘서 고마워.",
  ui_story_5028_50280202_13_dialog_content = "아, 아니야. 별일 아닌데 뭐.",
  ui_story_5028_50280202_14_dialog_content = "나한테 감사할 필요는 없어. 그럼 너희들한테 폐 끼치지 않게 난 이만 갈게.",
  ui_story_5028_50280202_15_dialog_content = "그건 곤란하지, 아이테르 씨.",
  ui_story_5028_50280202_16_dialog_content = "설마 숙녀의 부끄러운 모습을 보고도 아무렇지도 않게 떠날 수 있다고 생각하는 거야?",
  ui_story_5028_50280202_17_dialog_content = "나, 나 아무것도 기억 안 나! 여긴 어디지? 방금 무슨 일 있었어?",
  ui_story_5028_50280202_18_dialog_content = "기억 상실인 척해도 소용없어.",
  ui_story_5028_50280202_19_dialog_content = "얌전히 키아로랑 마찬가지로 내 동료 겸 펫이 돼서, 내 곁에서 날 도와줘!",
  ui_story_5028_50280202_20_dialog_content = "(헤헤, 이 타이밍에 내 가장 귀여운 미소로 아이테르를 사로잡자!)",
  ui_story_5028_50280202_21_dialog_content = "싫어! 거절할게!",
  ui_story_5028_50280202_22_dialog_content = "하아?",
  ui_story_5028_50280202_23_dialog_content = "아까는 호의로 도와줬을 뿐이지, 네 말을 듣겠다는 뜻이 아냐.",
  ui_story_5028_50280202_24_dialog_content = "게다가 그 키아로인가 뭔가 하는 녀석이 나한테 부딪히고,\n억지로 날 여기까지 끌고 온 것도 아직 안 따졌어.",
  ui_story_5028_50280202_25_dialog_content = "일단 같이 숲을 나가자. 그리고 각자 빚을 청산하고 헤어지는 거야!",
  ui_story_5028_50280202_26_dialog_content = "훌쩍...",
  ui_story_5028_50280202_27_dialog_content = "(내가 너무 심하게 말했나?)",
  ui_story_5028_50280202_28_dialog_content = "(아니지, 날 속이려는 걸지도 몰라. 옆에 있는 키아로라는 생물도 수상해.)",
  ui_story_5028_50280202_29_dialog_content = "흑흑...",
  ui_story_5028_50280202_30_dialog_content = "난 그저... 친구를 원했을 뿐이야...",
  ui_story_5028_50280202_31_dialog_content = "루...",
  ui_story_5028_50280202_32_dialog_content = "사람들은 날 좋아해 주는 건 고작해야 환상동물들밖에 없을 거라고 했어...\n그래서 나도 오로리안이나 아이테르랑 친구가 될 수 있다는 걸 증명하고 싶었어...",
  ui_story_5028_50280202_33_dialog_content = "그리고... 그저 사부의 「유언」을 이루고 싶었을 뿐이야...",
  ui_story_5028_50280202_34_dialog_content = "(사부? 아까 말한 그 사람 말이야? 유언이라니? 이미 세상을 떠났던 거야?)",
  ui_story_5028_50280202_35_dialog_content = "으엣취──!",
  ui_story_5028_50280202_36_dialog_content = "괜찮아, 타래야. 아마 감기일 거야.",
  ui_story_5028_50280202_37_dialog_content = "내가 걱정되니? 그럼 널 가지고 코를 좀 닦아도 될까?",
  ui_story_5028_50280202_38_dialog_content = "아하하, 당연히 농담이지. 네 털은 팔아서 술을 사야 되니까.",
  ui_story_5028_50280202_39_dialog_content = "(설마 정말 우는 건 아니겠지? 눈이 빨개졌잖아.)",
  ui_story_5028_50280202_40_dialog_content = "(얘, 레비보다 훨씬 어린 것 같은데? 게다가 전투도 능숙하지 않아.)",
  ui_story_5028_50280202_40X_dialog_content = "(혼자 많이 고생했겠지.)",
  ui_story_5028_50280202_41_dialog_content = "그래서 난... 아이테르 씨를 잡아서 친구가 되고 싶었어...",
  ui_story_5028_50280202_42_dialog_content = "(울지 마. 제발 울지 마...)",
  ui_story_5028_50280202_43_dialog_content = "저...정말 미안해. 그렇게 심한 짓을 해버려서... 피아도 진심으로 후회하고 있어.",
  ui_story_5028_50280202_44_dialog_content = "아이테르 씨, 그렇게 피아가 싫으면... 이대로 나 혼자 여기 두고...",
  ui_story_5028_50280202_45_dialog_content = "알아서 살다 죽게 놔둬...",
  ui_story_5028_50280202_46_dialog_content = "흐아아아앙!",
  ui_story_5028_50280202_47_dialog_content = "내가 잘못했어!",
  ui_story_5028_50280202_48_dialog_content = "미안, 미안... 내가 너무 심하게 말한 것 같아.",
  ui_story_5028_50280202_49_dialog_content = "친구가 되고 싶다는 거지? 나도 너랑 친구가 되고 싶어.\nPlayerName, 내 이름이야.",
  ui_story_5028_50280202_50_dialog_content = "저, 정말? 난 피아야!",
  ui_story_5028_50280202_51_dialog_content = "그래, 피아. 그럼 이제부터 우린 친구야!",
  ui_story_5028_50280202_52_dialog_content = "진짜?",
  ui_story_5028_50280202_53_dialog_content = "그래! 진짜로!",
  ui_story_5028_50280202_54_dialog_content = "루!",
  ui_story_5028_50280202_55_dialog_content = "헤헤... 그럼 PlayerName 네가 내 첫 번째 친구네!",
  ui_story_5028_50280202_56_dialog_content = "피아의 친구가 돼 줘서 정말 기뻐!",
  ui_story_5028_50280202_57_dialog_content = "사부! 보고 있지? 피아가 친구를 만들었어!",
  ui_story_5028_50280202_58_dialog_content = "루루~",
  ui_story_5028_50280202_59_dialog_content = "(크윽! 눈물 공격 뒤에 엄청나게 귀여운 미소 공격인가?!)",
  ui_story_5028_50280202_60_dialog_content = "(근데 얘도 정말 예전의 나처럼 친구가 없는 걸까?\n아니지, 적어도 나한테는 스카이워커가 있었어.)",
  ui_story_5028_50280202_61_dialog_content = "(그리고 얘 곁에도 키아로라는 저 생물이 있어.)",
  ui_story_5028_50280202_62_dialog_content = "(뭐, 만에 하나 얘가 연기를 하는 거라고 해도,\n여자애를 울린 채로 숲속에 남겨둘 순 없어.)",
  ui_story_5028_50280202_63_dialog_content = "PlayerName, PlayerName, 무슨 생각해?",
  ui_story_5028_50280202_64_dialog_content = "아, 별거 아냐. 이제 슬슬 돌아가야 될 것 같은데.\n내가 콜로서스로 집까지 데려다줄게.",
  ui_story_5028_50280202_65_dialog_content = "참! 아이테르는 콜로서스를 가지고 있었지!",
  ui_story_5028_50280202_66_dialog_content = "그럼 앞으로의 여행은 콜로서스로 이동할 수 있겠네!\n그럼 사부의 시련도 금방 마칠 수 있을 거야!",
  ui_story_5028_50280202_67_dialog_content = "자, 가자. PlayerName 오빠~",
  ui_story_5028_50280202_68_dialog_content = "어? 시련이 뭔데? 손 잡아당기지 마...",
  ui_story_5028_50280202_69_dialog_content = "허리가 아직도 아프다고! 당기지 마!",
  ui_story_5028_50280202_70_dialog_content = "그, 그리고 레비한테도 말하러 가야 한다고──!",
  ui_story_5028_50280202_71_dialog_content = "998번... 에잇! 999번...에잇!",
  ui_story_5028_50280202_72_dialog_content = "1000번... 에잇!",
  ui_story_5028_50280202_73_dialog_content = "PlayerName, 아직도 안 온 거야? 난 벌써 연습도 끝났는데.",
  ui_story_5028_50280202_74_dialog_content = "뭐, 됐어. 콜로서스로 돌아갔을지도 모르겠네. 나도 돌아가자.",
  ui_story_5028_50280202_75_dialog_content = "어?",
  ui_story_5028_50280202_76_dialog_content = "콜로서스는?",
  ui_story_5028_50280202_77_dialog_content = "PlayerName?",
  ui_story_5028_50280202_78_dialog_content = "어디 갔어?",
  ui_story_5028_50280202_79_dialog_content = "이 편지는 또 뭐야?",
  ui_story_5028_50280301_1_dialog_content = "시련: 드라코리온의 알 받기",
  ui_story_5028_50280301_2_dialog_content = "「<color=#FFB400>드라코리온</color>의 머리는 신화에 나오는 거대한 드래곤의 모습이다.」",
  ui_story_5028_50280301_3_dialog_content = "「그리고 사자처럼 강한 몸, 매나 독수리 같은 씩씩한 날개를 가지고 있고...」",
  ui_story_5028_50280301_4_dialog_content = "「코뿔소조차 쉽게 날려버릴 수 있는 강한 꼬리가 있다...」",
  ui_story_5028_50280301_5_dialog_content = "「그러나 더 무서운 것은 엄청난 힘을 지닌 두 발이다.」",
  ui_story_5028_50280301_5X_dialog_content = "「드라코리온은 지상의 어떤 사냥감이든지 추적해 무자비하게 제압할 수 있다.」",
  ui_story_5028_50280301_6_dialog_content = "「다행인 점은, 드라코리온은 기차처럼 지상을 누비는 것보다는\n하늘을 나는 것을 더 좋아한다.」",
  ui_story_5028_50280301_6X_dialog_content = "「따라서 보통 사람들이 마주칠 일은 거의 없다.」",
  ui_story_5028_50280301_7_dialog_content = "「하지만 우리의 이번 목표물은... 바로 <color=#FFB400>희귀종</color>인 그 드라코리온이다.」",
  ui_story_5028_50280301_8_dialog_content = "저기, 피아, 혼자서 뭘 중얼거리고 있어?",
  ui_story_5028_50280301_9_dialog_content = "그 책 재미있을 것 같은데? 나도 좀 보여줄래?",
  ui_story_5028_50280301_10_dialog_content = "쉿──!",
  ui_story_5028_50280301_11_dialog_content = "에이, 진짜! 완벽한 내레이션이었는데 너 때문에 끊겨버렸잖아.",
  ui_story_5028_50280301_12_dialog_content = "루~",
  ui_story_5028_50280301_13_dialog_content = "「내레이션」? 여긴 나랑 너밖에 없잖아.",
  ui_story_5028_50280301_14_dialog_content = "근데 왜 「내레이션」을 하는데?",
  ui_story_5028_50280301_15_dialog_content = "후후, 우리 업계는 룰을 아주 중요시하거든.",
  ui_story_5028_50280301_16_dialog_content = "타깃으로 삼은 환상동물과 접촉하기 전에 반드시 관련 생태 정보를 복습해야 돼.",
  ui_story_5028_50280301_17_dialog_content = "특히 드라코리온 같은 희귀 환상동물이라면 출몰 가능성이 있는 곳을\n더 면밀히 조사해야지.",
  ui_story_5028_50280301_18_dialog_content = "그럼 일할 때도 더 의미가 있고, 돌발 상황이 생겨도 잘 대처할 수 있다구!",
  ui_story_5028_50280301_19_dialog_content = "루루!",
  ui_story_5028_50280301_20_dialog_content = "...좀 걱정되는데... 너 사실 그냥 잘 몰라서 복습한 거 아냐?",
  ui_story_5028_50280301_21_dialog_content = "크흠, 걱정할 필요 없어. 피아가 이미 꼼꼼하게 조사해 놨으니까.\n드라코리온은 거의 100% 나타날 거야.",
  ui_story_5028_50280301_22_dialog_content = "「매나 독수리 같은 씩씩한 날개...」",
  ui_story_5028_50280301_23_dialog_content = "그건 아까 했어. 또 복습할 필요는 없잖아?",
  ui_story_5028_50280301_24_dialog_content = "쉿! 나 방해하지 마.",
  ui_story_5028_50280301_25_dialog_content = "지금 사부가 개발새발로 써둔 글씨를 읽는 것만으로도 충분히 힘드니까!",
  ui_story_5028_50280301_26_dialog_content = "아... 그 노트가 너희 사부의 「유품」이야...?",
  ui_story_5028_50280301_27_dialog_content = "「웃픈」? 무슨 소리야? 아무튼 조용히 좀 있어.\n지금부터 중요한 부분이니까.",
  ui_story_5028_50280301_28_dialog_content = "「드라코리온은 매우 신기한 동물로, 하늘에 이상할 정도로 집착을 보인다.」",
  ui_story_5028_50280301_29_dialog_content = "「태어난 새끼의 생명을 위협할 생물이 근처에 나타나거나 하지 않는 한,\n출산 때조차 쉽게 땅 위로 내려오려 하지 않는다.」",
  ui_story_5028_50280301_30_dialog_content = "「위협이 발생하면 녀석은 분노의 벼락을 소환하고,\n동시에 날카로운 손톱으로 덮쳐오는 적을 찢어 버린다.」",
  ui_story_5028_50280301_31_dialog_content = "「하지만 정작 공중에서 낳은 알이 안전하게 떨어져서,\n새끼가 무사히 성장하는지는 전혀 관심을 가지지 않는다.」",
  ui_story_5028_50280301_32_dialog_content = "「새끼가 홀로 위험투성이의 세계를 마주하게 하는 것.\n그것은 어쩌면 이 창공의 지배자가 후대를 선별하는 방식일지도 모른다.」",
  ui_story_5028_50280301_33_dialog_content = "「그러한 이유 때문에 드라코리온의 개체수는 매우 적다...」",
  ui_story_5028_50280301_34_dialog_content = "어쩐지, 드라코리온 알을 안전하게 부화시키는 시련을 넣은 이유가 있었구나.",
  ui_story_5028_50280301_35_dialog_content = "환상동물 본연의 습성을 중요시하는 것도 물론 중요하지만,\n가끔은 녀석들이 건강하게 자랄 수 있도록 손을 내미는 것도 필요해.",
  ui_story_5028_50280301_36_dialog_content = "그래! 이런 시련이라면 정말 환상동물 마스터라는 느낌이네!",
  ui_story_5028_50280301_37_dialog_content = "루~",
  ui_story_5028_50280301_38_dialog_content = "그거 너무 위험한 거 아냐?! 난 빠질게!",
  ui_story_5028_50280301_39_dialog_content = "자, 잠깐만! 그렇게 매정하게 가지 말아줘!",
  ui_story_5028_50280301_40_dialog_content = "루우우!",
  ui_story_5028_50280301_41_dialog_content = "아하하, 사부의 노트에 적힌 대로라면, 드라코리온의 알은 땅에 안전하게\n착지하는 순간 곧바로 부화할 거야.",
  ui_story_5028_50280301_42_dialog_content = "그러니까 우린 알이 무사히 땅에 내려오는 것만 도와주면 돼!",
  ui_story_5028_50280301_43_dialog_content = "그렇게 간단하다고...?\n근데 아까 내레이션에서 말한 그 드래곤은 엄청 무서운 녀석 같던데?",
  ui_story_5028_50280301_44_dialog_content = "그럼 전문가인 너희들이 보기에 드라코리온의 위험도는 몇 점 정도인데?",
  ui_story_5028_50280301_45_dialog_content = "아마 한 50점 정도일까나?",
  ui_story_5028_50280301_46_dialog_content = "그렇구나. 그럼 중간 정도인 모양이네. 조금 안심했어.",
  ui_story_5028_50280301_47_dialog_content = "(어? PlayerName, 이렇게 바로 믿는 거야? 그럼 나도 뭔가 마음이 찔리잖아...)",
  ui_story_5028_50280301_48_dialog_content = "10점... 만점에 말이야...",
  ui_story_5028_50280301_49_dialog_content = "......",
  ui_story_5028_50280301_50_dialog_content = "루...",
  ui_story_5028_50280301_51_dialog_content = "잘 알겠어! 난 이만 갈게!",
  ui_story_5028_50280301_52_dialog_content = "안 돼! 가지 마! 부탁이야!",
  ui_story_5028_50280301_53_dialog_content = "나 아이템도 가지고 왔어. 우리 몸의 냄새를 없애주는 아이템이야!",
  ui_story_5028_50280301_54_dialog_content = "이것만 있으면 절대 문제없어. 노트에도 쓰여 있다구.\n드라코리온은 눈이 너무 나빠서 시력으로는 우리를 찾을 수 없어!",
  ui_story_5028_50280301_55_dialog_content = "휴...",
  ui_story_5028_50280301_56_dialog_content = "좀 더 안전한 방법은 없어?",
  ui_story_5028_50280301_57_dialog_content = "예를 들면 스카이워커를 탄 채로 아래에서 알을 받는다거나 말이야.",
  ui_story_5028_50280301_58_dialog_content = "이론상으로는 가능해. 근데 문제가 하나 있어.",
  ui_story_5028_50280301_59_dialog_content = "드라코리온의 공격을 받고 싶지 않다면 우선 알아둬야 할 게 있어...\n스카이워커는... 수컷이야? 아니면 암컷이야?",
  ui_story_5028_50280301_60_dialog_content = "......",
  ui_story_5028_50280301_61_dialog_content = "......",
  ui_story_5028_50280301_62_dialog_content = "......루?",
  ui_story_5028_50280301_63_dialog_content = "그 질문은 답하기 좀 많이 어려운데...",
  ui_story_5028_50280301_64_dialog_content = "그냥 아까 내가 한 말은 잊어줘...",
  ui_story_5028_50280301_65_dialog_content = "넌 전문가니까, 그럼 아무래도... 아마... 어쩔 수 없이...\n네가 생각한 방식대로 하는 수밖에 없을 것 같네.",
  ui_story_5028_50280301_66_dialog_content = "걱정 마! 이 환상동물 마스터 피아 님의 솜씨를 보여줄 테니까!",
  ui_story_5028_50280301_67_dialog_content = "루~",
  ui_story_5028_50280301_68_dialog_content = "후... 후... 으엣취!",
  ui_story_5028_50280301_69_dialog_content = "이 냄새 제거 약... 왠지 어디서 맡아본 냄새가 나는 같아.",
  ui_story_5028_50280301_70_dialog_content = "그래도 방충 효과는 탁월하네.\n풀숲 안에 있는데도 벌레들이 우릴 피하고 있어.",
  ui_story_5028_50280301_71_dialog_content = "루~",
  ui_story_5028_50280301_72_dialog_content = "헤헤, 이건 키아로의 분비물로 만든 거야~ 효과가 끝내줘!",
  ui_story_5028_50280301_73_dialog_content = "풉──!",
  ui_story_5028_50280301_74_dialog_content = "왜 미리 말 안 했어?!",
  ui_story_5028_50280301_75_dialog_content = "왠지 온몸이 간지러운 것 같잖아... 뭔가 해로운 건 아니겠지?",
  ui_story_5028_50280301_76_dialog_content = "괜찮아. 나도 많이 발랐거든.",
  ui_story_5028_50280301_77_dialog_content = "봐, 이건 점성도 있고 보습 효과도 있어. 피부에 아주 좋다구.",
  ui_story_5028_50280301_78_dialog_content = "난 평소에 키아로의 분비물로 화장품을 만들어서 쓰고 있어.",
  ui_story_5028_50280301_78X_dialog_content = "그래서 하루 종일 조사를 다녀도 피부 상태는 항상 최고라니까.",
  ui_story_5028_50280301_79_dialog_content = "루루~",
  ui_story_5028_50280301_80_dialog_content = "쉿...! 뭔가 있어.",
  ui_story_5028_50280301_81_dialog_content = "드라코리온인가?",
  ui_story_5028_50280301_82_dialog_content = "응, 드라코리온은 출산이 가까워지면 되도록 소리를 안 내려고 하고,\n자기가 안전하다고 생각하는 곳으로 날아가거든.",
  ui_story_5028_50280301_83_dialog_content = "그래도 난 알 수 있어. 공기를 부채질하는 이 소리... 분명히 녀석이야.",
  ui_story_5028_50280301_84_dialog_content = "<color=#e8d9bb>스스슥...</color>",
  ui_story_5028_50280301_85_dialog_content = "음... 난 드라코리온 날갯짓 소리는 들어본 적 없지만...\n이 소리는 왠지 저쪽 풀숲에서 들리는 것 같은데?",
  ui_story_5028_50280301_86_dialog_content = "에이, 또 어떤 녀석이 방해하는 거야?",
  ui_story_5028_50280301_87_dialog_content = "키아로, 가서 쫓아내 버려!",
  ui_story_5028_50280301_88_dialog_content = "루!",
  ui_story_5028_50280301_89_dialog_content = "PlayerName, 정말 안 들려? 현악기의 현을 튕기는 소리 말이야.",
  ui_story_5028_50280301_90_dialog_content = "<color=#e8d9bb>스슥, 스슥, 스슥...</color>",
  ui_story_5028_50280301_91_dialog_content = "...루!",
  ui_story_5028_50280301_92_dialog_content = "현악기? 그런 거 안 들리는데... 키아로랑 풀이 흔들리는 소리밖에 안 들려.",
  ui_story_5028_50280301_93_dialog_content = "루! 루루!",
  ui_story_5028_50280301_94_dialog_content = "이 바보! 내가 머리카락이라도 뽑아서 소리를 들려줘야겠어?",
  ui_story_5028_50280301_95_dialog_content = "<size=45>루──!</size>",
  ui_story_5028_50280301_96_dialog_content = "키아로! 시끄러워!",
  ui_story_5028_50280301_97_dialog_content = "크아아──!",
  ui_story_5028_50280301_98_dialog_content = "암귀다!",
  ui_story_5028_50280301_99_dialog_content = "하필 이럴 때... 만약 출산이 임박한 드라코리온한테 들킨다면... 우린 전부 끝장이야!",
  ui_story_5028_50280301_100_dialog_content = "PlayerName, 얼른 해치우자!",
  ui_story_5028_50280301_101_dialog_content = "알았어, 가자!",
  ui_story_5028_50280301_102_dialog_content = "루!",
  ui_story_5028_50280302_1_dialog_content = "일단은 해치웠네.",
  ui_story_5028_50280302_2_dialog_content = "냄새 제거 약을 바르면 암귀한테 들킬 리가 없는데...",
  ui_story_5028_50280302_3_dialog_content = "아, PlayerName, 너 혹시 암귀를 끌어당기는 장치 같은 거 아냐?",
  ui_story_5028_50280302_4_dialog_content = "암귀의 눈에 넌 등대처럼 빛나고, 엄청 매력적이라든지...",
  ui_story_5028_50280302_5_dialog_content = "그래서 나방이 불을 향해 달려드는 것처럼 따라오는 거 아닐까?",
  ui_story_5028_50280302_6_dialog_content = "왠지 생각해 보니까 정말 그럴지도 모르겠네...",
  ui_story_5028_50280302_7_dialog_content = "바다, 설산, 사막, 유적... 어딜 가도 암귀가 갑자기 나타났거든.",
  ui_story_5028_50280302_8_dialog_content = "마치 명탐정이 가는 곳마다 수수께끼의 살인사건이 발생하는 것처럼 말이야.",
  ui_story_5028_50280302_9_dialog_content = "<size=30>사부... 역시 다른 꿍꿍이가 있었어...</size>",
  ui_story_5028_50280302_10_dialog_content = "뭐?",
  ui_story_5028_50280302_11_dialog_content = "됐어! 다행히 드라코리온이 아직 우릴 못 발견한 것 같아.\n아마 곧 출산이 시작될 거야.",
  ui_story_5028_50280302_12_dialog_content = "녀석이 고도를 낮추고 있으니까 우리도 숨자.",
  ui_story_5028_50280302_13_dialog_content = "녀석이 보여! 근데 저 높이에서 알이 떨어지면 분명히 깨지지 않을까?",
  ui_story_5028_50280302_14_dialog_content = "대체 무슨 습성이 그래?\n그래서야 새끼를 낳아봤자 멸종하지 않는 게 이상하잖아!",
  ui_story_5028_50280302_15_dialog_content = "아스트라 대륙의 동물학자들은 다들 너랑 비슷한 의문을 가지고 있어.",
  ui_story_5028_50280302_16_dialog_content = "근데 환상동물이라는 건 그런 거야.\n녀석들의 습성은 합리성을 기준으로 생각할 수 없어!",
  ui_story_5028_50280302_17_dialog_content = "그래서 지금은... 이대로는 안 돼. 뭔가 방법을 생각해야 돼.",
  ui_story_5028_50280302_18_dialog_content = "루!",
  ui_story_5028_50280302_19_dialog_content = "피아? 뭘 하려고?",
  ui_story_5028_50280302_20_dialog_content = "나무 위에서 알을 받을 거야!",
  ui_story_5028_50280302_21_dialog_content = "바보짓하지 마! 나무가 높긴 하지만 그거 가지곤 어림도 없어!",
  ui_story_5028_50280302_22_dialog_content = "게다가 나무에 올라가도 그물로 알을 받을 수가 없잖아!",
  ui_story_5028_50280302_23_dialog_content = "휴, 그럼 어떻게 해... 이래서는 녀석을 도와줄 수가 없어...",
  ui_story_5028_50280302_24_dialog_content = "드라코리온은 10여 년에 한 번밖에 알을 낳지 않아.\n정말 희귀한 멸종위기종이라구.",
  ui_story_5028_50280302_25_dialog_content = "사부한테 확실한 정보도 받았는데... 녀석을 지켜줄 수 없다니... 사부...",
  ui_story_5028_50280302_26_dialog_content = "루...",
  ui_story_5028_50280302_27_dialog_content = "...방법이 있어!",
  ui_story_5028_50280302_28_dialog_content = "응? 뭔데? 설마...",
  ui_story_5028_50280302_29_dialog_content = "정말 괜찮겠어?",
  ui_story_5028_50280302_30_dialog_content = "어쩔 수 없잖아. 시도해 볼 수밖에 없어!",
  ui_story_5028_50280302_31_dialog_content = "...PlayerName, 스카이워커호를 사용해서 도와준다니 정말 고마워!",
  ui_story_5028_50280302_32_dialog_content = "한 생명이 눈앞에서 사라지는 걸 보고만 있을 순 없잖아!",
  ui_story_5028_50280302_33_dialog_content = "드라코리온이 스카이워커를 좋아할진 모르겠지만... 시도해 볼 만해!",
  ui_story_5028_50280302_34_dialog_content = "캬오오오──",
  ui_story_5028_50280302_35_dialog_content = "PlayerName! 드라코리온이 스카이워커호에 관심이 많은 것 같아!",
  ui_story_5028_50280302_36_dialog_content = "왠지 스카이워커호를 친구로 생각하는 것 같아. 곧바로 다가오고 있어.",
  ui_story_5028_50280302_37_dialog_content = "좋아, 조금만 더 가까이 가면... 그물로 알을...",
  ui_story_5028_50280302_38_dialog_content = "(어라, 저 녀석 발목에 있는 건 뭐지? 뭐... 됐어, 그런 거 신경 쓸 시간이 없어.)",
  ui_story_5028_50280302_39_dialog_content = "루! 루!",
  ui_story_5028_50280302_40_dialog_content = "캬오오오──",
  ui_story_5028_50280302_41_dialog_content = "피아! 드라코리온이 다가왔어!",
  ui_story_5028_50280302_42_dialog_content = "알겠어. 조금만 더 가까워지게 두자. 그다음은 나랑 키아로한테 맡겨!",
  ui_story_5028_50280302_43_dialog_content = "셋...",
  ui_story_5028_50280302_44_dialog_content = "둘...",
  ui_story_5028_50280302_45_dialog_content = "하나!",
  ui_story_5028_50280302_46_dialog_content = "피아!",
  ui_story_5028_50280302_47_dialog_content = "루!",
  ui_story_5028_50280302_48_dialog_content = "!",
  ui_story_5028_50280302_49_dialog_content = "해냈어!",
  ui_story_5028_50280302_50_dialog_content = "눈부셔... 내 품에서 부화하는 거야?",
  ui_story_5028_50280302_51_dialog_content = "뽀...",
  ui_story_5028_50280302_52_dialog_content = "뽀삐?",
  ui_story_5028_50280302_53_dialog_content = "루루~",
  ui_story_5028_50280302_54_dialog_content = "귀, 귀여워!",
  ui_story_5028_50280302_55_dialog_content = "이렇게 작은데, 저렇게 커다랗게 자라는 거야?",
  ui_story_5028_50280302_56_dialog_content = "정말 신기해. 역시 <color=#FFB400>희귀종</color>이라고 불릴 만하네...",
  ui_story_5028_50280302_57_dialog_content = "피아! 잘 됐어?",
  ui_story_5028_50280302_58_dialog_content = "응! PlayerName 너랑 스카이워커호 덕분에 드라코리온이 잘 부화했어!",
  ui_story_5028_50280302_59_dialog_content = "루~",
  ui_story_5028_50280302_60_dialog_content = "키아로도 고마워~",
  ui_story_5028_50280302_61_dialog_content = "루루~",
  ui_story_5028_50280302_62_dialog_content = "뽀삐~!",
  ui_story_5028_50280302_63_dialog_content = "축하 인사는 나중에 하자!",
  ui_story_5028_50280302_64_dialog_content = "드라코리온이 스카이워커를 꽉 잡고 놓아주질 않아... 이래서는 돌아갈 수가 없어!",
  ui_story_5028_50280302_65_dialog_content = "앗, 말하는 걸 깜빡했네.",
  ui_story_5028_50280302_65X_dialog_content = "드라코리온은 생존에 성공한 새끼에게 강렬한 보호욕을 갖고 있어.\n아마 우리가 아이를 훔쳤다고 생각하는 걸지도 몰라!",
  ui_story_5028_50280302_66_dialog_content = "뭐야?! 그럼 우리 다 끝장 아냐?!",
  ui_story_5028_50280302_67_dialog_content = "아, 아니야. 녀석의 울음소리에 적의는 없어.",
  ui_story_5028_50280302_68_dialog_content = "이 소리... 설마 스카이워커호를 좋아하게 된 건 아니겠지?",
  ui_story_5028_50280302_69_dialog_content = "뭐라고?!",
  ui_story_5028_50280302_70_dialog_content = "...PlayerName, 여기도 없어.",
  ui_story_5028_50280302_71_dialog_content = "어? 너 레비지? 왜 이런 데서 돌아다니고 있어?",
  ui_story_5028_50280302_72_dialog_content = "아, 스모키.",
  ui_story_5028_50280302_73_dialog_content = "난 아이테르를 찾고 있어.",
  ui_story_5028_50280302_74_dialog_content = "저번에 PlayerName하고 이 근처에서 야구를 했어.",
  ui_story_5028_50280302_75_dialog_content = "근데 놀다가 아이테르가 사라져 버렸어.\n편지가 한 통 남아 있었는데, 왠지 납치된 것 같아.",
  ui_story_5028_50280302_76_dialog_content = "하아?",
  ui_story_5028_50280302_77_dialog_content = "방금 뭐라고? PlayerName 그 자식이 납치됐다고?",
  ui_story_5028_50280302_78_dialog_content = "그 편지는?",
  ui_story_5028_50280302_79_dialog_content = "오는 길에 암귀를 때려주다가 잃어버렸어.",
  ui_story_5028_50280302_80_dialog_content = "뭐야, 그게.",
  ui_story_5028_50280302_81_dialog_content = "왠지 궁금한걸. 이번엔 또 누가 운 나쁜 아이테르를 납치했을까.",
  ui_story_5028_50280302_82_dialog_content = "아이테르 찾는 거 좀 도와줘.",
  ui_story_5028_50280302_83_dialog_content = "잃어버리면 바이스랑 그람한테 혼날 거야.",
  ui_story_5028_50280302_84_dialog_content = "응, 어차피 지금은 딱히 할 일도 없으니까, 같이 그 녀석이나 찾지 뭐.",
  ui_story_5028_50280401_1_dialog_content = "시련: 포도 농장의 위기",
  ui_story_5028_50280401_2_dialog_content = "휴우... 휴우...",
  ui_story_5028_50280401_3_dialog_content = "피, 피아... 천천히 좀 가...",
  ui_story_5028_50280401_4_dialog_content = "우리 대체 어디 가는 거야?",
  ui_story_5028_50280401_5_dialog_content = "주변엔 온통 포도나무뿐이잖아. 설마 이번엔 무슨 포도 드래곤을 돕는 건 아니겠지?",
  ui_story_5028_50280401_6_dialog_content = "루.",
  ui_story_5028_50280401_7_dialog_content = "쉿, 피아는 지금 새끼 드라코리온 관찰일지를 정리하고 있다구.",
  ui_story_5028_50280401_8_dialog_content = "이렇게 성장이 빠를 줄은 몰랐어.\n눈 깜짝할 사이에 키아로보다 커져서 혼자 살 수 있게 됐잖아.",
  ui_story_5028_50280401_9_dialog_content = "휴, 이제 곧 자기 서식지를 찾으러 갈 거야.",
  ui_story_5028_50280401_9X_dialog_content = "어릴 때 귀여운 모습도 많이 못 봤는데...",
  ui_story_5028_50280401_10_dialog_content = "그 드라코리온한테 겨우 도망쳐 나온 것만으로도 다행이라고 생각해야지!",
  ui_story_5028_50280401_11_dialog_content = "난 이제 진짜 못 걷겠어. 잠깐만 쉬자.",
  ui_story_5028_50280401_12_dialog_content = "에이~ 벌써 쉬는 거야? 이제 곧 의뢰 지점에 도착할 거란 말이야.",
  ui_story_5028_50280401_13_dialog_content = "정말 어쩔 수가 없네. 자, 얼른 입 벌리고 이거 마셔~",
  ui_story_5028_50280401_14_dialog_content = "뭐, 뭐야?! 안 마셔!",
  ui_story_5028_50280401_15_dialog_content = "자~ 착하지~",
  ui_story_5028_50280401_16_dialog_content = "오지 마!",
  ui_story_5028_50280401_17_dialog_content = "키아로, PlayerName 붙잡고 있어~",
  ui_story_5028_50280401_18_dialog_content = "루루~",
  ui_story_5028_50280401_19_dialog_content = "우웁! 꼴깍꼴깍꼴깍!",
  ui_story_5028_50280401_20_dialog_content = "매워! 아, 아니지... 뭔가 우유 같은 맛도 느껴지는데...\n아니, 잠깐만... 갑자기 속이 싸늘해!",
  ui_story_5028_50280401_21_dialog_content = "도대체 뭘 먹인 거야?!",
  ui_story_5028_50280401_22_dialog_content = "불꽃소의 젖에 달달초의 뿌리로 만든 즙을 섞은 피아 특제 에너지 드링크야!",
  ui_story_5028_50280401_23_dialog_content = "거기다 특별히 북방에서만 얻을 수 있는 스노우 민트로 맛을 냈어.\n그래서 시원시원하고 정신이 바짝 드는 거야.",
  ui_story_5028_50280401_24_dialog_content = "참, 이건 키아로한테 먹인 다음에 키아로의 배 속에서 만들어진 거야.\n손으로 섞는 것보다 훨씬 잘 섞이거든.",
  ui_story_5028_50280401_25_dialog_content = "이것만 마시면 PlayerName 너도 호랑이 기운이 날 거야!",
  ui_story_5028_50280401_25X_dialog_content = "전부 귀한 재료들이라구.",
  ui_story_5028_50280401_26_dialog_content = "루~",
  ui_story_5028_50280401_27_dialog_content = "우욱! 키아로... 도대체 왜 그런 걸 돕는 거야?!",
  ui_story_5028_50280401_28_dialog_content = "루?",
  ui_story_5028_50280401_29_dialog_content = "그리고 너! 피아!",
  ui_story_5028_50280401_30_dialog_content = "응?",
  ui_story_5028_50280401_31_dialog_content = "사적으로 약을 만들어서 나한테 실험까지 하다니...\n이건 중대한 위법 행위라고!",
  ui_story_5028_50280401_32_dialog_content = "뭐, 뭐야? 어째서?!",
  ui_story_5028_50280401_33_dialog_content = "그, 그럼 이 약에 대해 절대 아무한테도 말하지 마!\n이렇게 어린 나이에 감옥 같은 데 가고 싶진 않아...",
  ui_story_5028_50280401_34_dialog_content = "감옥에 가기 싫으면 앞으로 나한테 갑자기 이상한 걸 먹이질 마!",
  ui_story_5028_50280401_35_dialog_content = "알았어... 좋은 뜻으로 준 건데...",
  ui_story_5028_50280401_36_dialog_content = "어? 근데 이거... 왠지 정말로 효과가 있는 것 같네?",
  ui_story_5028_50280401_37_dialog_content = "체력이 한 80% 정도는 돌아온 느낌이야.",
  ui_story_5028_50280401_38_dialog_content = "거 봐! 역시 좋지? 잠깐만 기다려. 이번 성분의 조합을 기록해 둬야겠어.",
  ui_story_5028_50280401_39_dialog_content = "뭐?! 그럼 남한테 처음 먹인 거야? 난 이 세상 하나뿐인 아이테르라고!",
  ui_story_5028_50280401_40_dialog_content = "만약 이런 곳에서 이상한 걸 먹어서 쓰러지거나 한다면...!",
  ui_story_5028_50280401_41_dialog_content = "연재 중단되는 소설의 주인공보다 더 비참하잖아!",
  ui_story_5028_50280401_42_dialog_content = "아하하, 처음일 리가 없잖아. 저기, 몸은 좀 어때?",
  ui_story_5028_50280401_42X_dialog_content = "키아로한테 좀 더 받을래?",
  ui_story_5028_50280401_43_dialog_content = "루?!",
  ui_story_5028_50280401_44_dialog_content = "절대 싫어! 너나 마셔!",
  ui_story_5028_50280401_45_dialog_content = "이제 다시는 나한테 이상한 거 먹거나 마시게 하지 마!",
  ui_story_5028_50280401_46_dialog_content = "아이테르가 에너지 드링크를 무서워하면 어떡해. PlayerName~ 얼레리꼴레리~",
  ui_story_5028_50280401_47_dialog_content = "나중에 스카이워커를 구할 때 네 도움이 필요하지만 않았어도\n지금 당장 널 혼내줬을 거라고.",
  ui_story_5028_50280401_48_dialog_content = "헤헤, 걱정 마. 우린 드라코리온한테서 무사히 도망쳤잖아?",
  ui_story_5028_50280401_49_dialog_content = "드라코리온은 스카이워커호를 꽤 좋아하는 것 같으니까,\n위험한 짓은 안 할 거야.",
  ui_story_5028_50280401_50_dialog_content = "말은 쉽지. 스카이워커가 드라코리온한테 잡혀서 저 높은 곳을\n왔다 갔다 하는 것만으로도 이미 충분히 심각하잖아.",
  ui_story_5028_50280401_51_dialog_content = "크흠.",
  ui_story_5028_50280401_52_dialog_content = "으아악!",
  ui_story_5028_50280401_53_dialog_content = "누, 누구야?! 암귀? 야수? 요괴?",
  ui_story_5028_50280401_54_dialog_content = "놀래켜서 미안하구나... 난 그냥 오로리안이야...",
  ui_story_5028_50280401_55_dialog_content = "이쪽이 바로 비크 씨의 제자님인가?",
  ui_story_5028_50280401_56_dialog_content = "비크?",
  ui_story_5028_50280401_57_dialog_content = "(이런 자상해 보이는 아저씨한테 놀라다니... 이래서는 안 돼, 피아. 정신 차려!)",
  ui_story_5028_50280401_58_dialog_content = "아, 아저씨, 안녕! 내가 바로 비크의 제자, 환상동물 마스터 피아야.",
  ui_story_5028_50280401_59_dialog_content = "피아, 넌 아직 공부 중인 거 아니었어?",
  ui_story_5028_50280401_60_dialog_content = "공부 중이라도 마스터는 마스터야!",
  ui_story_5028_50280401_61_dialog_content = "오오! 내가 실례했구나. 마스터를 못 알아보다니.",
  ui_story_5028_50280401_62_dialog_content = "저기, 사부는...",
  ui_story_5028_50280401_63_dialog_content = "사실 난 한때 백야성의 경비병이었단다. 전쟁에도 몇 번이나 나갔었지.",
  ui_story_5028_50280401_64_dialog_content = "이 무릎 좀 봐라. 이건 그때 솔라드 전하와 함께 암귀에 맞서 싸우다 생긴 상처다.",
  ui_story_5028_50280401_65_dialog_content = "아저씨는...",
  ui_story_5028_50280401_66_dialog_content = "아! 근데 난 계속 소설가가 되고 싶었거든. 그래서 근무 시간에 몰래 소설을 썼지.",
  ui_story_5028_50280401_67_dialog_content = "그러다 상관한테 들켜서 조기 퇴역을 하고 말았지 뭐야.\n그 뒤엔 여기 보내져서 포도를 키우게 되었단다.",
  ui_story_5028_50280401_68_dialog_content = "저기, 내 말 좀...",
  ui_story_5028_50280401_69_dialog_content = "그래도 난 유명한 책을 많이 썼단다!",
  ui_story_5028_50280401_69X_dialog_content = "대표작으로는 《기사는 이미 죽었다》, 《JUDGE×FAMILY》,\n그리고 《마스크위리어 VICE》 등이 있지.",
  ui_story_5028_50280401_70_dialog_content = "아저씨! 됐으니까 일단 의뢰 내용부터 빨리 말해줘!",
  ui_story_5028_50280401_71_dialog_content = "아! 의뢰? 그렇지. 미안하구나. 지금 바로 말해주마.",
  ui_story_5028_50280401_72_dialog_content = "쳇... 흥! 칫! 허접 사부!",
  ui_story_5028_50280401_73_dialog_content = "나보고 고작 한밤중에 저 바보 아저씨 대신 포도밭 감시나 하라고\n멍청한 비둘기한테 편지를 맡긴 거야?!",
  ui_story_5028_50280401_74_dialog_content = "피아는 앞으로 대단한 환상동물 마스터가 될 거라구!\n좀도둑이나 잡는 경비원이 아니란 말이야!",
  ui_story_5028_50280401_75_dialog_content = "야, 일어나! 교대할 시간이야.",
  ui_story_5028_50280401_76_dialog_content = "침까지 흘리면서 자고 있잖아?",
  ui_story_5028_50280401_77_dialog_content = "일──어──나──!",
  ui_story_5028_50280401_78_dialog_content = "으악?! 도, 도둑이 나타났어?",
  ui_story_5028_50280401_79_dialog_content = "그래, 도둑이 네 스카이워커호를 저 하늘의 구름 속에서 빼앗아 가버렸다구.",
  ui_story_5028_50280401_80_dialog_content = "뭐? 진짜?",
  ui_story_5028_50280401_81_dialog_content = "뻥이지! 네가 보초 설 차례야. 피곤해 죽겠어.",
  ui_story_5028_50280401_82_dialog_content = "<color=#e8d9bb>한참 뒤</color>",
  ui_story_5028_50280401_83_dialog_content = "...휴.",
  ui_story_5028_50280401_84_dialog_content = "하이~",
  ui_story_5028_50280401_85_dialog_content = "음... 으음?",
  ui_story_5028_50280401_86_dialog_content = "하이~ 우적우적.",
  ui_story_5028_50280401_87_dialog_content = "피, 피아!",
  ui_story_5028_50280401_88_dialog_content = "으, 으햐?",
  ui_story_5028_50280401_89_dialog_content = "루우...?",
  ui_story_5028_50280401_90_dialog_content = "얼른 일어나!",
  ui_story_5028_50280401_91_dialog_content = "포도가 다 털렸어!",
  ui_story_5028_50280401_92_dialog_content = "뭐햐앙?!",
  ui_story_5028_50280401_93_dialog_content = "범인은 저쪽으로 도망갔어! 얼른 쫓아가자!",
  ui_story_5028_50280401_94_dialog_content = "이 치사한 자식!",
  ui_story_5028_50280401_95_dialog_content = "순식간에 숲으로 도망쳐 버려서 안 보이잖아...",
  ui_story_5028_50280401_96_dialog_content = "어쩔 수 없지. 애초에 따라잡을 수가 없었어.",
  ui_story_5028_50280401_97_dialog_content = "한패가 있을지도 모르니까 얼른 돌아가서 포도 농장을 살펴보자.",
  ui_story_5028_50280401_98_dialog_content = "...푸훕, 아하하하!",
  ui_story_5028_50280401_99_dialog_content = "...피아? 왜 그래? 범인을 못 잡긴 했지만...\n그렇다고 벌써 헛웃음을 치긴 너무 이른 거 아냐?",
  ui_story_5028_50280401_100_dialog_content = "그, 그게 아니라... 갑자기 썰렁한 개그가 생각났거든.",
  ui_story_5028_50280401_101_dialog_content = "뭐?",
  ui_story_5028_50280401_102_dialog_content = "어떤 사람이 그랬어.\n「해가 쨍쨍한 레디젤 사막에선 반드시 샌드버그를 만난다...」",
  ui_story_5028_50280401_103_dialog_content = "그럼 다음 말은... 「한밤중에 숲속에 들어간 아이테르는 반드시....」",
  ui_story_5028_50280401_104_dialog_content = "크아아──!",
  ui_story_5028_50280401_105_dialog_content = "그건 또 무슨 소리야?! 하나도 재미없는 데다가 암귀까지 나왔잖아! 얼른 뛰어!",
  ui_story_5028_50280401_106_dialog_content = "으앗! 진짜로 나왔어?! 아이테르 바보! 빨리도 도망가네!",
  ui_story_5028_50280401_107_dialog_content = "같이 가!",
  ui_story_5028_50280402_1_dialog_content = "휴, 후우!",
  ui_story_5028_50280402_2_dialog_content = "이 암귀들... 왜 이렇게 끈질긴 거야?",
  ui_story_5028_50280402_3_dialog_content = "캬아악──!",
  ui_story_5028_50280402_4_dialog_content = "조심해!",
  ui_story_5028_50280402_5_dialog_content = "꺄앗!",
  ui_story_5028_50280402_6_dialog_content = "괘, 괜찮아... 고마워, PlayerName.",
  ui_story_5028_50280402_7_dialog_content = "안 돼! 노트가 암귀 때문에 날아가 버렸어!",
  ui_story_5028_50280402_8_dialog_content = "피아! 암귀가 더 많아지기 전에 빨리 노트부터 주워! 이쪽은 나한테 맡기고!",
  ui_story_5028_50280402_9_dialog_content = "그치만...",
  ui_story_5028_50280402_10_dialog_content = "얼른!",
  ui_story_5028_50280402_11_dialog_content = "캬악──!",
  ui_story_5028_50280402_12_dialog_content = "암귀가 곧바로 피아를 쫓아가 버렸잖아... 난 아예 신경도 안 쓰는 거야?",
  ui_story_5028_50280402_13_dialog_content = "(기회를 노려서 암귀의 약점을 정확히 조준하는 거야...)",
  ui_story_5028_50280402_14_dialog_content = "캬악──!",
  ui_story_5028_50280402_15_dialog_content = "(안 돼! 이러다 피아가 포위되면 위험해! 더는 못 기다려!)",
  ui_story_5028_50280402_16_dialog_content = "에잇!",
  ui_story_5028_50280402_17_dialog_content = "내가 나설 줄은 몰랐지? 이 빌어먹을 암귀들아!",
  ui_story_5028_50280402_18_dialog_content = "...으으, 아파... 왜 돌처럼 단단한 건데?!",
  ui_story_5028_50280402_19_dialog_content = "캬아악!",
  ui_story_5028_50280402_20_dialog_content = "으악! 역시 너무 무모했어... 얼른 피아를 데리고 도망치자...",
  ui_story_5028_50280402_21_dialog_content = "노트 챙겼어! PlayerName! 얼른 뛰어!",
  ui_story_5028_50280402_22_dialog_content = "휴우... 겨우 뿌리쳤네.",
  ui_story_5028_50280402_23_dialog_content = "PlayerName! 괜찮아?! 왜 팔이 부었어?",
  ui_story_5028_50280402_24_dialog_content = "괜찮아. 아까 암귀한테 달려들 때 부은 거야. 그 자식 엄청 단단하더라고.",
  ui_story_5028_50280402_25_dialog_content = "미안해... 나 때문에... 내가 금방 약 발라줄게!",
  ui_story_5028_50280402_26_dialog_content = "괜찮아. 피아의 사부가 남긴 유품을 되찾을 수 있었으니까, 그걸로 됐어.",
  ui_story_5028_50280402_27_dialog_content = "유...유품?",
  ui_story_5028_50280402_28_dialog_content = "아, 그, 그거... 내가 우는 척했을 때 말한 거 말이지?",
  ui_story_5028_50280402_29_dialog_content = "미안! 사실 사부는 멀쩡히 살아있어...",
  ui_story_5028_50280402_30_dialog_content = "하아?",
  ui_story_5028_50280402_31_dialog_content = "약은 발랐고, 붕대도 잘 감았어. 부은 건 금방 빠질 거야.",
  ui_story_5028_50280402_32_dialog_content = "<size=30>아무튼... 미안해...</size>",
  ui_story_5028_50280402_33_dialog_content = "뭐라고?",
  ui_story_5028_50280402_34_dialog_content = "<size=30>미안하다고...</size>",
  ui_story_5028_50280402_35_dialog_content = "피아, 목소리가 너무 작아서 무슨 말인지 안 들려.",
  ui_story_5028_50280402_36_dialog_content = "휴우...",
  ui_story_5028_50280402_37_dialog_content = "<size=45>미안해! 미안해! 미안해! 피아가 사과할게!</size>",
  ui_story_5028_50280402_38_dialog_content = "으앗! 가, 갑자기 왜 그래?",
  ui_story_5028_50280402_39_dialog_content = "미안해... 피아가 거짓말했어. 사과할게... 반성도 할게.",
  ui_story_5028_50280402_40_dialog_content = "그치만 그 허접 사부는 항상 날 골탕 먹이거나 부려 먹기만 한다구.",
  ui_story_5028_50280402_41_dialog_content = "PlayerName 너처럼 진심으로 자상하게 도와주는 일 같은 건 전혀 없어...",
  ui_story_5028_50280402_42_dialog_content = "그땐 초조해서 거짓말을 해버렸지만...\n친구가 되고 싶었던 건 진심이야! 진짜라구!",
  ui_story_5028_50280402_43_dialog_content = "피아가 거짓말한 거 용서해 줘...",
  ui_story_5028_50280402_44_dialog_content = "그래도 허접 사부는 뻥 터져버리라고 해! 흥!",
  ui_story_5028_50280402_45_dialog_content = "으엣취──!",
  ui_story_5028_50280402_46_dialog_content = "누가 또 내 생각을 하고 있나? 이번엔 어떤 녀석이지?",
  ui_story_5028_50280402_47_dialog_content = "왠지 안 좋은 예감이 드는걸.",
  ui_story_5028_50280402_48_dialog_content = "휴, 알겠어. 나도 그때 네가 우는 척하는 건 알고 있었어.\n그래도 그냥 내버려 둘 수는 없었던 거야.",
  ui_story_5028_50280402_49_dialog_content = "근데 방금 그 말은 조금 심했어.",
  ui_story_5028_50280402_50_dialog_content = "사람한테 그런 식으로 말하면 안 돼. 농담이라도 안 돼.",
  ui_story_5028_50280402_51_dialog_content = "이 노트, 글씨는 엉망이지만 내용은 아주 상세해.\n이걸 쓴 사람이 얼마나 정성을 들였는지 알 수 있어.",
  ui_story_5028_50280402_52_dialog_content = "이런 소중한 노트를 너한테 준 걸 보면,\n그 사람은 분명히 널 많이 생각하고 있을 거야.",
  ui_story_5028_50280402_53_dialog_content = "으음... 아, 알았어... 아마 네 말이 맞을 거야.",
  ui_story_5028_50280402_54_dialog_content = "허접 사부라고 해도 죽으라는 건 너무했어.\n사부한테도 이 자리에서 사과할게.",
  ui_story_5028_50280402_55_dialog_content = "앞으로는 다시는 그렇게 말 안 하겠다고 약속할게! 그러니까...",
  ui_story_5028_50280402_56_dialog_content = "...머리 쓰다듬는 거 그만해 줄래?\n우리가 친구인 건 맞지만 그래도 부끄러우니까... 키아로도 보고 있다구!",
  ui_story_5028_50280402_57_dialog_content = "아, 미안 미안, 키 차이 때문에 나도 모르게...",
  ui_story_5028_50280402_58_dialog_content = "응? 지금 내가 꼬마라고 말하고 싶은 거야?",
  ui_story_5028_50280402_59_dialog_content = "크흠, 그건 그렇고... 아무튼 아까 포도 훔친 녀석에 대한 단서는 없어?",
  ui_story_5028_50280402_60_dialog_content = "음, 내가 잘못 본 게 아니라면, 아마 <color=#FFB400>「비카」</color>라는 환상동물일 거야.",
  ui_story_5028_50280402_61_dialog_content = "노트에는 동그란 음식을 좋아한다고 적혀 있어.\n어떤 크기든 한입에 통째로 삼켜 버린대.",
  ui_story_5028_50280402_62_dialog_content = "게다가 몸의 탄력이 좋아서, 삼킨 음식의 크기에 맞춰 몸 크기가 변한다고 해.",
  ui_story_5028_50280402_63_dialog_content = "다리 힘도 강해서 엄청난 속도로 도망칠 수 있지만...",
  ui_story_5028_50280402_64_dialog_content = "사실 그렇게 똑똑하진 않아서, 조금 바보 같은 환상동물이래.",
  ui_story_5028_50280402_65_dialog_content = "공 모양의 음식? 어디 보자...",
  ui_story_5028_50280402_66_dialog_content = "<size=30>이걸로 정말 괜찮을까?</size>",
  ui_story_5028_50280402_67_dialog_content = "<size=30>우리 안에 수박을 넣었을 뿐이잖아... 확실히 수박이 맛있어 보이긴 하지만...</size>",
  ui_story_5028_50280402_68_dialog_content = "<size=30>비카가 정말 이렇게 쉽게 속을까?</size>",
  ui_story_5028_50280402_69_dialog_content = "<size=30>걱정 마. 노트에 적힌 게 사실이라면, 비카는 이렇게 큰 공 모양 음식을\n보고도 그냥 넘어갈 순 없을 거야.</size>",
  ui_story_5028_50280402_70_dialog_content = "<size=30>사부의 노트를 믿는 것처럼, 내 판단도 믿어줘.</size>",
  ui_story_5028_50280402_71_dialog_content = "<size=30>알겠어. 앗, 뭔가 다가오고 있는 것 같아.</size>",
  ui_story_5028_50280402_72_dialog_content = "하이~ 하이~",
  ui_story_5028_50280402_73_dialog_content = "하이?",
  ui_story_5028_50280402_74_dialog_content = "하이~",
  ui_story_5028_50280402_75_dialog_content = "먹었어!",
  ui_story_5028_50280402_76_dialog_content = "루!",
  ui_story_5028_50280402_77_dialog_content = "진짜로 먹었네! 역시 쟨 별로 똑똑하지가 않구나.",
  ui_story_5028_50280402_78_dialog_content = "하이?! 하이?!",
  ui_story_5028_50280402_79_dialog_content = "무서워하지 마. 우린 나쁜 사람이 아냐.",
  ui_story_5028_50280402_80_dialog_content = "하이?",
  ui_story_5028_50280402_81_dialog_content = "저기, 그러니까 이 집 포도 훔쳐 먹는 건 그만해 줄 수 있을까?",
  ui_story_5028_50280402_82_dialog_content = "하이하이?",
  ui_story_5028_50280402_83_dialog_content = "내가 얘기할게.",
  ui_story_5028_50280402_84_dialog_content = "무서워하지 마, 우린 널 해치지 않을 거야.",
  ui_story_5028_50280402_85_dialog_content = "하이...?",
  ui_story_5028_50280402_86_dialog_content = "PlayerName, 우리 문 좀 열어줄래? 괜찮아, 도망가지 않을 테니까.",
  ui_story_5028_50280402_87_dialog_content = "정말 괜찮아? 그럼 연다?",
  ui_story_5028_50280402_88_dialog_content = "하이...",
  ui_story_5028_50280402_89_dialog_content = "뭐? 수박이 맛있었다고? 이런 상황에서도 그런 생각을 하는 거야?",
  ui_story_5028_50280402_90_dialog_content = "하이하이!",
  ui_story_5028_50280402_91_dialog_content = "이 녀석은 어떤 무서운 괴물한테서 도망쳐 온 것 같아.",
  ui_story_5028_50280402_92_dialog_content = "분명히 많이 무서웠을 거야. 불쌍해라.\n그래도 포도를 훔쳐 먹는 건 안 돼.",
  ui_story_5028_50280402_93_dialog_content = "피아, 너 설마...",
  ui_story_5028_50280402_94_dialog_content = "하이~",
  ui_story_5028_50280402_95_dialog_content = "응? 나랑 같이 있으면 안전하다고? 수박도 더 많이 먹을 수 있고?",
  ui_story_5028_50280402_96_dialog_content = "듣기 좋은 말 해 봤자 아무것도 안 나온다구~",
  ui_story_5028_50280402_97_dialog_content = "PlayerName, 우리가 얘를 키우자.\n그럼 더는 농작물을 망치지도 않고, 다른 동물한테 괴롭힘을 당하지도 않을 거야.",
  ui_story_5028_50280402_98_dialog_content = "좋아. 네가 그렇다면 난 불만 없어.",
  ui_story_5028_50280402_99_dialog_content = "키아로, 너도 얘랑 같이 여행하고 싶지?",
  ui_story_5028_50280402_100_dialog_content = "루~",
  ui_story_5028_50280402_101_dialog_content = "좋아, 그럼 이 녀석도 우리의 새로운 동료가 된 거야!",
  ui_story_5028_50280402_102_dialog_content = "이쪽은 다 붙였어.",
  ui_story_5028_50280402_103_dialog_content = "나도 다 붙였어.",
  ui_story_5028_50280402_104_dialog_content = "사람 찾는 벽보 같은 건 큰 도움은 안 되겠지만,\n운이 좋다면 조금은 정보를 얻을 수 있을 거야.",
  ui_story_5028_50280402_105_dialog_content = "...거기 누구야? 나와.",
  ui_story_5028_50280402_106_dialog_content = "후후훗, 다 봤어, 스모키.",
  ui_story_5028_50280402_107_dialog_content = "설마 네가 길에서 벽보나 붙이고 있을 정도로 수준이 떨어질 줄은 몰랐네.",
  ui_story_5028_50280402_108_dialog_content = "게다가 일루미나의 꼬마 친구랑 같이 아르바이트라니.",
  ui_story_5028_50280402_109_dialog_content = "그렇게 돈이 궁하면 내가 좀 빌려줄까?",
  ui_story_5028_50280402_110_dialog_content = "이자라면 「지인 특별가」로 해 줄게.",
  ui_story_5028_50280402_111_dialog_content = "쳇, 말도 많네.",
  ui_story_5028_50280402_112_dialog_content = "야, 레비. 너희 일루미나에서 쓰는 총도 저 녀석 입보다는 느리지?",
  ui_story_5028_50280402_113_dialog_content = "난 총 안 써서 몰라.",
  ui_story_5028_50280402_114_dialog_content = "아이테르가 없어졌어. 그래서 스모키가 찾는 거 도와주고 있어.",
  ui_story_5028_50280402_115_dialog_content = "어머? 별일이라고 해야 하나, 의외면서도 합리적이잖아.",
  ui_story_5028_50280402_116_dialog_content = "근데 PlayerName 그 애를 찾는 거라면 나도 할래.\n뭐든지 너보다 뒤처질 순 없으니까.",
  ui_story_5028_50280402_117_dialog_content = "따라오지 마.",
  ui_story_5028_50280402_118_dialog_content = "넌 병원이나 가서 그 과한 승부욕부터 몇 달 고치고 다시 와.",
  ui_story_5028_50280402_119_dialog_content = "네가 붙었다 하면 항상 일이 귀찮아진다고.\n게다가 넌 아이테르랑 그렇게 친하지도 않잖아?",
  ui_story_5028_50280402_120_dialog_content = "아니면 아이테르를 두고 또 뭔가 꾸미려는 거야?\n네 멍청한 팬클럽에 가입이라도 시킬 생각인가?",
  ui_story_5028_50280402_121_dialog_content = "그건 걱정할 거 없어. 내가 노리는 건 다른 녀석이니까.",
  ui_story_5028_50280402_122_dialog_content = "하, 그 운 좋은 녀석이 대체 누구일까 궁금하네.",
  ui_story_5028_50280402_123_dialog_content = "휴, 난 쓰레기통 뒤에 아이테르가 있나 찾아볼게.",
  ui_story_5028_50280501_1_dialog_content = "시련: 해안의 비밀",
  ui_story_5028_50280501_2_dialog_content = "이 뜨겁고 눈부신 태양...",
  ui_story_5028_50280501_3_dialog_content = "습하면서도 활력이 넘치는 바닷바람...",
  ui_story_5028_50280501_4_dialog_content = "사람이 정말 많네!",
  ui_story_5028_50280501_5_dialog_content = "여길 또 오게 될 줄은 정말 몰랐어!",
  ui_story_5028_50280501_6_dialog_content = "더워 죽겠어... 사람도 너무 많아.",
  ui_story_5028_50280501_7_dialog_content = "루~",
  ui_story_5028_50280501_8_dialog_content = "역시 이럴 땐 바닷가를 산책해야지~",
  ui_story_5028_50280501_9_dialog_content = "어이쿠!",
  ui_story_5028_50280501_10_dialog_content = "앗, 괜찮아요?",
  ui_story_5028_50280501_11_dialog_content = "아, 괜찮습니다. 고마워요.",
  ui_story_5028_50280501_12_dialog_content = "흐응? 혹시 넘어져서 안겨 온 게 여자애였으면 좋았을 거라 생각했어~?",
  ui_story_5028_50280501_13_dialog_content = "아니거든!",
  ui_story_5028_50280501_14_dialog_content = "호오? 그럼 방금 그 건장한 오빠가 더 좋아?",
  ui_story_5028_50280501_15_dialog_content = "그것도 아니라고! 놀리지 마.",
  ui_story_5028_50280501_16_dialog_content = "근데 너네 사부라는 사람, 널 정말 예뻐하는 모양이네.",
  ui_story_5028_50280501_17_dialog_content = "해변에서 휴가를 보내는 것도 시련의 일환이야?",
  ui_story_5028_50280501_18_dialog_content = "그럴 리가, 그 허접 사부가 그렇게 마음씨 좋을 리가 없다고.",
  ui_story_5028_50280501_19_dialog_content = "여긴 사람이 너무 많아서 짜증 나. 도대체 왜 여기로 보낸 건지 제대로 설명도 안 했고.",
  ui_story_5028_50280501_20_dialog_content = "사부는 맨날 나한테 타래들 빗질을 시키고, 털을 깎게 해.\n그렇게 모은 털은 돈으로 바꾸는 거야.",
  ui_story_5028_50280501_21_dialog_content = "돈이 생기고 나면 먹고 마시거나 노는 데 써 버려...",
  ui_story_5028_50280501_22_dialog_content = "정작 난 집에 남아서 페페츄한테 먹일 사료를 만들거나,\n야보노루의 배설물을 치우거나, 돌풍개한테 끌려다니면서 산책을 시켜야 돼.",
  ui_story_5028_50280501_23_dialog_content = "피아처럼 귀여운 여자애를 매일 하인처럼 부려 먹고 있다고.",
  ui_story_5028_50280501_24_dialog_content = "관찰 연구 임무로 외출할 때도 사부가 대충 쓴 메모 때문에 얼마나 고생했는지 몰라.",
  ui_story_5028_50280501_25_dialog_content = "루, 루.",
  ui_story_5028_50280501_26_dialog_content = "음... 그럼 왜 계속 그 사람 제자를 하는 건데?",
  ui_story_5028_50280501_27_dialog_content = "게다가 말로는 불평하고 있으면서,\n지금까지 계속 열심히 그 사람이 맡긴 일을 했던 거 아냐?",
  ui_story_5028_50280501_28_dialog_content = "사부랑 나는 악연 그 자체야!",
  ui_story_5028_50280501_29_dialog_content = "난 어렸을 때부터 <color=#FFB400>《신기한 작은 동물》</color>이라는 책을 엄청 좋아했어.",
  ui_story_5028_50280501_30_dialog_content = "그 책은 내 어린 시절을 환하게 밝혀줬어.",
  ui_story_5028_50280501_30X_dialog_content = "그 책 덕분에 난 동물들이랑 소통할 수 있게 됐고, 녀석들을 무척이나 좋아하게 됐어.",
  ui_story_5028_50280501_31_dialog_content = "하지만 움브라톤엔 오로리안뿐이고, 환상동물은 거의 없어.\n난 그걸 참을 수가 없어서 결심을 했어.",
  ui_story_5028_50280501_32_dialog_content = "이 책을 쓴 사람을 찾아서, 수많은 나날 동안 날 사로잡았던\n이 책 속의 환상동물들이 대체 어디 있는지 물어보기로 말이야.",
  ui_story_5028_50280501_33_dialog_content = "그래서 난 부모님과 작별하고 혼자 짐을 싸서 이 작가가 살고 있다는 숲으로 향했어.",
  ui_story_5028_50280501_34_dialog_content = "근데 며칠 동안 찾아다녔지만 아무 단서도 없었어.\n그리고 텐트 앞에서 밤나무 열매를 구워 먹는데, 갑자기 한 남자가 나타난 거야.",
  ui_story_5028_50280501_35_dialog_content = "그 사람은 수풀 속에서 튀어나와서는 천천히 날 향해서 기어 왔어.\n금방이라도 굶어 죽을 것처럼 보였고 말이야.",
  ui_story_5028_50280501_36_dialog_content = "설마 그게...",
  ui_story_5028_50280501_37_dialog_content = "맞아. 근데 그땐 그 사람이 책의 작가인 줄은 전혀 몰랐어.",
  ui_story_5028_50280501_38_dialog_content = "그 사람은 배부르게 먹고 나서야 갑자기 말을 하기 시작했어.\n자긴 이 대륙의 유일한 환상동물 마스터고, 이 부근에서 생태 조사를 하고 있다고 말이야.",
  ui_story_5028_50280501_39_dialog_content = "그 말이 너무 사기꾼 같아서 난 곧바로 마을로 달려가서 경비병을 부를 뻔했어.",
  ui_story_5028_50280501_40_dialog_content = "근데 그 남자가 그때 갑자기 글씨는 엉망이지만 열심히 적은 노트를 보여줬어.\n그리고 자기가 갖고 있는 여러 신기한 아이템도 보여줬어.",
  ui_story_5028_50280501_41_dialog_content = "게다가 그 사람은 휘파람만 불어도 근처에 있는 환상동물들을 잔뜩 불러올 수 있었어.",
  ui_story_5028_50280501_42_dialog_content = "PlayerName, 저번에 비카를 만났을 때 기억나?",
  ui_story_5028_50280501_43_dialog_content = "너도 짐작했겠지만, 난 환상동물이랑 텔레파시로 소통할 수 있어.\n네가 오로리안이랑 소통하는 것처럼 말이야.",
  ui_story_5028_50280501_44_dialog_content = "그래서 난 드라코리온이나 비카의 울음소리를 알아들을 수 있는 거야.\n심지어 오로리안과 소통하는 것보다... 환상동물이랑 같이 있는 게 더 좋아.",
  ui_story_5028_50280501_45_dialog_content = "그때의 난 환상동물들에 둘러싸여 있는 행복감 때문에 정신이 혼미해졌던 게 분명해.",
  ui_story_5028_50280501_46_dialog_content = "게다가 사부도 계속 말했어. 내가 환상동물이랑 소통하는 재능이 있다면,\n분명히 위대한 환상동물 마스터가 될 수 있을 거라고 말이야!",
  ui_story_5028_50280501_47_dialog_content = "환상동물 마스터가 될 수 있다니... 그때의 나한테는 너무나도 매력적인 말이었어.",
  ui_story_5028_50280501_48_dialog_content = "아니, 지금의 나라도 똑같이 그 사람 제자가 되겠다고 선택했을 거야.",
  ui_story_5028_50280501_49_dialog_content = "그리고 그때 난 이미 굳게 믿고 있었어.\n그 사람이 바로 그 책의 작가, 환상동물 마스터 비크라고 말이야.",
  ui_story_5028_50280501_50_dialog_content = "결국 내가 선택한 길이지만... 그래도 역시 사부는 못된 사부야!",
  ui_story_5028_50280501_51_dialog_content = "하하하, 그럼 사실 넌 지금까지 쭉 자기가 좋아하는 일을 해 왔던 거네.",
  ui_story_5028_50280501_52_dialog_content = "앗──!",
  ui_story_5028_50280501_53_dialog_content = "조심해요!",
  ui_story_5028_50280501_54_dialog_content = "앗, 미, 미안해요! 갑자기 발이 미끄러져서...",
  ui_story_5028_50280501_55_dialog_content = "괜찮아요. 안 다쳤으면 됐죠.",
  ui_story_5028_50280501_56_dialog_content = "(뭐야, 또?)",
  ui_story_5028_50280501_57_dialog_content = "아, 미안. 아무튼 난 이렇게 생각해.",
  ui_story_5028_50280501_58_dialog_content = "인생이란 그런 거야. 모든 게 뜻대로 될 순 없어.\n그리고 넌 이미 많은 사람들보다 훨씬 더 행복해!",
  ui_story_5028_50280501_59_dialog_content = "오빠, 갑자기 억지로 어른스러운 척하는 거 정말 뭐라고 해야 할지 모르겠네.",
  ui_story_5028_50280501_60_dialog_content = "아까 몸매 좋은 언니가 넘어졌을 때 머리라도 부딪힌 걸까나?",
  ui_story_5028_50280501_61_dialog_content = "크흠, 안 부딪혔거든? 부딪히기 전에 잡아줬다고.",
  ui_story_5028_50280501_62_dialog_content = "그리고 피아 너... 지금 질투하는 거지?",
  ui_story_5028_50280501_63_dialog_content = "흥, 피아가 그런 저속하고 재미없는 일에 관심 가질 줄 알고?\n이렇게 많은 환상동물들이 내 곁에 있잖아. 난 그거면 충분해.",
  ui_story_5028_50280501_64_dialog_content = "방금 분명히 질투했잖아.",
  ui_story_5028_50280501_65_dialog_content = "야──!",
  ui_story_5028_50280501_66_dialog_content = "아, 알았어. 하던 얘기로 돌아가자. 넌 환상동물과 소통할 수 있잖아.\n그건 환상동물 마스터가 될 수 있는 재능이 확실해.",
  ui_story_5028_50280501_67_dialog_content = "내가 오로리안의 전투를 지휘하고 도울 수 있으니까\n지휘관의 재능이 있는 것처럼 말이야.",
  ui_story_5028_50280501_68_dialog_content = "흥, 확실히 그렇지. 근데 예외도 있어.\n피아는 키아로랑 소통이 안 돼.",
  ui_story_5028_50280501_69_dialog_content = "루~",
  ui_story_5028_50280501_70_dialog_content = "왜 그런 건데?",
  ui_story_5028_50280501_71_dialog_content = "모르겠어... 사부 말로는 키아로가 특별한 희귀종이래.",
  ui_story_5028_50280501_72_dialog_content = "루!",
  ui_story_5028_50280501_73_dialog_content = "희귀종? 드라코리온 같은 게 희귀종 아냐?",
  ui_story_5028_50280501_74_dialog_content = "그치? 사부가 하는 이상한 말은 너라도 안 믿겠지.",
  ui_story_5028_50280501_75_dialog_content = "루... 루...",
  ui_story_5028_50280501_76_dialog_content = "속상해할 거 없어, 키아로.",
  ui_story_5028_50280501_77_dialog_content = "네 생각을 읽을 순 없지만, 피아는 네가 분명히 착한 애라고 생각해.",
  ui_story_5028_50280501_78_dialog_content = "루~",
  ui_story_5028_50280501_79_dialog_content = "아무 쓸모도 없고, 도움도 안 되긴 하지만 말이야.",
  ui_story_5028_50280501_80_dialog_content = "루!",
  ui_story_5028_50280501_81_dialog_content = "으앗!",
  ui_story_5028_50280501_82_dialog_content = "뭐야? 왜 또 사람이 넘어진 거지?",
  ui_story_5028_50280501_83_dialog_content = "여기 역시 뭔가 이상해. 넘어진 사람 쪽으로 가 보자!",
  ui_story_5028_50280501_84_dialog_content = "잠깐만! 피아! 너무 서두르지 마──",
  ui_story_5028_50280501_85_dialog_content = "으아앗──",
  ui_story_5028_50280501_86_dialog_content = "이얍!",
  ui_story_5028_50280501_87_dialog_content = "...고, 고마워. PlayerName.",
  ui_story_5028_50280501_88_dialog_content = "정말, 넘어지기 쉬운 걸 알면서 그렇게 서두르면 어떡해?",
  ui_story_5028_50280501_89_dialog_content = "미안... 급해서 그랬어. 미안한데 좀 내려줄래?",
  ui_story_5028_50280501_90_dialog_content = "아, 알겠어.",
  ui_story_5028_50280501_91_dialog_content = "역시, 그런 거였어.",
  ui_story_5028_50280501_92_dialog_content = "응?",
  ui_story_5028_50280501_93_dialog_content = "안 보여? 내 다리에 붙은 녀석 말이야.",
  ui_story_5028_50280501_94_dialog_content = "이 투명한 녀석은 <color=#FFB400>찐찐득이</color>라고 해.",
  ui_story_5028_50280501_95_dialog_content = "꾸룩.",
  ui_story_5028_50280501_96_dialog_content = "주로 물속에서 살지만, 가끔씩 나와서 숨을 쉬어야 하거든.",
  ui_story_5028_50280501_97_dialog_content = "평소엔 몸이 투명해서 사람들이 걸려 넘어지기 쉬워.",
  ui_story_5028_50280501_98_dialog_content = "이곳은 오로리안이 너무 많아서 찐찐득이들이 살기엔 적합하지 않을 것 같아.",
  ui_story_5028_50280501_99_dialog_content = "둥지에서 전부 나온 건 아마 다른 곳으로 이주할 생각일 거야.",
  ui_story_5028_50280501_100_dialog_content = "근데 움직이는 속도도 너무 느리고, 자꾸 사람들한테 밟히고 있어.\n이대로면 찐찐득이도, 관광객들도 모두 다치기 쉬워.",
  ui_story_5028_50280501_101_dialog_content = "(환상동물에 대한 이야기만 나오면 피아는 무척 진지해지는구나.)",
  ui_story_5028_50280501_102_dialog_content = "아, 맞다! 그럼 혹시 시련 내용이 녀석들을 무사히 이주시키는 게 아닐까?",
  ui_story_5028_50280501_103_dialog_content = "아마 그렇겠지. 그럼 우리가 흩어져 있는 찐찐득이들을\n찾아서 다른 곳으로 옮겨주자!",
  ui_story_5028_50280501_104_dialog_content = "키아로, 찐찐득이하고 놀지만 말고 이리 와서 도와줘!",
  ui_story_5028_50280501_105_dialog_content = "루!",
  ui_story_5028_50280501_106_dialog_content = "휴, 얘가 마지막 한 마리지?",
  ui_story_5028_50280501_107_dialog_content = "꾸룩...",
  ui_story_5028_50280501_108_dialog_content = "응, 다들 같은 방향으로 기어가고 있어.",
  ui_story_5028_50280501_109_dialog_content = "녀석들은 새로운 해안에서 적합한 서식지를 찾을 거야.\n우린 거기까지 가는 걸 호위해 주기만 하면 돼.",
  ui_story_5028_50280501_110_dialog_content = "잠깐만. 저쪽엔 암귀가 있는 것 같아.\n혹시 쟤들한테 돌아서 가자고 말할 수 있어?",
  ui_story_5028_50280501_111_dialog_content = "그건 무리야. 찐찐득이는 융통성이 없거든.\n그게 아니면 계속 사람들한테 밟히면서도 그 자리에 있었을 리가 없잖아.",
  ui_story_5028_50280501_112_dialog_content = "고작 암귀 몇 마리일 뿐이야. 나도 더는 도망치지 않을 거야!",
  ui_story_5028_50280501_113_dialog_content = "이번엔 이 피아 님이 암귀들을 전부 쫓아내 줄게!",
  ui_story_5028_50280502_1_dialog_content = "<color=#e8d9bb>찰싹── 찰싹──</color>",
  ui_story_5028_50280502_2_dialog_content = "이쪽 바닷가는 되게 조용하네. 갈매기 소리도 거의 안 들려.",
  ui_story_5028_50280502_3_dialog_content = "여기라면 찐찐득이들도 편하게 살 수 있겠지?",
  ui_story_5028_50280502_4_dialog_content = "꾸룩~ 꾸룩~",
  ui_story_5028_50280502_5_dialog_content = "항상 조심해. 다음엔 사람들이 모이기 전에 움직이는 거야~",
  ui_story_5028_50280502_6_dialog_content = "야, 걸려 넘어진 관광객들도 잘못은 없어!",
  ui_story_5028_50280502_7_dialog_content = "그치만 암귀가 잔뜩 나타나거나 환경이 급격하게 변하면서,\n환상동물의 서식지도 점점 줄어들고 있어.",
  ui_story_5028_50280502_8_dialog_content = "그거 알아? 사실 많은 환상동물들이 줄곧 남몰래 오로리안들을 지켜주고 있었어.",
  ui_story_5028_50280502_9_dialog_content = "도시 근처에도 환상동물들이 많이 살고 있어.\n제일 먼저 암귀를 발견하고 맞서 싸우는 것도 환상동물일 때가 많아.",
  ui_story_5028_50280502_10_dialog_content = "그건 정말 처음 들었어.",
  ui_story_5028_50280502_11_dialog_content = "아무튼 이렇게 시련을 또 하나 완수했어!\n오늘은 정말 환상동물한테 많은 도움을 준 하루야!",
  ui_story_5028_50280502_12_dialog_content = "(어라? 뭔가 다리에 끈적한 게 붙은 느낌인데...)",
  ui_story_5028_50280502_13_dialog_content = "꾸룩...",
  ui_story_5028_50280502_14_dialog_content = "전에 근처에 무서운 괴물이 나타났다고?\n근데 다들 안 믿어줬구나. 그래서 넌 피아랑 같이 있고 싶은 거야?",
  ui_story_5028_50280502_15_dialog_content = "헤헤, 그런 작업 멘트는 좀 구식인걸.",
  ui_story_5028_50280502_16_dialog_content = "뭐, 괜찮아. 너도 우리랑 같이 다니자!",
  ui_story_5028_50280502_17_dialog_content = "PlayerName, 봐, 우리 또 새로운 동료가 생겼어!",
  ui_story_5028_50280502_18_dialog_content = "루~",
  ui_story_5028_50280502_19_dialog_content = "또 늘어난 거야? 넌 평소에도 이렇게 환상동물들한테 인기가 많아?",
  ui_story_5028_50280502_20_dialog_content = "하이~",
  ui_story_5028_50280502_21_dialog_content = "당연하지. 난 미래의 환상동물 마스터야.\n그러니까 당연히 모든 환상동물이랑 친구가 돼야지!",
  ui_story_5028_50280502_22_dialog_content = "대신 수가 너무 많으면 사부한테 부탁해서 돌봐달라고 하고 있어.\n내 곁에 있으면 위험하니까.",
  ui_story_5028_50280502_23_dialog_content = "그래, 알았어. 그럼 우리 마스터님, 시련을 마치려면 얼마나 더 남았어?",
  ui_story_5028_50280502_24_dialog_content = "음, 노트를 좀 볼게.",
  ui_story_5028_50280502_25_dialog_content = "좋았어! 아, 아니지, 망했어!",
  ui_story_5028_50280502_26_dialog_content = "루?",
  ui_story_5028_50280502_27_dialog_content = "뭐?",
  ui_story_5028_50280502_28_dialog_content = "시련은 전부 달성했다고 할 수 있어. 근데 어쩌면 영원히 달성할 수 없을지도 몰라.",
  ui_story_5028_50280502_29_dialog_content = "그게 무슨 소리야?",
  ui_story_5028_50280502_30_dialog_content = "봐! 위험한 시련은 이미 전부 달성했어!",
  ui_story_5028_50280502_31_dialog_content = "근데 난이도가 제일 높은 시련... 사부가 쓴 《환상동물 대백과》를\n전부 외우는 건 언제 해낼 수 있을지 까마득하다구!",
  ui_story_5028_50280502_32_dialog_content = "끔찍해! 벌써 일주일이나 외웠는데 아직 두 페이지 반밖에 못 외웠어...",
  ui_story_5028_50280502_33_dialog_content = "루...",
  ui_story_5028_50280502_34_dialog_content = "아... 그런 건 힘이나 행동으로 해결할 수 없는 문제네.",
  ui_story_5028_50280502_35_dialog_content = "아이테르인 나라도 기억을 네 머릿속에 넣어주는 건 무리야.",
  ui_story_5028_50280502_36_dialog_content = "...루!",
  ui_story_5028_50280502_37_dialog_content = "히잉...",
  ui_story_5028_50280502_38_dialog_content = "루! 루!",
  ui_story_5028_50280502_39_dialog_content = "응? 키아로, 왜 그래?",
  ui_story_5028_50280502_40_dialog_content = "노트 잡아당기지 마! 이러다 찢어지겠어!",
  ui_story_5028_50280502_41_dialog_content = "루!",
  ui_story_5028_50280502_42_dialog_content = "하지 말라고 했잖아! 으앗!",
  ui_story_5028_50280502_43_dialog_content = "피아, 괜찮아?",
  ui_story_5028_50280502_44_dialog_content = "바보 키아로! 싸우자는 거야?!",
  ui_story_5028_50280502_45_dialog_content = "잠깐만, 키아로가 노트를 넘기고 있어.",
  ui_story_5028_50280502_46_dialog_content = "뭐?",
  ui_story_5028_50280502_47_dialog_content = "루! 루!",
  ui_story_5028_50280502_48_dialog_content = "이 페이지에 있는 건... 토끼인가?",
  ui_story_5028_50280502_49_dialog_content = "토끼?",
  ui_story_5028_50280502_50_dialog_content = "도착했어.",
  ui_story_5028_50280502_51_dialog_content = "어머? 이게 큰돈을 들여서 얻은 단서야?",
  ui_story_5028_50280502_52_dialog_content = "움브라톤에서 오랫동안 이름을 떨쳐온 우리 스모키 양도\n이렇게 속는 일이 있을 줄은 몰랐네.",
  ui_story_5028_50280502_53_dialog_content = "아니면 일부러 날 바닷가로 불러낸 거야?\n미안한데 나 수영복은 안 챙겨 왔는걸.",
  ui_story_5028_50280502_54_dialog_content = "하하, 미안하지만 난 이미 입었거든.",
  ui_story_5028_50280502_55_dialog_content = "어때, 화나지? 방어력이라곤 조금도 없는 네 그 구멍투성이 수영복도 못 입고 말이야.",
  ui_story_5028_50280502_56_dialog_content = "오늘은 그렇게 두꺼운 옷이나 입고, 멍청하게 바닷가에 서 있을 수밖에 없겠네.",
  ui_story_5028_50280502_57_dialog_content = "그 표정, 계속 보고 싶었어. 날 질투하는 그 표정 말이야.",
  ui_story_5028_50280502_58_dialog_content = "너... 진짜! 아이테르 찾는 것보다 일단 너부터 같이 바다에 빠져줘야겠어!",
  ui_story_5028_50280502_59_dialog_content = "아하하, 사실 아이테르 같은 건 아무래도 좋아.\n난 그냥 재미 삼아 시간 때우러 따라왔을 뿐이야.",
  ui_story_5028_50280502_60_dialog_content = "그건 너도 마찬가지 아냐?",
  ui_story_5028_50280502_61_dialog_content = "난 그런 적당한 마음으로 온 게 아냐. 너랑 같은 취급 안 했으면 좋겠어.",
  ui_story_5028_50280502_62_dialog_content = "이번에야말로 이 제네비브 님이 정정당당하게 널 넘어설 절호의 기회니까!",
  ui_story_5028_50280502_63_dialog_content = "수영복 따위에 의지하지 않고, 현상금 사냥꾼의 프로 정신으로 널 이겨줄게!",
  ui_story_5028_50280502_64_dialog_content = "호오? 말은 거창하네. 수영복도 없는 게.",
  ui_story_5028_50280502_65_dialog_content = "좋겠다. 나도 수영복 갖고 싶어.",
  ui_story_5028_50280502_66_dialog_content = "거기 여러분, 이쪽을 보세요──",
  ui_story_5028_50280502_67_dialog_content = "<color=#e8d9bb>찰칵!</color>",
  ui_story_5028_50280502_68_dialog_content = "레스터?",
  ui_story_5028_50280502_69_dialog_content = "어머, 스모키 씨네요?",
  ui_story_5028_50280502_70_dialog_content = "네가 여기 왜 있어? 아직도 여행 중이야?",
  ui_story_5028_50280502_71_dialog_content = "그럼요. 여기 두 분도 전에 뵌 적이 있는 것 같네요.\n다 같이 바다에 놀러 오셨나요?",
  ui_story_5028_50280502_72_dialog_content = "자, 이건 방금 찍은 기념사진이에요.",
  ui_story_5028_50280502_73_dialog_content = "아, 고마워.",
  ui_story_5028_50280502_74_dialog_content = "...나도 볼래.",
  ui_story_5028_50280502_75_dialog_content = "뭐, 놀러 온 셈이긴 하지. 겸사겸사 납치됐는지, 실종됐는지 모를 친구를 찾고 있어.",
  ui_story_5028_50280502_76_dialog_content = "아, 맞다. 너도 아는 녀석이야. 그 아이테르 말이야.",
  ui_story_5028_50280502_77_dialog_content = "아이테르 씨가 없어졌다고요? 이 대륙에서 한 마리뿐인 아이테르가요?",
  ui_story_5028_50280502_78_dialog_content = "그래. 한 마리인지 한 명인지. 아무튼 걔가 없어졌어.",
  ui_story_5028_50280502_79_dialog_content = "알겠어요. 그럼 저도 여행하면서 주의해서 살펴볼게요.",
  ui_story_5028_50280502_80_dialog_content = "아이테르 씨를 보면 그대로 잡아드리죠.",
  ui_story_5028_50280601_1_dialog_content = "시련: 《환상동물 대백과》 암기",
  ui_story_5028_50280601_2_dialog_content = "<color=#e8d9bb>탕!</color>",
  ui_story_5028_50280601_3_dialog_content = "<color=#e8d9bb>탕! 탕!</color>",
  ui_story_5028_50280601_4_dialog_content = "됐어! 막 쏴대지 마.",
  ui_story_5028_50280601_5_dialog_content = "그랬다간 사냥감이 도망칠 거라고.",
  ui_story_5028_50280601_6_dialog_content = "쳇, 저 두 녀석을 놔둘 셈이야?",
  ui_story_5028_50280601_7_dialog_content = "저것들한테 낭비할 시간 없어.\n얼른 <color=#FFB400>게리</color> 두목님한테 <color=#FFB400>「페코」</color>를 잡아다 드려야 한다고.",
  ui_story_5028_50280601_8_dialog_content = "두목님을 화나게 했다간 우린 끝장이야.",
  ui_story_5028_50280601_9_dialog_content = "으.",
  ui_story_5028_50280601_10_dialog_content = "으...으...",
  ui_story_5028_50280601_11_dialog_content = "으엣취──!",
  ui_story_5028_50280601_12_dialog_content = "쉿.",
  ui_story_5028_50280601_13_dialog_content = "가버렸어.",
  ui_story_5028_50280601_14_dialog_content = "루.",
  ui_story_5028_50280601_15_dialog_content = "키아로가 똑똑해서 다행이야. 눈 덮인 수풀로 들어와서 숨을 수 있었어.",
  ui_story_5028_50280601_16_dialog_content = "루~",
  ui_story_5028_50280601_17_dialog_content = "엣취──!",
  ui_story_5028_50280601_18_dialog_content = "엣취! 에엣취! 으엣취!",
  ui_story_5028_50280601_19_dialog_content = "괜찮아? 이걸로 닦아.",
  ui_story_5028_50280601_20_dialog_content = "휴, 고마워.",
  ui_story_5028_50280601_21_dialog_content = "그건 그렇고 여긴 대체 어디야? 추워서 손발이 굳어버렸잖아.",
  ui_story_5028_50280601_22_dialog_content = "노트에 적혀 있던 「페코」를 잡기 위해서만 아니었으면,\n피아는 절대 이런 추운 곳에 안 왔을 거라구.",
  ui_story_5028_50280601_23_dialog_content = "내 외투를 빌려줄게. 참, 여기 여분 머리띠도 있어.",
  ui_story_5028_50280601_24_dialog_content = "됐어. 나한테 줘버리면 너도 못 버틸 거야.",
  ui_story_5028_50280601_25_dialog_content = "이거 먹어.",
  ui_story_5028_50280601_26_dialog_content = "우웁?!",
  ui_story_5028_50280601_27_dialog_content = "그건 샌드버그 파우더와 연료유, 그리고 일륜초를 조합한 약이야.",
  ui_story_5028_50280601_28_dialog_content = "그걸 먹으면 극한 환경에서도 체온을 유지할 수 있어.",
  ui_story_5028_50280601_29_dialog_content = "근데 요즘 샌드버그 파우더가 구하기 힘들어서 방금 그 한 알이 마지막이었어.",
  ui_story_5028_50280601_30_dialog_content = "따뜻해진 것 같아. 그럼 넌 어떡해?",
  ui_story_5028_50280601_31_dialog_content = "피아는 찐찐득이를 몸에 붙여서 최대한 체온을 유지할 거야.",
  ui_story_5028_50280601_32_dialog_content = "꾸룩...",
  ui_story_5028_50280601_33_dialog_content = "만약 피아가 쓰러지면 네가 날 업고 산을 내려가서 도움을 요청해 줘.",
  ui_story_5028_50280601_34_dialog_content = "근데 네가 쓰러지면 피아가 널 데리고 산을 내려가는 건 무리야.",
  ui_story_5028_50280601_35_dialog_content = "그런가? 알았어. 정말 그렇게 되면 내가 꼭 널 데리고 내려갈게!",
  ui_story_5028_50280601_36_dialog_content = "응, 근데 다시 생각해 보니까, 네 그 허약한 몸은 별로 의지가 안 될 것 같아.\n역시 도로 뱉어줘. 키아로한테 먹일래.",
  ui_story_5028_50280601_37_dialog_content = "지금 말해봤자 늦었어. 벌써 소화해 버렸으니까!",
  ui_story_5028_50280601_38_dialog_content = "아하하, 정말 뱉으라고 할 리가 없잖아.",
  ui_story_5028_50280601_39_dialog_content = "루?",
  ui_story_5028_50280601_40_dialog_content = "기운도 차렸으니까, 얼른 계속 가자.",
  ui_story_5028_50280601_41_dialog_content = "저 사냥꾼들보다 먼저 「페코」를 찾아야 해.",
  ui_story_5028_50280601_42_dialog_content = "저렇게 많은 사냥꾼들이 이런 불모지까지 찾아오다니...\n그 토끼가 정말 그렇게 희귀한 동물이야?",
  ui_story_5028_50280601_43_dialog_content = "훈련된 모습을 보면 보통 녀석들은 아니었어.\n아마 고용주도 큰돈을 걸었을 거야.",
  ui_story_5028_50280601_44_dialog_content = "흥, 바보들이 아무리 모여 봤자 소용없어.",
  ui_story_5028_50280601_45_dialog_content = "머릿수가 아무리 많든, 사냥총, 사냥개, 함정이 얼마나 많든 쓸모없다구.",
  ui_story_5028_50280601_46_dialog_content = "그 토끼는 교활해서 절대 안 잡힐 거야.",
  ui_story_5028_50280601_47_dialog_content = "경험이 많은 사냥꾼들이 저만큼 모여도 무리인 거라면,\n우리가 정말 잡을 수 있을까?",
  ui_story_5028_50280601_48_dialog_content = "걱정 마! 피아는 실전 경험이 풍부한 환상동물 마스터니까!",
  ui_story_5028_50280601_49_dialog_content = "페코 정도는 단숨에 잡을 수 있다구.",
  ui_story_5028_50280601_50_dialog_content = "다, 단숨에... 손이 또 얼어버렸어!",
  ui_story_5028_50280601_51_dialog_content = "사부의 메모는 찾았어? 나도 같이 찾을까?",
  ui_story_5028_50280601_52_dialog_content = "필요 없어! 벌써 찾았으니까.",
  ui_story_5028_50280601_53_dialog_content = "「페코는 빠르고 영리해서 잡기가 어렵다. 하지만 녀석은 책을 먹는 것을 좋아한다.」",
  ui_story_5028_50280601_54_dialog_content = "잘됐네! 그럼 책을 미끼로 유인하면...",
  ui_story_5028_50280601_55_dialog_content = "근데 책을 미끼로 유인한다는 누구나 떠올릴 만한 방법으로는\n아무런 수확도 없이 돌아가게 될 수도 있어.",
  ui_story_5028_50280601_56_dialog_content = "난 아무 말도 안 한 걸로 할게.",
  ui_story_5028_50280601_57_dialog_content = "페코는 무척 교활해서, 갑자기 책이 나타나면 오히려 녀석들의 경각심을 부채질할 거야.",
  ui_story_5028_50280601_58_dialog_content = "대신 녀석들의 호기심을 이용하면 잘될지도 몰라.\n그런 거 있잖아. 「남의 떡이 커 보인다」 말이야.",
  ui_story_5028_50280601_59_dialog_content = "호기심이라면... PlayerName, 요 며칠 동안 네가 읽던 그 책 좀 빌려줘!",
  ui_story_5028_50280601_60_dialog_content = "이 책은 또 뭐야?\n《가끔씩 툭하고 이클립스어로 부끄러워하는 옆자리의 슈우 양》?",
  ui_story_5028_50280601_61_dialog_content = "뭔 제목이 이렇게 길어?",
  ui_story_5028_50280601_62_dialog_content = "아, 그건 저번에 그 포도 농장 펭 아저씨가 준 책이야.\n자기가 새로 쓴 소설이라고 하더라고.",
  ui_story_5028_50280601_63_dialog_content = "사인까지 해 줬어. 몇 년 뒤엔 비싸게 팔릴 거라던데?",
  ui_story_5028_50280601_64_dialog_content = "아, 그렇구나. 그래, 그럼 그걸로 하자.\n그럼 적어도 사부의 노트를 가지고 위험을 감수할 필요는 없을 테니까.",
  ui_story_5028_50280601_65_dialog_content = "...휴.",
  ui_story_5028_50280601_66_dialog_content = "넌 분명히 별말 안 하긴 했지만...\n지금 나도 그렇고, 저 멀리 있는 펭 아저씨도 분명히 큰 상처를 받았을 거야.",
  ui_story_5028_50280601_67_dialog_content = "자, 수다는 여기까지. 우린 저 사냥꾼들보다 먼저 토끼를 잡아야 한다구.",
  ui_story_5028_50280601_68_dialog_content = "넌 먼저 숨어 있어. 내가 책을 읽기 시작할 테니까.",
  ui_story_5028_50280601_69_dialog_content = "토끼가 오면 버튼을 눌러.",
  ui_story_5028_50280601_70_dialog_content = "근데 그럼 너도 토끼랑 같이 그물에 걸릴 거잖아?",
  ui_story_5028_50280601_71_dialog_content = "그게 뭐 어때서. 페코가 날 물진 않을 거야.",
  ui_story_5028_50280601_72_dialog_content = "감히 피아를 물거나 하면 나도 더 세게 물어 줄 거라구.",
  ui_story_5028_50280601_73_dialog_content = "<color=#e8d9bb>잠시 후</color>",
  ui_story_5028_50280601_74_dialog_content = "페코?",
  ui_story_5028_50280601_75_option_content = "(피아와 감응한다)",
  ui_story_5028_50280601_76_dialog_content = "뭔가 온 것 같아. 피아, 침착하게 가자.",
  ui_story_5028_50280601_77_dialog_content = "알았어. 너도 타이밍 놓치지 마.",
  ui_story_5028_50280601_78_dialog_content = "루...",
  ui_story_5028_50280601_79_dialog_content = "페코페코...",
  ui_story_5028_50280601_80_dialog_content = "(후후후, 바로 그거야. 이리 와. 호기심에 사로잡혀서 피아 곁으로 오는 거야.)",
  ui_story_5028_50280601_81_dialog_content = "페코...",
  ui_story_5028_50280601_82_dialog_content = "안 되겠어. 그 토끼 경계심이 너무 강해.\n계속 그물 주변만 다니면서 안으로는 들어갈 생각이 없어.",
  ui_story_5028_50280601_83_dialog_content = "지금 그물을 내려 봤자 금방 도망칠 거야.\n다음 기회는 언제가 될지 몰라!",
  ui_story_5028_50280601_84_dialog_content = "어쩔 수 없네, 내가 직접 덮칠 테니까,\nPlayerName 넌 임기응변으로 대응해.",
  ui_story_5028_50280601_85_dialog_content = "당장──",
  ui_story_5028_50280601_86_dialog_content = "페코?",
  ui_story_5028_50280601_87_dialog_content = "얌전히 잡혀!",
  ui_story_5028_50280601_88_dialog_content = "페코!",
  ui_story_5028_50280601_89_dialog_content = "놓칠 줄 알고!",
  ui_story_5028_50280601_90_dialog_content = "잡았다! 잡았어!",
  ui_story_5028_50280601_91_dialog_content = "페코페코페코페코!",
  ui_story_5028_50280601_92_dialog_content = "갑자기 소리를 질러서 놀라게 만들 줄이야...",
  ui_story_5028_50280601_93_dialog_content = "중요한 순간에 그런 방법을 떠올리다니,\n똑똑하다고 해야 하나, 엉뚱하다고 해야 하나...",
  ui_story_5028_50280601_94_dialog_content = "헤헤, 칭찬으로 받아줄게. 너도 거기서 멍하니 있지 말고, 얼른 나랑 토끼를 꺼내줘.",
  ui_story_5028_50280601_95_dialog_content = "헤헤헤헤, 이제 마지막 시련도 방법이 생겼어.",
  ui_story_5028_50280601_96_dialog_content = "페...페코...",
  ui_story_5028_50280601_97_dialog_content = "루~",
  ui_story_5028_50280601_98_dialog_content = "이 토끼가 네 시련에 무슨 도움이 되는데?",
  ui_story_5028_50280601_99_dialog_content = "책의 내용에 따르면 페코는 대량의 서적 내용을 취합해서\n그걸 전부 다른 사람한테 전이할 수 있대.",
  ui_story_5028_50280601_100_dialog_content = "...그런 괴상한 말에도 더는 놀라지 않게 되다니.\n그래서 어떻게 해야 되는데?",
  ui_story_5028_50280601_101_dialog_content = "어디 보자, 일단 전이할 내용, 그러니까 책을 먹여야 돼.",
  ui_story_5028_50280601_102_dialog_content = "뭐, 환상동물이니까... 그 정도는 이해할 수 있겠어.",
  ui_story_5028_50280601_103_dialog_content = "그리고?",
  ui_story_5028_50280601_104_dialog_content = "그런 다음... 기름을 적당히 데우고...\n양파, 생강, 마늘을 넣고 향이 날 때까지 볶아.",
  ui_story_5028_50280601_105_dialog_content = "?",
  ui_story_5028_50280601_106_dialog_content = "페코!",
  ui_story_5028_50280601_107_dialog_content = "루!",
  ui_story_5028_50280601_108_dialog_content = "그리고 설탕을 약간 넣어서 캐러멜색이 될 때까지 볶고, 거기에 이제 털을 뽑은...",
  ui_story_5028_50280601_109_dialog_content = "잠깐만, 그거 갈비찜 만드는 법 아냐?",
  ui_story_5028_50280601_110_dialog_content = "쪄서 조리하는 것도 괜찮다...? 그럴 리가 없잖아! 이 허접 사부가!",
  ui_story_5028_50280601_111_dialog_content = "아니면 다리 하나만 먼저 먹어보는 게 어때? 효과가 있을지도 모르잖아.",
  ui_story_5028_50280601_112_dialog_content = "페코페코페코!",
  ui_story_5028_50280601_113_dialog_content = "그런 농담 그만해. 페코가 무서워하잖아.",
  ui_story_5028_50280601_114_dialog_content = "잠깐만, 얘가 우리한테 조심하라고 하는 것 같아.",
  ui_story_5028_50280601_115_dialog_content = "뭘? 사냥꾼들은 벌써 따돌렸잖아.",
  ui_story_5028_50280601_116_dialog_content = "사냥꾼이 아니라... <color=#FFB400>암귀를 조심하래</color>!",
  ui_story_5028_50280602_1_dialog_content = "정말 끈질긴 녀석들이네.",
  ui_story_5028_50280602_2_dialog_content = "왜 어딜 가도 암귀가 있는 거지?\n이래서야 환상동물 마스터보다 암귀 마스터가 되는 게 더 빠를 것 같아.",
  ui_story_5028_50280602_3_dialog_content = "그래도 이 녀석이 가르쳐 줘서 다행이야. 안 그랬으면 포위당할 뻔했어.",
  ui_story_5028_50280602_4_dialog_content = "페코페코~",
  ui_story_5028_50280602_5_dialog_content = "이래서는 더 먹을 수가 없겠는데? 너 시련은 어떻게 할 거야?",
  ui_story_5028_50280602_6_dialog_content = "다른 방법을 생각해 볼게. 사적인 욕심 때문에 환상동물을 해치는 건\n환상동물 마스터가 할 짓이 아냐.",
  ui_story_5028_50280602_7_dialog_content = "설령 시련을 통과할 수 없다고 해도... 그런 짓은 절대...",
  ui_story_5028_50280602_8_dialog_content = "으으, 그럼 대체 어떻게 하지?",
  ui_story_5028_50280602_9_dialog_content = "페코...",
  ui_story_5028_50280602_10_dialog_content = "루...",
  ui_story_5028_50280602_11_dialog_content = "꾸룩...",
  ui_story_5028_50280602_12_dialog_content = "너희들... 위로해 줘서 고마워.",
  ui_story_5028_50280602_13_dialog_content = "휴, 다른 방법은 없는 거야?",
  ui_story_5028_50280602_14_dialog_content = "이 녀석을 해치지 않고도 도움을 받을 수 있는 방법이 분명 있지 않을까?",
  ui_story_5028_50280602_15_dialog_content = "아! 생각났어!",
  ui_story_5028_50280602_16_dialog_content = "페코, 내 완벽한 계획을 들어볼래?",
  ui_story_5028_50280602_17_dialog_content = "페코!",
  ui_story_5028_50280602_17X1_dialog_content = "으앗!",
  ui_story_5028_50280602_18_dialog_content = "어라? 엄청 살갑게 달려드네.",
  ui_story_5028_50280602_19_dialog_content = "후후, 이게 바로 피아 님의 강력한 친화력이란 거야.",
  ui_story_5028_50280602_19X1_dialog_content = "그래, 그래. 그래서 어떤 방법인데?",
  ui_story_5028_50280602_19X2_dialog_content = "다른 사람한테는 어려울지 몰라도, 피아한테는 아주 쉬운 방법이야.",
  ui_story_5028_50280602_19X3_dialog_content = "기억나? 피아는 환상동물의 울음소리를 알아들을 수 있잖아.",
  ui_story_5028_50280602_19X4_dialog_content = "그럼 시험을 볼 때 페코를 품 안이나 주머니 속에 넣어두고...",
  ui_story_5028_50280602_19X5_dialog_content = "나한테 정답을 알려주게 하면 되는 거야.",
  ui_story_5028_50280602_19X6_dialog_content = "그럼 피아는 무사히 시련을 통과하고, 그 허접 사부를 놀라게 만들 수 있을 거야!",
  ui_story_5028_50280602_19X7_dialog_content = "그게 쉽게 될까? 왠지 어려울 것 같은데.",
  ui_story_5028_50280602_20_dialog_content = "페코페코~",
  ui_story_5028_50280602_20X1_dialog_content = "페코, 내가 시험 볼 때 주머니 속에 숨어서...",
  ui_story_5028_50280602_20X2_dialog_content = "몰래 정답을 가르쳐 줄 수 있을까?",
  ui_story_5028_50280602_20X3_dialog_content = "페코페코~",
  ui_story_5028_50280602_20X4_dialog_content = "헤헤, 다행이야!",
  ui_story_5028_50280602_21_dialog_content = "도와주겠대! 그리고 우리랑 같이 여행을 하겠대!",
  ui_story_5028_50280602_22_dialog_content = "페코~",
  ui_story_5028_50280602_22X1_dialog_content = "이걸로 성공이야! 이제 사부한테 돌아갈 수 있겠어!",
  ui_story_5028_50280602_23_dialog_content = "아무튼 벌써 이렇게 많은 동물들이 널 따르고 있잖아.\n한 마리 더 늘어나는 것도 나쁘진 않겠네.",
  ui_story_5028_50280602_24_dialog_content = "헤헤, PlayerName 넌 정말 좋은 사람이구나.",
  ui_story_5028_50280602_25_dialog_content = "응? 넌 페코 중에서도 운이 좋은 애라고?\n저번에 무서운 괴물한테 잡혔을 때도 무사히 풀려났다고?",
  ui_story_5028_50280602_26_dialog_content = "그거 대단하네. 그럼 네가 우리랑 같이 여행을 하면,\n우리한테 행운을 줄 수 있지 않을까? 그럼 앞으로 잘 부탁할게~",
  ui_story_5028_50280602_27_dialog_content = "페코~",
  ui_story_5028_50280602_28_dialog_content = "레비! 돌격!",
  ui_story_5028_50280602_29_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_5028_50280602_30_dialog_content = "대지를 불태워! 만티코어!",
  ui_story_5028_50280602_31_dialog_content = "어, 어서 도망쳐! 이 자식들 만만한 상대가 아냐!",
  ui_story_5028_50280602_32_dialog_content = "똑바로 기억해라. <color=#FFB400>게리 두목님</color>과 <color=#FFB400>강철채찍단</color>이 너흴 절대 용서하지 않을 거다!",
  ui_story_5028_50280602_33_dialog_content = "도망가 버렸어.",
  ui_story_5028_50280602_34_dialog_content = "아이테르도 못 찾았는데, 적의가 넘치는 사냥꾼들이랑 마주치다니.",
  ui_story_5028_50280602_35_dialog_content = "여기 뭐 하러 온 걸까? PlayerName 그 애가 얽힌 일이랑 관계가 있는 걸까?",
  ui_story_5028_50280602_36_dialog_content = "쳇, 한 놈 붙잡아서 물어볼 걸 그랬어.",
  ui_story_5028_50280602_37_dialog_content = "유후~ 너희 PlayerName 씨 친구들 아니야?",
  ui_story_5028_50280602_38_dialog_content = "로라? 넌 왜 여기 있니?",
  ui_story_5028_50280602_39_dialog_content = "편지를 전하러 가는 길이었는데, 총소리가 들리길래 보러 왔어.\n다들 안 다쳤어?",
  ui_story_5028_50280602_40_dialog_content = "우린 아이테르를 찾고 있었는데, 갑자기 사냥꾼들이 나타나서 우릴 공격했어.",
  ui_story_5028_50280602_41_dialog_content = "그래도 안 다쳤어. 사냥꾼도 도망갔어.",
  ui_story_5028_50280602_42_dialog_content = "헤에에? 아이테르? PlayerName 씨가 실종된 거야?",
  ui_story_5028_50280602_43_dialog_content = "그러고 보니까 오는 도중에 야영을 한 흔적이 있었어.\n어쩌면 무슨 단서가 있을지도 몰라.",
  ui_story_5028_50280602_44_dialog_content = "내가 그쪽으로 데려다줄게. 편지는 나중에 전하면 되니까.",
  ui_story_5028_50280602_45_dialog_content = "뭔가 단체 여행으로 변한 것 같은 느낌인걸?",
  ui_story_5028_50280602_46_dialog_content = "재밌잖아. 나가서 다양한 경치도 보고, 겸사겸사 암귀랑 나쁜 오로리안도 혼내주고.",
  ui_story_5028_50280602_47_dialog_content = "하긴, 재밌긴 하네.",
  ui_story_5028_50280701_1_dialog_content = "시련: 달콤한 유혹 견디기",
  ui_story_5028_50280701_2_dialog_content = "새하얀 구름~ 푸른 나무의 가지~♪",
  ui_story_5028_50280701_3_dialog_content = "길을 걷고 있는 피아와 친구들~♫",
  ui_story_5028_50280701_4_dialog_content = "그리고 즐거운 동료~ 아이테르~♪",
  ui_story_5028_50280701_5_dialog_content = "루루루~♫",
  ui_story_5028_50280701_6_dialog_content = "기분이 되게 좋아 보이는데?",
  ui_story_5028_50280701_7_dialog_content = "헤헤, 시련 달성까지 이제 얼마 안 남았으니까.",
  ui_story_5028_50280701_8_dialog_content = "PlayerName 너랑 키아로, 그리고 다들 도와준 덕분에 순조롭게 해냈어.",
  ui_story_5028_50280701_9_dialog_content = "나도 놀랐어.",
  ui_story_5028_50280701_10_dialog_content = "난 처음엔 피아가 힘든 걸 못 참고 포기할 줄 알았어.\n그럼 나도 고생할 일이 없겠다 싶었지.",
  ui_story_5028_50280701_11_dialog_content = "의외지? 피아는 말이야, 환상동물에 대해서라면 열정이 넘친다구!",
  ui_story_5028_50280701_12_dialog_content = "성격만 좀 덜 사나웠으면 좋겠는데 말이야.",
  ui_story_5028_50280701_13_dialog_content = "그건 안 돼. 그건 피아의 개성이거든. 개성이 없어지면 매력이 반감된다구!",
  ui_story_5028_50280701_14_dialog_content = "그것도 그렇네. 그래야 피아답지.",
  ui_story_5028_50280701_15_dialog_content = "헤헤──",
  ui_story_5028_50280701_16_dialog_content = "(맞아, 나도 알아. 사나운 건 그냥 위장일 뿐이고, 피아는 마음이 착한 아이야.)",
  ui_story_5028_50280701_16X_dialog_content = "(인간의 본성을 잘 이해하는 이 동물들도 그 사실을 알고 있는 거겠지.)",
  ui_story_5028_50280701_17_dialog_content = "(동물들은 단순하면서도 영리해. 그래서 무엇이 진심이고 위선인지,\n누가 상냥하고, 누가 잔혹한지 잘 알고 있어.)",
  ui_story_5028_50280701_18_dialog_content = "(저 동물들과 피아의 사이가 좋은 건,\n그만큼 피아가 착하고 상냥한 아이라는 확실한 증거겠지.)",
  ui_story_5028_50280701_19_dialog_content = "...응? 뭘 멍하니 생각하고 있어?",
  ui_story_5028_50280701_20_dialog_content = "목말라? 물병 줄게.",
  ui_story_5028_50280701_21_dialog_content = "앞으로 반나절만 더 걸으면 사부의 집에 도착할 거야. 조금만 더 버텨.",
  ui_story_5028_50280701_22_dialog_content = "괜찮아, 목 안 말라.",
  ui_story_5028_50280701_23_dialog_content = "그럼 넌 졸업한 뒤에 뭘 할 계획인데?",
  ui_story_5028_50280701_24_dialog_content = "글쎄, 아마 여기저기 여행하고, 더 많은 환상동물들을 만나겠지.\n그리고 그걸 기록해서 사부가 쓴 것보다 더 대단한 책을 쓸 거야.",
  ui_story_5028_50280701_25_dialog_content = "역시 피아다운 계획이네...",
  ui_story_5028_50280701_26_dialog_content = "헤헤, 그럼 PlayerName 넌 뭘 할 건데?",
  ui_story_5028_50280701_27_dialog_content = "일단은 드라코리온 문제를 해결할 방법부터 찾아야겠지.",
  ui_story_5028_50280701_28_dialog_content = "앞으로 또 갑자기 어디서 저렇게 큰 용을 만나는 건 사양하고 싶으니까.",
  ui_story_5028_50280701_29_dialog_content = "걱정 마. 피아가 해결해 줄게.",
  ui_story_5028_50280701_30_dialog_content = "교배기가 지나고 나면 드라코리온도 아마 콜로서스를 찾아오지 않을 거야.",
  ui_story_5028_50280701_31_dialog_content = "그랬으면 좋겠네.",
  ui_story_5028_50280701_32_dialog_content = "며칠 동안 계속 하늘에서 날아다니느라 스카이워커도 분명히 지쳤을 거야.",
  ui_story_5028_50280701_33_dialog_content = "피아의 풍부하고 깊은 학식을 믿어!",
  ui_story_5028_50280701_34_dialog_content = "루~",
  ui_story_5028_50280701_35_dialog_content = "그래, 그래.",
  ui_story_5028_50280701_36_dialog_content = "...어? 저게 뭐지?",
  ui_story_5028_50280701_37_dialog_content = "무슨 <color=#FFB400>신상</color> 같은데?",
  ui_story_5028_50280701_38_dialog_content = "저런 신상은 처음 보는 것 같은데.",
  ui_story_5028_50280701_39_dialog_content = "(이 기묘한 감각은 뭐지... 신상에서 왠지 무척 친근하고 편안한 기분이 느껴져.)",
  ui_story_5028_50280701_40_dialog_content = "저기, 저 신상에 기도하고 가지 않을래?\n어쩌면 시련을 완수하는 데 축복을 줄지도 모르잖아.",
  ui_story_5028_50280701_41_dialog_content = "그것도 괜찮을 것 같아. 딱히 손해 볼 것도 없으니까.",
  ui_story_5028_50280701_42_dialog_content = "(...뭐지? 신상이랑 가까워질수록 뭔가 현기증이 나는 느낌이야.)",
  ui_story_5028_50280701_43_dialog_content = "당신이 어떤 신인지는 모르겠지만,\n피아가 시련을 순조롭게 통과할 수 있게 축복해 주세요.",
  ui_story_5028_50280701_44_dialog_content = "드라코리온이 새로운 짝을 찾아서 스카이워커가 PlayerName 곁으로\n돌아갈 수 있게 해주세요.",
  ui_story_5028_50280701_45_dialog_content = "그리고 키아로가...",
  ui_story_5028_50280701_46_dialog_content = "......",
  ui_story_5028_50280701_47_dialog_content = "............",
  ui_story_5028_50280701_48_dialog_content = "어라? 뭔가 이상한데?",
  ui_story_5028_50280701_49_dialog_content = "축하해! 피아!",
  ui_story_5028_50280701_50_dialog_content = "넌 시련을 완수했어. 이제 넌 가장 위대한 환상동물 마스터야!",
  ui_story_5028_50280701_51_dialog_content = "뭐? 사부? 내가 가장 위대하다고?",
  ui_story_5028_50280701_52_dialog_content = "그래요, 어서 앉으세요.",
  ui_story_5028_50280701_53_dialog_content = "피아 님의 위대한 공적은 제 공적을 아득히 뛰어넘었습니다.\n환상동물에 대한 지식과 이해로 이 세상에서 당신을 앞설 사람은 없을 겁니다.",
  ui_story_5028_50280701_54_dialog_content = "저도 피아 님에게 비한다면 하늘과 땅 같은 차이일 겁니다.\n부디 절 제자로 삼아 주세요. 앞으로 피아 님께 배우고 싶습니다!",
  ui_story_5028_50280701_55_dialog_content = "헤헤헤, 그렇게까지 대단하진 않지만... 피아가 한번 생각은 해 볼게!",
  ui_story_5028_50280701_56_dialog_content = "피아 님.",
  ui_story_5028_50280701_57_dialog_content = "어? 넌 또 누구야?",
  ui_story_5028_50280701_58_dialog_content = "피아 님의 위대한 업적은 온 대륙에 널리 알려져 있습니다.\n그리고 저는 피아 님의 재능을 존경하는 사람 중 하나입니다.",
  ui_story_5028_50280701_59_dialog_content = "피아 님을 따르는 사람들이 이미 준비를 마치고 기다리고 있습니다.\n피아 님의 다음 모험을 지원해 드리고 싶습니다.",
  ui_story_5028_50280701_60_dialog_content = "피아! 피아! 피아!",
  ui_story_5028_50280701_61_dialog_content = "우와! 이렇게 많은 사람들이 날 떠받드는 거야?",
  ui_story_5028_50280701_62_dialog_content = "헤헤, 역시 위대한 일을 이루면 많은 사람들이 따르는 법이라니까.",
  ui_story_5028_50280701_63_dialog_content = "잠깐만... 뭔가 중요한 사람을 잊어버린 것 같은데...",
  ui_story_5028_50280701_64_dialog_content = "PlayerName! PlayerName, 어디 있어?",
  ui_story_5028_50280701_65_dialog_content = "<color=#e8d9bb>같은 시간</color>",
  ui_story_5028_50280701_66_dialog_content = "어라? 언제 콜로서스로 돌아왔지? 여긴...",
  ui_story_5028_50280701_67_dialog_content = "우와! 루맘버가 왜 이렇게 많은데?! 이거 꿈은 아니겠지?",
  ui_story_5028_50280701_68_dialog_content = "꿈이든 뭐든 알 게 뭐야. 오늘은 이 루맘버를 전부 오로리안의 소집에 쓰자!\n일단 100번 당겨보자!",
  ui_story_5028_50280701_69_dialog_content = "<color=#e8d9bb>펑──!</color>",
  ui_story_5028_50280701_70_dialog_content = "<color=#e8d9bb>쾅, 쾅──!</color>",
  ui_story_5028_50280701_71_dialog_content = "뭐야? 어디서 싸우는 소리가 나는 것 같은데?",
  ui_story_5028_50280701_72_dialog_content = "일어나── 이 바보야!",
  ui_story_5028_50280701_73_dialog_content = "방금 누가 날 욕한 것 같기도 하고?",
  ui_story_5028_50280701_74_dialog_content = "에이, 몰라! 열 번만 더 당기고 가서 살펴보자!",
  ui_story_5028_50280701_75_dialog_content = "캬아악!",
  ui_story_5028_50280701_76_dialog_content = "으악!",
  ui_story_5028_50280701_77_dialog_content = "아, 암귀?!",
  ui_story_5028_50280701_78_dialog_content = "뭐, 뭐가 어떻게 된 거야?",
  ui_story_5028_50280701_79_dialog_content = "피아? 여긴 어디야? 암귀가 왜 있어? 넌 또 누구고?",
  ui_story_5028_50280701_80_dialog_content = "쓸데없는 말 하지 말고 일어나서 싸워.",
  ui_story_5028_50280701_81_dialog_content = "<size=45>그어어어!</size>",
  ui_story_5028_50280701_82_dialog_content = "피아!",
  ui_story_5028_50280701_83_dialog_content = "아, 알았어... PlayerName. 가자! 키아로도!",
  ui_story_5028_50280702_1_dialog_content = "또 암귀를 만나다니...",
  ui_story_5028_50280702_2_dialog_content = "대체 어떻게 된 거야? 아까 우린 신상 앞에서 소원을 빌고 있었잖아?",
  ui_story_5028_50280702_3_dialog_content = "그러다 뭔가 멍하더니, 내가 환상동물 마스터가 된 꿈을 꿨어.",
  ui_story_5028_50280702_4_dialog_content = "나도야. 꿈에서 눈앞에 번쩍거리는 금색이랑 보라색의 무언가가 잔뜩 보였어...",
  ui_story_5028_50280702_5_dialog_content = "그리고 아는 오로리안들이 잔뜩 왔고,\n심지어 이제는 없는 오로리안들까지 내 동료가 됐어.",
  ui_story_5028_50280702_6_dialog_content = "너희 둘은 개꿈 꾸는 수준도 꽤 높구나.",
  ui_story_5028_50280702_7_dialog_content = "아까 신상에 소원을 빌었다고 했지?",
  ui_story_5028_50280702_8_dialog_content = "맞아, 그게 왜?",
  ui_story_5028_50280702_9_dialog_content = "무슨 신인지도 모르면서 소원을 빈 거야?",
  ui_story_5028_50280702_10_dialog_content = "그런 얼렁뚱땅한 태도로 환상동물 마스터가 되려고? 꿈 깨.",
  ui_story_5028_50280702_11_dialog_content = "일루미나에 가면 의무교육이 있거든.\n지금이라도 공부나 해서 월급 나오는 회사나 들어가지 그래?",
  ui_story_5028_50280702_12_dialog_content = "뭐라고?!",
  ui_story_5028_50280702_13_dialog_content = "넌 대체 누구야? 갑자기 나타나서 피아를 바보 취급하고!",
  ui_story_5028_50280702_14_dialog_content = "아까 좀 도와줬다고 해서 이런 식으로 굴면 안 되지!",
  ui_story_5028_50280702_15_dialog_content = "키아로, 혼내주자!",
  ui_story_5028_50280702_16_dialog_content = "......",
  ui_story_5028_50280702_17_dialog_content = "키아로?",
  ui_story_5028_50280702_18_dialog_content = "환상동물들은 지금 여기 없어. 감응이 안 돼.",
  ui_story_5028_50280702_19_dialog_content = "바보.",
  ui_story_5028_50280702_20_dialog_content = "내가 누군지는 알 거 없어.",
  ui_story_5028_50280702_21_dialog_content = "다만 그런 순진한 애들 장난 같은 태도로 환상동물 마스터가 되려는 거라면...",
  ui_story_5028_50280702_22_dialog_content = "그게 무슨 소리야? 키아로가 없어진 거야?",
  ui_story_5028_50280702_23_dialog_content = "...지금 당장 포기해!",
  ui_story_5028_50280702_24_dialog_content = "저들은 네 애완동물도 아니고, 소꿉놀이 상대도 아냐.\n네 마음대로 조종할 수 있는 온순한 동물은 더더욱 아냐.",
  ui_story_5028_50280702_25_dialog_content = "결의와 정신력이 없으면 힘든 세상을 살아갈 수 없어.\n환상동물 마스터가 되기도 전에 쓰러져서 끝이 날 뿐이야.",
  ui_story_5028_50280702_26_dialog_content = "키아로... 키아로...",
  ui_story_5028_50280702_27_dialog_content = "그것도 너뿐만이 아니고, 너와 함께했던 모든 사람들,\n네 그 소꿉놀이 「동료」들까지 포함해서 말이야.",
  ui_story_5028_50280702_28_dialog_content = "너, 너 역시 다들 어디 있는지 아는 거지?",
  ui_story_5028_50280702_29_dialog_content = "제발 좀 알려줘... 키아로랑 다들 지금 어디 있어?",
  ui_story_5028_50280702_30_dialog_content = "너 바보야? 내 말 못 알아듣는 거야?!",
  ui_story_5028_50280702_31_dialog_content = "여기 어디에도 키아로랑 다른 녀석들은 안 보여.\n우리 장비가 든 짐도 없어졌어.",
  ui_story_5028_50280702_32_dialog_content = "지금 그런 건 아무래도 좋으니까... 부탁이니까 어디 있는지 알려달라구!",
  ui_story_5028_50280702_33_dialog_content = "그 애들은 사부가 나한테 맡긴... 내 소중한 동료들이야.\n조금이라도 행방을 알고 있다면 제발 좀 알려줘!",
  ui_story_5028_50280702_34_dialog_content = "...그 멍청한 모습, 기분 나빠.",
  ui_story_5028_50280702_35_dialog_content = "난 가야겠어. 계속 여기 있고 싶으면 남아 있어.",
  ui_story_5028_50280702_36_dialog_content = "네 그 귀찮은 친구들이 산 밑에서 네가 올 때까지\n하루 종일 울고 있진 않을 것 같은데.",
  ui_story_5028_50280702_37_dialog_content = "어린애는 정말 귀찮다니까...",
  ui_story_5028_50280702_38_dialog_content = "피아!",
  ui_story_5028_50280702_39_dialog_content = "응!",
  ui_story_5028_50280702_40_dialog_content = "짐이나 장비는 없어져도 상관없어.\n지금 중요한 건 키아로랑 애들을 찾으러 가는 거야!",
  ui_story_5028_50280702_41_dialog_content = "잠깐만, 피아.",
  ui_story_5028_50280702_42_dialog_content = "방금 그 여자애, 뭔가 떨어트리고 간 것 같은데?",
  ui_story_5028_50280702_43_dialog_content = "이건 야외 탐험에 쓰는 나침반이랑 필수 장비들이야.",
  ui_story_5028_50280702_44_dialog_content = "없어졌던 내 장비들도 아니고, 아주 새 것처럼 보여.\n아마 저 사람이 일부러 자기 예비용 장비를 두고 간 거겠지.",
  ui_story_5028_50280702_45_dialog_content = "말은 거칠게 해도 사실은 좋은 사람이었구나.",
  ui_story_5028_50280702_46_dialog_content = "응! 다음에 만나면 꼭 고맙다고 인사해야겠네.",
  ui_story_5028_50280702_47_dialog_content = "게다가 저 사람 왠지 어디서 본 것 같단 말이야.",
  ui_story_5028_50280702_48_dialog_content = "키아로!",
  ui_story_5028_50280702_49_dialog_content = "루──!",
  ui_story_5028_50280702_50_dialog_content = "꾸룩...",
  ui_story_5028_50280702_51_dialog_content = "하이하이~",
  ui_story_5028_50280702_52_dialog_content = "페코~",
  ui_story_5028_50280702_53_dialog_content = "다행이야. 다들 신상이 있는 곳에서 기다리고 있었구나.",
  ui_story_5028_50280702_54_dialog_content = "그럼 방금 우린 왜 잠이 든 거지? 그리고 어떻게 아까 거기로 갔던 거야?",
  ui_story_5028_50280702_55_dialog_content = "루! 루루!",
  ui_story_5028_50280702_56_dialog_content = "키아로가 이 신상을 가리키는 것 같은데?",
  ui_story_5028_50280702_57_dialog_content = "역시 이 신상에 뭔가 문제가 있는 건가?",
  ui_story_5028_50280702_58_dialog_content = "구우...",
  ui_story_5028_50280702_59_dialog_content = "시, 신상이 움직였어?",
  ui_story_5028_50280702_60_dialog_content = "아, 아니야. 이건 애초에 신상이 아니었어!",
  ui_story_5028_50280702_61_dialog_content = "이건 <color=#FFB400>가골빼미</color>라는 환상동물이야! 이런 곳에서 만날 줄은 몰랐는데...",
  ui_story_5028_50280702_62_dialog_content = "개체 수가 적어서 멸종 직전이라고 사부가 그랬어.\n게다가 환상동물 대백과에 적힌 내용도 엄청 적어.",
  ui_story_5028_50280702_63_dialog_content = "내가 아는 건 이 녀석이 신상으로 위장해서 사람들이 소원을 빌러 오길 기다린다는 거야.",
  ui_story_5028_50280702_63X_dialog_content = "그리고 최면을 건 다음에 사람들이 가진 재물을 훔쳐서 도망치는 거지.",
  ui_story_5028_50280702_64_dialog_content = "구우... 구우...",
  ui_story_5028_50280702_65_dialog_content = "재물? 쟤가 그런 걸 뺏어서 뭐 해?",
  ui_story_5028_50280702_66_dialog_content = "아마 그냥 반짝거리는 동전 같은 걸 좋아하는 거겠지.\n그런 습성을 가진 동물은 많이 있으니까.",
  ui_story_5028_50280702_67_dialog_content = "구우!",
  ui_story_5028_50280702_68_dialog_content = "이런! 도망친다!",
  ui_story_5028_50280702_69_dialog_content = "루!",
  ui_story_5028_50280702_70_dialog_content = "잘했어, 키아로! 절대 놓치면 안 돼!",
  ui_story_5028_50280702_71_dialog_content = "잡았어!",
  ui_story_5028_50280702_72_dialog_content = "구우!",
  ui_story_5028_50280702_73_option_content = "(가골빼미를 힘껏 흔들다)",
  ui_story_5028_50280702_74_dialog_content = "PlayerName! 우리 물건들이 떨어져 나왔는데?",
  ui_story_5028_50280702_75_option_content = "(더 흔들어 본다)",
  ui_story_5028_50280702_76_dialog_content = "구구구!",
  ui_story_5028_50280702_77_dialog_content = "<color=#e8d9bb>흔들흔들</color>",
  ui_story_5028_50280702_78_dialog_content = "구우!",
  ui_story_5028_50280702_79_dialog_content = "점점 더 많아져! 이건 일루미나 통조림... 나이티움... 그리고 북방의 보석도 있는데?",
  ui_story_5028_50280702_80_dialog_content = "이 녀석한테 골탕 먹은 사람이 엄청 많았겠네. 다른 사람들 건 여기 두고 가자.",
  ui_story_5028_50280702_81_dialog_content = "헤헤, 그럼 너한테 선택의 기회를 줄게.",
  ui_story_5028_50280702_82_dialog_content = "구?",
  ui_story_5028_50280702_83_dialog_content = "여기서 곧바로 정의의 처단을 당할래?",
  ui_story_5028_50280702_84_dialog_content = "구구구!",
  ui_story_5028_50280702_85_dialog_content = "아니면 얌전히 날 따라올래?",
  ui_story_5028_50280702_86_dialog_content = "구우...",
  ui_story_5028_50280702_87_dialog_content = "구우!",
  ui_story_5028_50280702_88_dialog_content = "헤헤, 그럼 얌전히 날 따라와!",
  ui_story_5028_50280702_89_dialog_content = "피아는 널 데리고 사부한테 갈 거야. 사부한테 내 능력을 보여줄 거라구!",
  ui_story_5028_50280702_90_dialog_content = "후우...",
  ui_story_5028_50280702_91_dialog_content = "드르렁...",
  ui_story_5028_50280702_92_dialog_content = "후... 그람, 한 그릇 더!",
  ui_story_5028_50280702_93_dialog_content = "뭐, 뭐야? 잠들었었나?",
  ui_story_5028_50280702_94_dialog_content = "다들 그만 자! 일어나!",
  ui_story_5028_50280702_95_dialog_content = "우린 함정에 빠졌어!",
  ui_story_5028_50280702_96_dialog_content = "하, 그러니까 아까 그 망할 석상한테 속은 거란 말이지?",
  ui_story_5028_50280702_97_dialog_content = "그러니까 내가 소원 빌지 말라고 했잖아.",
  ui_story_5028_50280702_98_dialog_content = "그러게 무슨 연애운이야, 그런 건 다 사기라고.\n넌 어떻게 나이를 먹을수록 점점 더 미신을 믿는 거야?",
  ui_story_5028_50280702_99_dialog_content = "그러다간 재산도 다 날리겠네.",
  ui_story_5028_50280702_100_dialog_content = "나, 난 그냥 널 이기게 해달라고 빌었을 뿐이야!",
  ui_story_5028_50280702_101_dialog_content = "날 비웃을 시간이 있으면 얼른 가서 잃어버린 물건이나 찾는 게 어때?",
  ui_story_5028_50280702_102_dialog_content = "그 얄미운 신상은 어디 갔어?",
  ui_story_5028_50280702_103_dialog_content = "안 보이는데?",
  ui_story_5028_50280702_104_dialog_content = "잠깐만, 여기 뭔가 있어.",
  ui_story_5028_50280702_105_dialog_content = "야, 스모키, 이거 네가 전에 쓰던 일렉기타 피크 아냐?",
  ui_story_5028_50280702_106_dialog_content = "어, 진짜네. 이거 병뚜껑 딸 때 딱이거든.",
  ui_story_5028_50280702_107_dialog_content = "다른 건 없어?",
  ui_story_5028_50280702_108_dialog_content = "신상은 없어졌는데 물건은 있어.",
  ui_story_5028_50280702_109_dialog_content = "그리고 아이테르 냄새가 나.",
  ui_story_5028_50280801_1_dialog_content = "허접 사부, 피아가 돌아왔어!",
  ui_story_5028_50280801_2_dialog_content = "사부가 낸 온갖 잡다한 시련을 피아가 전부 완수했다구!",
  ui_story_5028_50280801_X2_dialog_content = "근데 키아로는 진화가 안 된 것 같은데?",
  ui_story_5028_50280801_3_dialog_content = "잠깐 실례할게...",
  ui_story_5028_50280801_4_dialog_content = "(뭐가 이렇게 정신없어?!)",
  ui_story_5028_50280801_5_dialog_content = "(책이 아무 데나 막 쌓여 있잖아. 이곳 주인, 생활 습관이 너무 나쁜 거 아냐?)",
  ui_story_5028_50280801_6_dialog_content = "피아, 이제 졸업할 수 있는 거지? 허접 사부, 사부──",
  ui_story_5028_50280801_7_dialog_content = "뭐지? 집이 엉망이 됐잖아!",
  ui_story_5028_50280801_8_dialog_content = "아... 원래 이런 게 아니었어?",
  ui_story_5028_50280801_9_dialog_content = "아니야. 허접 사부네 집은 어질러져 있으면서도 질서가 있거든.",
  ui_story_5028_50280801_10_dialog_content = "겉보기엔 어수선하게 쌓인 것처럼 보이지만 실제로는 꽤 정리돼 있어.",
  ui_story_5028_50280801_11_dialog_content = "사부는 책을 분야별로 한 더미에 던져 놓는다구.",
  ui_story_5028_50280801_12_dialog_content = "그리고 이상한 정리 습관이 있어서, 읽던 책은 펼친 상태로 맨 위에 놔.\n그래서 더 어질러진 것처럼 보이는 거야.",
  ui_story_5028_50280801_13_dialog_content = "봐, 여기 책더미는 곤충류에 대한 책이야. 맨 위의 두 권은 수생동물 책이고.",
  ui_story_5028_50280801_14_dialog_content = "중년 대머리 허접 사부는 별로 믿음직하진 않지만, 그래도 책을 엉망으로 두진 않을걸!",
  ui_story_5028_50280801_15_dialog_content = "그 말은 그러니까, 누가 여기 와서 비크 씨의 책을 만졌다는 거야?",
  ui_story_5028_50280801_16_dialog_content = "그럴지도 몰라. 지금 제일 중요한 건 사부를 찾는 일이야!",
  ui_story_5028_50280801_17_dialog_content = "허접 사부, 어디 갔어? 빨리 나와!",
  ui_story_5028_50280801_18_dialog_content = "<size=45>야──!</size>",
  ui_story_5028_50280801_19_option_content = "비크 씨!",
  ui_story_5028_50280801_20_dialog_content = "......",
  ui_story_5028_50280801_21_dialog_content = "여기 없나 본데.",
  ui_story_5028_50280801_22_dialog_content = "책상 서랍도 제대로 안 닫혀 있고, 의자도 제자리가 아냐.\n그리고 평소에 나한테 만지지 말라던 수집 선반의 문도 열려 있어.",
  ui_story_5028_50280801_23_dialog_content = "아무래도 비크 씨가 여길 떠날 때 엄청 당황했던 모양이네.",
  ui_story_5028_50280801_24_dialog_content = "집이 이렇게 어질러져 있다는 건, 설마...",
  ui_story_5028_50280801_25_dialog_content = "음, 그럴 가능성이 높겠어. 아무래도 비크 씨는 납...",
  ui_story_5028_50280801_26_dialog_content = "분명히 자기가 사기꾼이라는 걸 들킬 것 같아서 내가 돌아오기 전에 도망친 거야!",
  ui_story_5028_50280801_27_dialog_content = "하아?",
  ui_story_5028_50280801_28_dialog_content = "틀림없어.",
  ui_story_5028_50280801_29_dialog_content = "넌 비크 씨가 납치당했다는 생각 안 들어?",
  ui_story_5028_50280801_30_dialog_content = "뭐?!",
  ui_story_5028_50280801_31_dialog_content = "크흠, 나, 나도 진작에 생각하고 있었어!",
  ui_story_5028_50280801_32_dialog_content = "난 그저 사부 같은 사람을 납치하는 녀석이 정말 있을지 의심했을 뿐이야.",
  ui_story_5028_50280801_33_dialog_content = "뭐 하나 제대로 해낸 것도 없고, 술꾼에다가 주머니엔 나이티움 반쪽도 없어...",
  ui_story_5028_50280801_34_dialog_content = "그래도 너네 사부인데 그렇게 말할 것까지야...",
  ui_story_5028_50280801_35_dialog_content = "그럼 이제 어떡하지?",
  ui_story_5028_50280801_36_dialog_content = "사부를 못 찾으면 졸업도 못 하고, 환상동물 마스터도 될 수 없어.",
  ui_story_5028_50280801_37_dialog_content = "그러니까 역시 먼저 사부를 찾아야지.",
  ui_story_5028_50280801_38_dialog_content = "그럼 일단 이 부근에서 단서를 찾자. 비크 씨의 흔적이 있는지 말이야.",
  ui_story_5028_50280801_39_dialog_content = "흥, 허접 사부, 정말 번거롭게 만든다니까.",
  ui_story_5028_50280801_40_dialog_content = "그럼 내가 단서를 찾아볼게!",
  ui_story_5028_50280801_41_dialog_content = "<color=#e8d9bb>콰당!</color>",
  ui_story_5028_50280801_42_dialog_content = "<color=#e8d9bb>퍽──! 쨍그랑──!</color>",
  ui_story_5028_50280801_43_dialog_content = "그만, 그만, 얼른 멈춰!",
  ui_story_5028_50280801_44_dialog_content = "그게 어딜 봐서 단서를 찾는 거야?! 이건 현장 훼손이라고!",
  ui_story_5028_50280801_45_dialog_content = "다, 단서를 찾다가 실수로 물건을 좀 망가트릴 수도 있는 거 아냐?",
  ui_story_5028_50280801_46_dialog_content = "그런 식으로 찾다간 집을 통째로 부술 것 같은데.",
  ui_story_5028_50280801_47_dialog_content = "피아는 그런 난폭한 짓 안 하거든!",
  ui_story_5028_50280801_48_dialog_content = "그냥 내가 찾을게...",
  ui_story_5028_50280801_49_dialog_content = "이대로면 온 집을 네가 해체할 것 같으니까.",
  ui_story_5028_50280801_50_dialog_content = "야──!",
  ui_story_5028_50280801_51_dialog_content = "결국 처음부터 다시 시작이네.",
  ui_story_5028_50280801_52_dialog_content = "어디서부터 찾아야 하지?",
  ui_story_5028_50280801_53_option_content = "(책상 주변을 살펴보자)",
  ui_story_5028_50280801_54_dialog_content = "책상 서랍이 다 열려 있어. 내용물도 엉망으로 뒤적여 놨고...",
  ui_story_5028_50280801_55_dialog_content = "뭐, 사부는 평소에도 서랍에 아무렇게나 물건을 넣었지만,\n그래도 서랍마다 분류를 해 뒀었단 말이야.",
  ui_story_5028_50280801_56_dialog_content = "이 빈 서랍엔 뭐가 들어 있었는데?",
  ui_story_5028_50280801_57_dialog_content = "음, 아마 환상동물에 대한 원고였던 것 같아.",
  ui_story_5028_50280801_58_dialog_content = "전에 사부가 나한테 키아로를 맡기기 전에,\n먼저 여기서 원고를 꺼내 보고 그 뒤에 결정했던 기억이 나.",
  ui_story_5028_50280801_59_dialog_content = "근데 그 원고도 지금은 없어졌어...",
  ui_story_5028_50280801_60_dialog_content = "잠깐만, 책상 밑에 무슨 종이가 있는데?",
  ui_story_5028_50280801_61_dialog_content = "보여줘!",
  ui_story_5028_50280801_62_dialog_content = "동그라미 하나, 그리고 그 안에 엑스 표가 그려져 있어...",
  ui_story_5028_50280801_63_dialog_content = "급하게 쓴 것 같아. 잉크가 아직 다 마르지 않았다는 건... 쓴 지 얼마 안 됐다는 거야!",
  ui_story_5028_50280801_64_dialog_content = "암호인가?",
  ui_story_5028_50280801_65_dialog_content = "잘 모르겠어...",
  ui_story_5028_50280801_66_option_content = "(책꽂이 주변을 살펴보자)",
  ui_story_5028_50280801_67_dialog_content = "책꽂이의 책들은 의외로 가지런히 정리돼 있어.",
  ui_story_5028_50280801_68_dialog_content = "근데 사부는 이쪽에 있는 책은 자주 안 보는 편이었어.\n그리고 청소도 싫어해서 먼지가 쌓여 있어.",
  ui_story_5028_50280801_69_dialog_content = "봐, 맨 위에 있는 저 책엔 먼지가 안 쌓였어.\n그럼 저 책은 자주 읽었다는 뜻이겠지.",
  ui_story_5028_50280801_70_dialog_content = "저 책을 꺼내 보자.",
  ui_story_5028_50280801_71_dialog_content = "쳇, 안 닿잖아!",
  ui_story_5028_50280801_72_dialog_content = "풉!",
  ui_story_5028_50280801_73_dialog_content = "웃지 마!",
  ui_story_5028_50280801_74_dialog_content = "야, PlayerName, 넌 키가 크니까 저 책 좀 꺼내 줘.",
  ui_story_5028_50280801_75_dialog_content = "에잇!",
  ui_story_5028_50280801_76_dialog_content = "어라? 책 안에 사진이 한 장 끼워져 있는데?",
  ui_story_5028_50280801_77_dialog_content = "그 사진에 있는 사람이 비크 사부야. 근데 한쪽은 찢겨 버렸잖아...",
  ui_story_5028_50280801_78_dialog_content = "그 녀석이 계속 가지고 있었던 걸 보면 아마 중요한 사진이라는 거겠지.",
  ui_story_5028_50280801_79_dialog_content = "옆에 있는 사람, 왠지 수상해 보여... 대체 누구지?",
  ui_story_5028_50280801_80_dialog_content = "하루 종일 집을 뒤져서 다리가 저려. 찾은 단서는 고작 이것뿐인가...",
  ui_story_5028_50280801_81_dialog_content = "어떡하지?",
  ui_story_5028_50280801_82_dialog_content = "......",
  ui_story_5028_50280801_83_dialog_content = "저기, 피아...",
  ui_story_5028_50280801_84_dialog_content = "왠지 등 뒤가 서늘하지 않아?",
  ui_story_5028_50280801_85_dialog_content = "그...그러게...",
  ui_story_5028_50280801_86_dialog_content = "너희들...",
  ui_story_5028_50280801_87_dialog_content = "흐이익!",
  ui_story_5028_50280801_88_dialog_content = "그, 그 이상한 녀석이야!",
  ui_story_5028_50280801_89_dialog_content = "도둑질을 할 거면 값어치가 있을 만한 물건을 가져갔으면 됐지.\n뭐, 여긴 딱히 귀중품 같은 것도 없지만.",
  ui_story_5028_50280801_90_dialog_content = "하지만 이 집을 엉망으로 만든 건 용서할 수 없어.",
  ui_story_5028_50280801_91_dialog_content = "엉망이 된 책들을 분류해서 제자리에 놓으려면 무척 번거롭거든.",
  ui_story_5028_50280801_92_dialog_content = "수집 선반의 문도 열려 있잖아. 수집품이 전부 먼지투성이가 됐어.\n깨끗하게 정리하려면 적어도 며칠은 걸리겠는걸.",
  ui_story_5028_50280801_93_dialog_content = "더 끔찍한 건, 내가 몇 년 동안 정리한 환상동물의 분포도와\n귀중한 원고들이 전부 없어졌다는 거야.",
  ui_story_5028_50280801_94_dialog_content = "마, 맞아! 정말 끔찍하네!",
  ui_story_5028_50280801_95_dialog_content = "저기... 일단 진정해!",
  ui_story_5028_50280801_96_dialog_content = "우리가 꼭──",
  ui_story_5028_50280801_97_dialog_content = "아니.",
  ui_story_5028_50280801_98_dialog_content = "이 귀중한 자료들은 값을 매길 수 없어. 너흰 절대 못 갚아.",
  ui_story_5028_50280801_99_dialog_content = "잠깐만! 이건 우리가 한 게 아니야!",
  ui_story_5028_50280801_100_dialog_content = "맞아. 우리가 집에 돌아왔을 때 비크 사부는 없었어.\n그리고 집 안도 이미 엉망이었다니까!",
  ui_story_5028_50280801_101_dialog_content = "단서를 찾다가 실수로 의자 하나, 꽃병 두 개, 유리잔 세 개를 망가트렸을 뿐이라구...",
  ui_story_5028_50280801_102_dialog_content = "넌 좀 조용히 있어!",
  ui_story_5028_50280801_103_dialog_content = "변명해도 소용없어. 이렇게 물증이 확실하잖아.",
  ui_story_5028_50280801_104_dialog_content = "평범한 환상동물 애호가인 줄 알았는데, 이런 범죄자들일 줄은 몰랐네.",
  ui_story_5028_50280801_105_dialog_content = "얌전하게 내 손해를 물어내.",
  ui_story_5028_50280801_110_dialog_content = "이 폭력녀! 남의 말을 좀 들어! 우리가 한 게 아니라고 했잖아!",
  ui_story_5028_50280801_112_dialog_content = "꺄앗──!",
  ui_story_5028_50280801_113_dialog_content = "뭐야?! 말도 없이 공격부터 하는 거야?!",
  ui_story_5028_50280801_114_dialog_content = "나도 싸우고 싶진 않아. 손가락이나 촉수를 움직이는 것만으로도 피곤하거든.",
  ui_story_5028_50280801_X114_dialog_content = "그러니까 얼른 자백해.",
  ui_story_5028_50280801_115_dialog_content = "진짜로 우리가 아니라니까!",
  ui_story_5028_50280801_116_dialog_content = "흐이익!",
  ui_story_5028_50280801_117_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5028_50280801_118_dialog_content = "초, 촉수가 닿은 바닥에 커다란 구멍이 뚫려버렸잖아...",
  ui_story_5028_50280801_119_dialog_content = "맞았으면 끝장이었겠어!",
  ui_story_5028_50280801_120_dialog_content = "그래, 아주 아플 거야.",
  ui_story_5028_50280801_121_dialog_content = "얼른 멈춰! 우린 물건을 훔치려던 게 아냐!",
  ui_story_5028_50280801_122_dialog_content = "우린 그저 실종된 비크 씨가 남긴 단서가 있는지 찾으려고 했을 뿐이라고!",
  ui_story_5028_50280801_123_dialog_content = "사부가 실종됐다고? 근데 너네가 아니라면 대체 누군데?",
  ui_story_5028_50280801_124_dialog_content = "우리도 몰라...",
  ui_story_5028_50280801_125_dialog_content = "대신 단서가 있어!",
  ui_story_5028_50280801_126_dialog_content = "단서? 그런 걸 찾는 건 귀찮아. 추리하는 건 더 귀찮아. 대신 들어는 줄게.",
  ui_story_5028_50280801_127_dialog_content = "그래서 뭘 찾았는데? 어디 말해 봐.",
  ui_story_5028_50280801_128_dialog_content = "사부가 안에 엑스 표가 있는 동그라미 하나를 종이에 그려뒀어.\n게다가 아직 그린 지 얼마 안 됐어!",
  ui_story_5028_50280801_129_dialog_content = "맞아. 그리고 어느 책에서 이 사진을 찾았어.",
  ui_story_5028_50280801_130_dialog_content = "잠깐만, 너 비크를 「사부」라고 불렀어?",
  ui_story_5028_50280801_131_dialog_content = "그래!",
  ui_story_5028_50280801_132_dialog_content = "난 한동안 사부 밑에서 공부했고, 지금은 사부가 준 임무를 마치고 곧 졸업할 참이었어!",
  ui_story_5028_50280801_133_dialog_content = "증거는 바로 이 키아로야. 허접 사부가 나한테 돌보라고 맡겼거든!",
  ui_story_5028_50280801_134_dialog_content = "어, 키아로는?",
  ui_story_5028_50280801_135_dialog_content = "루? 루루...",
  ui_story_5028_50280801_136_dialog_content = "여기 있었구나. 어떻게 책더미 안에서 잘 수가 있어? 얼른 나와!",
  ui_story_5028_50280801_137_dialog_content = "확실히 비크가 키우던 키아로가 맞네. 게다가 널 멀리하지도 않잖아...",
  ui_story_5028_50280801_138_dialog_content = "환상동물들이 널 믿는 걸 보면, 나도 더는 널 의심할 필요는 없겠어.",
  ui_story_5028_50280801_139_dialog_content = "그럼 이젠 믿는 거지?!",
  ui_story_5028_50280801_140_dialog_content = "휴, 내가 환상동물을 찾으러 다니는 동안 비크가 또 귀찮은 일을 벌인 모양이네.",
  ui_story_5028_50280801_141_dialog_content = "어린애 돌보는 게 제일 귀찮은데.",
  ui_story_5028_50280801_142_dialog_content = "난 어린애가 아니라구!",
  ui_story_5028_50280801_143_dialog_content = "너 대체 누구야? 왜 비크 사부를 잘 아는 것 같은 건데?",
  ui_story_5028_50280801_144_dialog_content = "내가 누구냐고? 글쎄, 내가 누굴까...",
  ui_story_5028_50280801_145_dialog_content = "관계가 너무 복잡해서 생각만 해도 피곤한걸...",
  ui_story_5028_50280801_146_dialog_content = "다만, 비크가 네 사부라면, 나는 네 선배인 셈이겠지.",
  ui_story_5028_50280801_147_dialog_content = "<color=#FFB400>시라</color>, 내 이름이야.",
  ui_story_5028_50280801_148_dialog_content = "시라",
  ui_story_5028_50280801_X148_dialog_content = "21세",
  ui_story_5028_50280801_X149_dialog_content = "신비한 문어 소녀",
  ui_story_5028_50280801_149_dialog_content = "선배?! 사부한테 그런 말은 들은 적 없어.",
  ui_story_5028_50280801_150_dialog_content = "그 사람은 항상 그래. 뭐든 제대로 설명하는 일이 없어.",
  ui_story_5028_50280801_151_dialog_content = "가끔은 나도 모르겠거든. 그 사람이 가르쳐 준 지식이랑,\n나한테 숨기고 있는 것 중에 대체 어느 쪽이 더 많을까?",
  ui_story_5028_50280801_152_dialog_content = "그 사람을 대하는 건 정말 번거로운 일이야.",
  ui_story_5028_50280801_153_dialog_content = "고생이 많았겠네...",
  ui_story_5028_50280801_154_dialog_content = "괜찮아. 이젠 익숙하거든.",
  ui_story_5028_50280801_155_dialog_content = "하던 얘기로 돌아가자. 이 사진의 의미는 나도 모르겠어.",
  ui_story_5028_50280801_156_dialog_content = "관계가 있는 이야기를 전에 비크가 말해줬을 수도 있지만,\n적어도 지금 내 기억엔 없어.",
  ui_story_5028_50280801_157_dialog_content = "잠깐만, 너 기억력 좋은 거 아니야?",
  ui_story_5028_50280801_158_dialog_content = "그 많은 희귀한 환상동물들의 습성이나 특징을 다 기억하고 있잖아!",
  ui_story_5028_50280801_159_dialog_content = "환상동물 외의 것들을 기억하는 건 귀찮아.",
  ui_story_5028_50280801_160_dialog_content = "야!",
  ui_story_5028_50280801_161_dialog_content = "근데 이 기호의 의미는 알아.",
  ui_story_5028_50280801_162_dialog_content = "이건 비크가 남긴 암호야. 그 사람, 납치됐어.",
  ui_story_5028_50280801_163_dialog_content = "이 근처에는 강도가 자주 출몰해.\n그래서 비크는 가끔 암호를 남기고 나한테 도움을 요청하곤 했어.",
  ui_story_5028_50280801_164_dialog_content = "역시 납치였구나!",
  ui_story_5028_50280801_165_dialog_content = "그럼 큰일이잖아... 이제 곧 협박 편지가 올까?",
  ui_story_5028_50280801_166_dialog_content = "「네 사부를 구하고 싶다면 1000만 나이티움을 준비해라」...\n그런 말을 들어도 난 돈이 없는데...",
  ui_story_5028_50280801_167_dialog_content = "만약 사부가 어떻게 되기라도 한다면... 난 영원히 졸업할 수가 없잖아!",
  ui_story_5028_50280801_168_dialog_content = "지금 졸업이 문제가 아니잖아!",
  ui_story_5028_50280801_169_dialog_content = "이상해. 납득이 안 돼.",
  ui_story_5028_50280801_170_dialog_content = "평소에도 강도한테 자주 습격당하지만, 비크는 가난해서 한 푼도 없어.",
  ui_story_5028_50280801_171_dialog_content = "그래서 항상 강도가 난리를 쳐도 결국엔 그냥 가버렸어.\n거기서 더 심해 봤자 비크를 때리는 정도로 끝이야.",
  ui_story_5028_50280801_172_dialog_content = "그런데 이번엔 비크를 납치해 갔어.",
  ui_story_5028_50280801_173_dialog_content = "왜 그렇게 이득도 안 되는 짓을 했을까?",
  ui_story_5028_50280801_174_dialog_content = "비크를 데려가 봤자 음식이랑 물만 축낼 뿐이야.\n돈이 될 만한 건 전혀 나오지 않아.",
  ui_story_5028_50280801_175_dialog_content = "납치범을 불쌍하게 생각해야 할지...\n아니면 너희 사부를 불쌍하게 생각해야 할지 참...",
  ui_story_5028_50280801_176_dialog_content = "너 말이야... 이런 귀찮은 일에 휘말린 자신부터 불쌍하게 여기는 게 어때?",
  ui_story_5028_50280801_177_dialog_content = "그, 그것도 그렇네...",
  ui_story_5028_50280801_178_dialog_content = "대체 누가 이런 짓을... 설마...",
  ui_story_5028_50280801_179_dialog_content = "큰일이네.",
  ui_story_5028_50280801_180_dialog_content = "야! 기다려!",
  ui_story_5028_50280801_181_dialog_content = "그래서 대체 누가 비크 사부를 납치한 거냐고?! 야!",
  ui_story_5028_50280801_182_dialog_content = "잠깐 사이에 사라져 버렸잖아...",
  ui_story_5028_50280801_183_dialog_content = "허접 사부는 실종됐고, 선배는 홀랑 말 한 마디만 하고 사라져 버리고...",
  ui_story_5028_50280801_184_dialog_content = "대체 둘 다 왜 저래? 왜 하나같이 제대로 말을 안 해주는 거냐고!",
  ui_story_5028_50280801_185_dialog_content = "일단 시라부터 쫓아가자.",
  ui_story_5028_50280801_186_dialog_content = "거리 쪽으로 간 것 같으니까 우리도 가자.",
  ui_story_5028_50280801_187_dialog_content = "거리엔 사람이 많으니까, 아마 누가 봤을지도 몰라.",
  ui_story_5028_50280801_188_dialog_content = "응!",
  ui_story_5028_50280901_1_dialog_content = "저기, 혹시 흰 머리에 문어 다리가 달린 젊은 여자 못 봤어?",
  ui_story_5028_50280901_4_dialog_content = "앗, 피아잖아?",
  ui_story_5028_50280901_5_dialog_content = "같이 있는 사람은 누구야?",
  ui_story_5028_50280901_6_dialog_content = "어? 너였구나, 신문 파는 애.",
  ui_story_5028_50280901_7_dialog_content = "이쪽은 PlayerName, 「환상동물 마스터」인 내 파트너야.",
  ui_story_5028_50280901_8_dialog_content = "우린 지금 사람을 찾고 있어. 뭔가 단서가 없을까?",
  ui_story_5028_50280901_12_dialog_content = "젊은 여자는 잘 모르겠는데, 너네 사부 비크 씨가 왠지 위험에 처한 것 같아!",
  ui_story_5028_50280901_13_dialog_content = "그래, 비크가 실종된 건 이 「환상동물 마스터」도 알고 있어.\n지금 막 찾고 있던 중이야.",
  ui_story_5028_50280901_14_dialog_content = "역시...",
  ui_story_5028_50280901_15_dialog_content = "아무튼, 얼마 전에 어떤 키가 큰 남자가 비크 씨를 납치해 가는 걸 봤어.",
  ui_story_5028_50280901_16_dialog_content = "섀도우마스터의 부하한테는 이미 말했지만, 뭔가 조치를 취했는지는 잘 모르겠어...",
  ui_story_5028_50280901_17_dialog_content = "어떻게 생겼는지는 기억해?",
  ui_story_5028_50280901_18_dialog_content = "미안, 그냥 커다란 사람이 비크 씨를 둘러메고는 도시 밖으로 나가는 것만 봤어.\n정확히 어떻게 생겼는지 같은 건 못 봤고.",
  ui_story_5028_50280901_19_dialog_content = "그래도 옷은 기억해. 이 근처에 출몰하는 강도 같았어.",
  ui_story_5028_50280901_20_dialog_content = "강도?",
  ui_story_5028_50280901_21_dialog_content = "알겠어. 그럼 나머지는 이 「환상동물 마스터」한테 맡겨.",
  ui_story_5028_50280901_22_dialog_content = "무모하게 굴면 절대 안 돼, 피아.",
  ui_story_5028_50280901_23_dialog_content = "안 될 것 같으면 돈을 좀 내고 섀도우마스터의 도움을 받아...",
  ui_story_5028_50280901_24_dialog_content = "걱정 마. 우리끼리 해낼 수 있으니까.",
  ui_story_5028_50280901_25_dialog_content = "그럼 다행이고... 그럼 난 갈게.",
  ui_story_5028_50280901_26_dialog_content = "휴, 나도 도움을 받고 싶긴 한데...",
  ui_story_5028_50280901_27_dialog_content = "사부는 돈이 한 푼도 없단 말이야.",
  ui_story_5028_50280901_28_dialog_content = "우리 둘만 가지고 정말 강도를 상대할 수 있어?",
  ui_story_5028_50280901_29_dialog_content = "왜 「우리 둘」인데?",
  ui_story_5028_50280901_30_dialog_content = "잊으면 안 되지. 난 「환상동물 마스터」라구.\n환상동물 동료들이 이렇게 많이 있잖아!",
  ui_story_5028_50280901_31_dialog_content = "페코페코!",
  ui_story_5028_50280901_32_dialog_content = "꾸룩──",
  ui_story_5028_50280901_33_dialog_content = "응, 응! 알겠어. 너희도 사부를 돕고 싶은 거지?",
  ui_story_5028_50280901_34_dialog_content = "너희들이 도와준다면 분명히 해낼 수 있을 거야.",
  ui_story_5028_50280901_35_dialog_content = "루우──",
  ui_story_5028_50280901_36_dialog_content = "네 말은 알아들을 수 없지만, 내가 꼭 노력해서 사부를 구해낼게!",
  ui_story_5028_50280901_37_dialog_content = "지식을 노리는 기괴한 강도가 가난에 찌든 비크 씨를 납치해 갔다...",
  ui_story_5028_50280901_38_dialog_content = "어떻게 하면 단서를 찾을 수 있을까?",
  ui_story_5028_50280901_39_dialog_content = "설마 진짜로 섀도우마스터한테 도움을 요청해야 되는 거야?",
  ui_story_5028_50280901_40_dialog_content = "분명히 더 좋은 방법이 있을 거야.",
  ui_story_5028_50280901_41_dialog_content = "어디 보자...",
  ui_story_5028_50280901_42_dialog_content = "강도라면 목표물을 노리는 것도 중요하지만,\n아마 다른 강도의 정보에도 관심이 많을 거야.",
  ui_story_5028_50280901_43_dialog_content = "그런 녀석들은 법도 안 지키고, 항상 세력 다툼을 해댈 테니까.",
  ui_story_5028_50280901_44_dialog_content = "강도 한 명을 잡아서 심문할 수 있다면 분명히 단서를 찾을 수 있을 거야!",
  ui_story_5028_50280901_45_dialog_content = "근데 강도를 어떻게 찾지?",
  ui_story_5028_50280901_46_dialog_content = "뭐? 강도 찾는 거?",
  ui_story_5028_50280901_47_dialog_content = "그거야 간단하지!",
  ui_story_5028_50280901_48_dialog_content = "피아랑 PlayerName 둘이서 부자인 척하면 되잖아!",
  ui_story_5028_50280901_49_dialog_content = "예를 들면──",
  ui_story_5028_50280901_50_dialog_content = "서, 설마...",
  ui_story_5028_50280901_51_dialog_content = "안 돼! 난 반대야!",
  ui_story_5028_50280901_52_dialog_content = "이건 내가 땅에서 나온 뒤부터 지금까지 열심히 모은 돈이라고!",
  ui_story_5028_50280901_53_dialog_content = "PlayerName 오빠, 비크 사부를 구하고 싶지 않아?",
  ui_story_5028_50280901_54_dialog_content = "......",
  ui_story_5028_50280901_55_dialog_content = "피아가 졸업을 못 해서 영원히 환상동물 마스터가 될 수 없길 바라는 거야?",
  ui_story_5028_50280901_56_dialog_content = "............",
  ui_story_5028_50280901_57_dialog_content = "훌쩍... 알았어. 피아는 이만 갈게.",
  ui_story_5028_50280901_58_dialog_content = "피아는 혼자서라도 사부를 구하러 갈 거야. 강도한테 잡히더라도...\nPlayerName한테는 도와달라고 안 할 테니까!",
  ui_story_5028_50280901_X58_dialog_content = "흐아아앙!",
  ui_story_5028_50280901_X59_dialog_content = "..................",
  ui_story_5028_50280901_X60_dialog_content = "너무하잖아!",
  ui_story_5028_50280901_59_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_5028_50280901_60_dialog_content = "운도 특산, 사과사탕, 도미빵 사세요──",
  ui_story_5028_50280901_61_dialog_content = "손님, 뭐로 드릴까요?",
  ui_story_5028_50280901_62_dialog_content = "여기 있는 거 전부 다 10개씩 주세요. 돈은 이 사람이 낼 거니까요!",
  ui_story_5028_50280901_63_dialog_content = "네... 제, 제가 낼게요...!",
  ui_story_5028_50280901_64_dialog_content = "정말 통 큰 손님이시군요! 지금 바로 준비하겠습니다!",
  ui_story_5028_50280901_65_dialog_content = "우와! 맛있는 게 진짜 많네!",
  ui_story_5028_50280901_66_dialog_content = "(왜 나는 부자인 척하자는 계획에 동의한 걸까...!)",
  ui_story_5028_50280901_67_dialog_content = "(이렇게 돈을 많이 쓰면 분명히 바이스한테 혼날 거라고!)",
  ui_story_5028_50280901_68_dialog_content = "냠냠, 이거 진짜 맛있어!",
  ui_story_5028_50280901_69_dialog_content = "하나 더 주세요!",
  ui_story_5028_50280901_70_dialog_content = "네, 갑니다!",
  ui_story_5028_50280901_71_dialog_content = "(아아... 또 열흘은 아르바이트를 해야겠네...)",
  ui_story_5028_50280901_72_dialog_content = "......",
  ui_story_5028_50280901_73_dialog_content = "(저기 저 사람, 계속 우릴 보는 것 같은데?)",
  ui_story_5028_50280901_74_dialog_content = "누가 우릴 노려보고 있어. 왠지 강도의 눈에 띈 것 같아.",
  ui_story_5028_50280901_75_dialog_content = "마침 배도 불렀겠다, 그럼 다음 단계로 넘어가자.",
  ui_story_5028_50280901_76_dialog_content = "크흠!",
  ui_story_5028_50280901_77_dialog_content = "진짜 맛있었어. 이제 쇼핑이나 갈까?",
  ui_story_5028_50280901_78_dialog_content = "물론 그래야지. 내가 갖고 싶은 게 있으면 사 줄 거지?",
  ui_story_5028_50280901_79_dialog_content = "그, 그런 건 계획에 없었잖아?!",
  ui_story_5028_50280901_80_dialog_content = "<size=45>크흠──!</size>",
  ui_story_5028_50280901_81_dialog_content = "아파! 차지 마!",
  ui_story_5028_50280901_82_dialog_content = "아, 알았어. 사 줄게!",
  ui_story_5028_50280901_83_dialog_content = "뭐든지 네가 마음에 드는 거면 다 사 줄게!",
  ui_story_5028_50280901_84_dialog_content = "음, 그래야지!",
  ui_story_5028_50280901_85_dialog_content = "(이래서야 해명할 수도 없겠어...)",
  ui_story_5028_50280901_86_dialog_content = "(바이스, 미안... 나 또 돈 다 써버릴 것 같아...)",
  ui_story_5028_50280901_87_dialog_content = "(스카이워커, 미안해... 다음 달 유지보수 경비가 또 비어버려...)",
  ui_story_5028_50280901_88_dialog_content = "......",
  ui_story_5028_50280901_89_dialog_content = "저기, 저 멀리 보이는 저 사람, 왠지 PlayerName 닮지 않았어?",
  ui_story_5028_50280901_90_dialog_content = "저건 닮은 게 아니라 그냥 본인이잖아.",
  ui_story_5028_50280901_91_dialog_content = "근데 여기선 너무 멀어서 채찍으로 묶을 수가 없겠는걸. 유감이네.",
  ui_story_5028_50280901_93_dialog_content = "조──종──사──",
  ui_story_5028_50280901_94_dialog_content = "기다려──",
  ui_story_5028_50280901_95_dialog_content = "이 거리에선 무리야. 사이에 번화가를 끼고 있으니까 아마 안 들리겠지.",
  ui_story_5028_50280901_96_dialog_content = "뭔 잔소리가 그렇게 많아? 바로 쫓아가면 될 걸 가지고.",
  ui_story_5028_50280901_97_dialog_content = "<color=#e8d9bb>마을 밖</color>",
  ui_story_5028_50280901_98_dialog_content = "(말은 쇼핑이라고 해 놓고, 피아는 인적이 드문 마을 밖으로 와버렸잖아...)",
  ui_story_5028_50280901_99_dialog_content = "후후, 여기면 딱 좋겠어.",
  ui_story_5028_50280901_100_dialog_content = "PlayerName, 피곤해. 여기서 좀 쉬자!",
  ui_story_5028_50280901_101_dialog_content = "아, 그, 그래.",
  ui_story_5028_50280901_102_dialog_content = "근데 여긴 좀 위험하지 않을까?",
  ui_story_5028_50280901_103_dialog_content = "내가 있잖아. 뭘 무서워하고 그래?",
  ui_story_5028_50280901_104_dialog_content = "즐거워 보이는군.",
  ui_story_5028_50280901_105_dialog_content = "아까부터 쭉 따라온 그 녀석이야!",
  ui_story_5028_50280901_106_dialog_content = "이미 알고 있다면 이야기가 빠르겠어.",
  ui_story_5028_50280901_107_dialog_content = "돈깨나 있는 부잣집 도련님과 아가씨 같은데, 같이 좀 가 주실까?",
  ui_story_5028_50280901_108_dialog_content = "어쩔 수 없네, PlayerName. 따라가자.",
  ui_story_5028_50280901_109_dialog_content = "뭐?!",
  ui_story_5028_50280901_110_dialog_content = "이쪽 아가씨는 뭘 좀 아는군그래. 자, 손을 묶을 테니 뒤쪽으로 내밀어라.",
  ui_story_5028_50280901_111_dialog_content = "(대체 어떻게 된 거야? 제대로 물어봐야겠어!)",
  ui_story_5028_50280901_112_option_content = "(강제 감응!)",
  ui_story_5028_50280901_113_dialog_content = "(피아, 내 말 들려? 대체 무슨 생각이야?!)",
  ui_story_5028_50280901_114_dialog_content = "(으앗! 또, 또 이거야?!)",
  ui_story_5028_50280901_115_dialog_content = "(당황하지 마. 그냥 겸사겸사 태워달라고 하는 거니까.\n그럼 이 강도들의 소굴까지 바로 갈 수 있잖아.)",
  ui_story_5028_50280901_116_dialog_content = "(그러면 우리도 찾는 수고를 덜 수 있어.)",
  ui_story_5028_50280901_117_dialog_content = "(이래도 괜찮을까?!)",
  ui_story_5028_50280901_118_dialog_content = "(넌 그냥 잘 보고 있어. 지금은 인내심을 가지고 기다려야 돼...)",
  ui_story_5028_50280901_119_dialog_content = "오늘은 운이 좋군. 아까 노리던 목표는 다른 놈들이 선수를 쳤는데.",
  ui_story_5028_50280901_120_dialog_content = "그 뒤에 대물을 낚을 줄 누가 알았겠어? 하하하!",
  ui_story_5028_50280901_121_dialog_content = "똑바로 묶었나? 그럼...",
  ui_story_5028_50280901_122_dialog_content = "크억!",
  ui_story_5028_50280901_123_dialog_content = "사람 찾는 건 정말 귀찮다니까.",
  ui_story_5028_50280901_124_dialog_content = "꼭 필요한 일이 아니었다면 내가 쉬어야 할 시간에\n강도나 찾는 짓 따윈 하고 싶지 않았어.",
  ui_story_5028_50280901_125_dialog_content = "시라?! 또 너야?!",
  ui_story_5028_50280901_126_dialog_content = "「또 너」? 그래, 왜 또 너네야?",
  ui_story_5028_50280901_127_dialog_content = "말했잖아. 귀찮게 만들지 말라고.",
  ui_story_5028_50280901_128_dialog_content = "그런데도 멋대로 따라오더니, 그것도 모자라서 강도들이랑 한패가 되고 말이야.",
  ui_story_5028_50280901_129_option_content = "딱 봐도 납치당한 거잖아!",
  ui_story_5028_50280901_130_option_content = "누가 봐도 「한패」가 아니라고!",
  ui_story_5028_50280901_131_dialog_content = "이건 우리 계획이었어. 근데 너 때문에 망했어!",
  ui_story_5028_50280901_133_dialog_content = "계획? 뭐, 됐어. 너희가 뭘 하든 나는 내 할 일을 할 거니까.",
  ui_story_5028_50280901_134_dialog_content = "그냥 날 귀찮게 만들지나 마.",
  ui_story_5028_50280901_136_dialog_content = "크...크억... 젠장... 이 여자... 뭐가 이렇게 센 거냐?!",
  ui_story_5028_50280901_137_dialog_content = "다들 한 번에 덤벼! 저 여자를 때려눕혀!",
  ui_story_5028_50280901_138_dialog_content = "귀찮게 하지 말라고 했잖아.",
  ui_story_5028_50280901_139_dialog_content = "얌전히 비크의 행방이나 말해주면 안 될까?",
  ui_story_5028_50280901_140_dialog_content = "으윽──!",
  ui_story_5028_50280901_141_dialog_content = "말해, 비크 어딨어?",
  ui_story_5028_50280901_142_dialog_content = "얼른 말해. 이렇게 네 목을 조르는 것도 정말 힘드니까.",
  ui_story_5028_50280901_143_dialog_content = "으윽... 게, <color=#FFB400>게리</color>, 그리고 그 부하 사냥꾼들... 「강철채찍단」이 데려갔어!",
  ui_story_5028_50280901_144_dialog_content = "역시 그 녀석이었어.",
  ui_story_5028_50280901_145_dialog_content = "게리? 어디서 들어본 것 같데...",
  ui_story_5028_50280901_146_dialog_content = "저것들한테 낭비할 시간 없어.\n얼른 게리 두목님한테 「페코」를 잡아다 드려야 한다고.",
  ui_story_5028_50280901_147_dialog_content = "생각났어. 페코를 찾다가 마주친 강도들도 그 이름을 말했었어!",
  ui_story_5028_50280901_148_dialog_content = "아? 그랬어? 피아는 기억이 전혀 안 나는데?",
  ui_story_5028_50280901_149_dialog_content = "게리... 환상동물의 급격한 개체수 감소를 불러온 원흉이 바로 녀석이었다니.",
  ui_story_5028_50280901_150_dialog_content = "아는 사람이야?",
  ui_story_5028_50280901_151_dialog_content = "설명하기 귀찮아. 그리고 애초에 너랑은 상관없는 일이야.",
  ui_story_5028_50280901_152_dialog_content = "게리는 어디 숨었지?",
  ui_story_5028_50280901_153_dialog_content = "부, 북쪽으로 10km 떨어진 곳에 동굴이 있다... 거기가 놈의 아지트다...",
  ui_story_5028_50280901_154_dialog_content = "크억──!",
  ui_story_5028_50280901_155_dialog_content = "정말 귀찮네.",
  ui_story_5028_50280901_156_dialog_content = "야! 기다려!",
  ui_story_5028_50280901_157_dialog_content = "PlayerName, 우리도 가자!",
  ui_story_5028_50280901_158_dialog_content = "이번엔 놓치면 안 돼!",
  ui_story_5028_50280901_159_dialog_content = "아, 알았어!",
  ui_story_5028_50280901_160_dialog_content = "<color=#e8d9bb>몇 분 후</color>",
  ui_story_5028_50280901_161_dialog_content = "기절한 사람들이 잔뜩 있어.",
  ui_story_5028_50280901_162_dialog_content = "하? 이 녀석들이 왜 여기 쓰러져 있는 거야?",
  ui_story_5028_50280901_163_dialog_content = "스모키, 아는 사람들이야?",
  ui_story_5028_50280901_164_dialog_content = "이 녀석들, 전부 움브라톤 근처에서 어슬렁대는 강도들이야.\n하나같이 불태워 버려야 할 놈들이라고.",
  ui_story_5028_50280901_165_dialog_content = "음, 싸운 흔적들은 방금 전에 생긴 것 같아.",
  ui_story_5028_50280901_166_dialog_content = "서두르면 PlayerName 녀석을 따라잡을 수 있을 거야.",
  ui_story_5028_50280901_168_dialog_content = "그럼 얼른 가자.",
  ui_story_5028_50280901_169_dialog_content = "PlayerName, 대체 뭘 하는 거야?",
  ui_story_5028_50280901_170_dialog_content = "<color=#e8d9bb>강도의 아지트 밖</color>",
  ui_story_5028_50280901_171_dialog_content = "아마 여기겠네.",
  ui_story_5028_50280901_172_dialog_content = "휴... 빨리도 달리네!",
  ui_story_5028_50280901_173_dialog_content = "저기 보이는 동굴이 강도들의 아지트 입구겠지?",
  ui_story_5028_50280901_174_dialog_content = "기다려!",
  ui_story_5028_50280901_175_dialog_content = "루! 루루!",
  ui_story_5028_50280901_176_dialog_content = "시라, <color=#FFB400>그쪽</color>은 왜 가리키는데?",
  ui_story_5028_50280901_177_dialog_content = "앗! 저기 환상동물들이 잔뜩 있어!",
  ui_story_5028_50280901_178_dialog_content = "어디?",
  ui_story_5028_50280901_179_dialog_content = "뭐야... 환상동물만이 아닌데?! 암귀도 엄청 많잖아!",
  ui_story_5028_50280901_180_dialog_content = "크오오──!",
  ui_story_5028_50280901_181_dialog_content = "이런, 들켰어!",
  ui_story_5028_50280901_182_dialog_content = "가라, 키아로!",
  ui_story_5028_50280901_183_dialog_content = "휴... 또 싸우는 거야?",
  ui_story_5028_50280902_1_dialog_content = "키아로!",
  ui_story_5028_50280902_2_dialog_content = "루우우── 루!",
  ui_story_5028_50280902_3_dialog_content = "캬아악!",
  ui_story_5028_50280902_4_dialog_content = "조심해, 환상동물들은 공격하지 마.",
  ui_story_5028_50280902_5_dialog_content = "저 애들은 아무 잘못도 없으니까.",
  ui_story_5028_50280902_6_dialog_content = "페코──",
  ui_story_5028_50280902_7_dialog_content = "무서워하지 마. 해치지 않을 테니까 이리 오렴.",
  ui_story_5028_50280902_8_dialog_content = "페코페코!",
  ui_story_5028_50280902_9_dialog_content = "야, 도망갔잖아! 왜 겁을 주고 그래?",
  ui_story_5028_50280902_10_dialog_content = "그럴 생각은 없었어. 난 그저...",
  ui_story_5028_50280902_11_dialog_content = "크오오──!",
  ui_story_5028_50280902_12_dialog_content = "정말 귀찮네!",
  ui_story_5028_50280902_13_dialog_content = "(시라... 왠지 마음이 안 좋아 보이네.)",
  ui_story_5028_50280902_14_dialog_content = "(게다가 적의 환상동물만이 아니야. 피아의 곁에 있는 녀석들도\n전부 시라 곁에는 가려고 하질 않고 있어.)",
  ui_story_5028_50280902_15_dialog_content = "암귀는 전부 쓰러트렸어. 환상동물들은 전부 시라 때문에 놀라서 도망가 버렸어.",
  ui_story_5028_50280902_16_dialog_content = "후후후, 이런 녀석들은 환상동물 마스터의 상대가 못 된다구.",
  ui_story_5028_50280902_17_dialog_content = "근데 이상하잖아. 왜 환상동물들이 암귀랑 같이 있지?",
  ui_story_5028_50280902_18_dialog_content = "심지어 이 동굴을 지키고 있던 것 같던데?",
  ui_story_5028_50280902_X18_dialog_content = "아마 그렇게 훈련을 받은 거겠지.",
  ui_story_5028_50280902_19_dialog_content = "암귀도 훈련시킬 수 있단 말이야?!",
  ui_story_5028_50280902_20_dialog_content = "나도 몰라. 근데 게리는 <color=#FFB400>동물이 말을 듣게 만드는 채찍</color>을 가지고 있다고 들었어.",
  ui_story_5028_50280902_21_dialog_content = "그 채찍이라면 암귀를 길들일 수 있을지도 몰라.",
  ui_story_5028_50280902_22_dialog_content = "힘으로 남을 굴복시키는 건 강도들이 가장 잘하는 짓이니까.",
  ui_story_5028_50280902_23_dialog_content = "저 환상동물들도 설마 그런 거야?",
  ui_story_5028_50280902_24_dialog_content = "당연히 그 채찍으로 훈련시켰겠지.",
  ui_story_5028_50280902_25_dialog_content = "강도는 연구자와 달라. 놈들은 가장 쉽고 난폭한 방법으로 목적을 달성해.\n동물의 기분 따위는 생각하지 않는다고.",
  ui_story_5028_50280902_26_dialog_content = "어떻게 그럴 수가 있어!",
  ui_story_5028_50280902_27_dialog_content = "너도 마찬가지잖아.",
  ui_story_5028_50280902_28_dialog_content = "네가 환상동물에 대해 아는 게 뭔데?\n그저 책에 쓰인 대로, 비크한테 배운 대로 녀석들을 대할 뿐이잖아.",
  ui_story_5028_50280902_29_dialog_content = "자칭 「환상동물 마스터」라면서 그저 제멋대로 다루는 것밖에 모르지...",
  ui_story_5028_50280902_30_dialog_content = "그런 점에서 넌 저들과 다를 게 없어.",
  ui_story_5028_50280902_31_dialog_content = "난 달라!",
  ui_story_5028_50280902_32_dialog_content = "반박하고 싶으면 내 질문에 답해 봐.",
  ui_story_5028_50280902_33_dialog_content = "가골빼미 알을 2단계로 인공부화시키려면 온도는 몇 도로 유지해야 하지?",
  ui_story_5028_50280902_34_dialog_content = "그게, 그러니까... 30도였나... 아니, 40도?",
  ui_story_5028_50280902_35_dialog_content = "42.5도야. 게다가 6시간마다 알을 뒤집어 줘야 해.",
  ui_story_5028_50280902_36_dialog_content = "뒤집기까지 해야 돼?!",
  ui_story_5028_50280902_37_dialog_content = "당연하지. 안 그러면 부화는 실패할 거야.",
  ui_story_5028_50280902_38_dialog_content = "나, 나도 알고 있었어!",
  ui_story_5028_50280902_39_dialog_content = "노트를 보면 알 수 있다구!",
  ui_story_5028_50280902_40_dialog_content = "네가 중요하게 생각한다는 환상동물조차 커닝하지 않으면 안 되는구나.",
  ui_story_5028_50280902_41_dialog_content = "정말 되는대로 살아온 모양이네.",
  ui_story_5028_50280902_42_dialog_content = "나, 난...",
  ui_story_5028_50280902_43_dialog_content = "흐아아앙!",
  ui_story_5028_50280902_44_dialog_content = "피아?!",
  ui_story_5028_50280902_45_dialog_content = "이래서 어린애는 귀찮다니까.",
  ui_story_5028_50280902_46_dialog_content = "나, 난 어린애가 아니야! 흐아앙!",
  ui_story_5028_50280902_47_dialog_content = "어린애가 아니라고 부정하는 건 어린애뿐이야.",
  ui_story_5028_50280902_48_dialog_content = "충고하는데, 이 일에서 손을 떼는 게 좋을 거야.\n네 애완동물들을 데리고 네가 가야 할 곳으로 돌아가.",
  ui_story_5028_50280902_49_dialog_content = "그만해! 이러다간 피아가 계속 울겠어!",
  ui_story_5028_50280902_50_dialog_content = "흐아아앙!",
  ui_story_5028_50280902_51_dialog_content = "그 애가 그렇게 된 건 너한테도 책임이 있어.",
  ui_story_5028_50280902_52_dialog_content = "뭐?",
  ui_story_5028_50280902_53_dialog_content = "버릇없는 아이를 혼내지 않으면 영원히 성장하지 않아.",
  ui_story_5028_50280902_54_dialog_content = "지금처럼 계속 제멋대로 굴다가는 언젠가 너도 분명히 더 곤란해질 거야.",
  ui_story_5028_50280902_55_dialog_content = "옛날의 나처럼 말이야.",
  ui_story_5028_50280902_56_dialog_content = "으으! 거, 거기 서!",
  ui_story_5028_50280902_57_dialog_content = "저 녀석, 왜 계속 자기 할 말만 하고 가버리냐고!",
  ui_story_5028_50280902_58_dialog_content = "동굴 안으로 바로 들어갔어.",
  ui_story_5028_50280902_59_dialog_content = "자기도 제멋대로면서... 나한테...",
  ui_story_5028_50280902_60_dialog_content = "피아, 괜찮아?",
  ui_story_5028_50280902_61_dialog_content = "루루!",
  ui_story_5028_50280902_62_dialog_content = "난, 훌쩍... 그렇게 쉽게 포기 안 해!",
  ui_story_5028_50280902_63_dialog_content = "뭐?!",
  ui_story_5028_50280902_64_dialog_content = "내 목표는 환상동물 마스터가 되는 거야.\n누가 좀 비웃었다고 포기할 줄 알았어?",
  ui_story_5028_50280902_65_dialog_content = "우리도 쫓아가자!",
  ui_story_5028_50280902_66_dialog_content = "입구를 지키던 녀석들은 지금 전부 쓰러져 있으니까,\n몰래 잠입해서 사부를 구하자!",
  ui_story_5028_50280902_67_dialog_content = "녀석, 시라라고 했지?",
  ui_story_5028_50280902_68_dialog_content = "반드시 녀석한테 내 실력을 보여줄 거야!",
  ui_story_5028_50281001_1_dialog_content = "여기가 게리의 비밀 기지인가? 정말 취향도 저질이네.",
  ui_story_5028_50281001_2_dialog_content = "온통 지저분한 동물 우리밖에 없잖아. 비어 있지만 냄새도 심해.",
  ui_story_5028_50281001_3_dialog_content = "아마 얼마 전까지 환상동물들을 잔뜩 가둬 둔 거겠지.",
  ui_story_5028_50281001_4_dialog_content = "우리가 전부 열려 있어. 안에 동물은 없고.",
  ui_story_5028_50281001_5_dialog_content = "시라가 풀어준 건가?",
  ui_story_5028_50281001_6_dialog_content = "잠깐만...",
  ui_story_5028_50281001_7_dialog_content = "피아, 조심해. 환상동물들이 이쪽으로 달려오는 게 느껴져.",
  ui_story_5028_50281001_8_dialog_content = "얼른 피해! 부딪힐 거야!",
  ui_story_5028_50281001_9_dialog_content = "어?",
  ui_story_5028_50281001_10_dialog_content = "으엑──?!",
  ui_story_5028_50281001_11_dialog_content = "잠깐만, 이게 어떻게 된 거야?",
  ui_story_5028_50281001_12_dialog_content = "누가 좀 말해줘!",
  ui_story_5028_50281001_13_dialog_content = "야, 너! 지금 이게 도대체 무슨 일이야?",
  ui_story_5028_50281001_14_dialog_content = "꾸룩──!",
  ui_story_5028_50281001_15_dialog_content = "뭐, 뭐라고?",
  ui_story_5028_50281001_16_dialog_content = "이 앞에 살기가 가득한 무서운 녀석이 있다고?",
  ui_story_5028_50281001_17_dialog_content = "그 녀석이 너흴 풀어주고 혼자 안으로 들어갔다고?",
  ui_story_5028_50281001_18_dialog_content = "살기가 가득한...",
  ui_story_5028_50281001_19_option_content = "설마 강도 두목인가?",
  ui_story_5028_50281001_20_dialog_content = "너도 참 순진하네, PlayerName.",
  ui_story_5028_50281001_21_dialog_content = "강도 두목이 환상동물을 풀어줄 리가 없잖아.",
  ui_story_5028_50281001_22_dialog_content = "그, 그것도 그렇네.",
  ui_story_5028_50281001_23_dialog_content = "동물들이 말한 건 아마 시라일 거야.",
  ui_story_5028_50281001_24_dialog_content = "그럼 지금까지 동물들을 놀라게 만든 「무서운 녀석」은 설마...",
  ui_story_5028_50281001_25_option_content = "설마 시라는 아니겠지?",
  ui_story_5028_50281001_26_dialog_content = "환상동물들이 보는 시라는 「살기가 넘친다」는 건가?",
  ui_story_5028_50281001_27_dialog_content = "뭐, 저 기분 나쁜 모습엔 딱 맞는 묘사지만 말이야.",
  ui_story_5028_50281001_28_dialog_content = "어쩐지 동물들이 무서워한다 했어.",
  ui_story_5028_50281001_29_dialog_content = "동물들은 일단 놔두자. 다친 곳도 없어 보이고, 스스로 도망칠 수 있으니까.",
  ui_story_5028_50281001_30_dialog_content = "우린 비크 사부를 찾자.",
  ui_story_5028_50281001_31_dialog_content = "알았어.",
  ui_story_5028_50281001_32_dialog_content = "캄캄해서 아무것도 안 보여.",
  ui_story_5028_50281001_33_dialog_content = "저 동물들, 지금까지 계속 이런 곳에 갇혀 있었던 거야?",
  ui_story_5028_50281001_34_dialog_content = "정말 찝찝하네...",
  ui_story_5028_50281001_35_dialog_content = "흥, 겨우 이 정도로 겁먹었어? 정말 겁도 많네, 우리 꼬마 아이테르~",
  ui_story_5028_50281001_36_dialog_content = "저기, 피아... 너 뒤에...",
  ui_story_5028_50281001_37_dialog_content = "그런 수작으로 날 놀라게 하려고? 너무 진부하잖아.",
  ui_story_5028_50281001_38_dialog_content = "너희들... 역시 따라왔구나.",
  ui_story_5028_50281001_39_dialog_content = "으아악?!",
  ui_story_5028_50281001_40_dialog_content = "소, 소리도 없이 언제 나타난 거야?!",
  ui_story_5028_50281001_41_dialog_content = "먼저 말해두는데, 나, 난 놀란 게 아냐!",
  ui_story_5028_50281001_42_dialog_content = "......",
  ui_story_5028_50281001_43_dialog_content = "시라, 비크 씨는?",
  ui_story_5028_50281001_44_dialog_content = "그 사람? 아직 동굴 안쪽에 묶여 있어.",
  ui_story_5028_50281001_45_dialog_content = "뭐? 그럼 왜 안 풀어준 건데?",
  ui_story_5028_50281001_46_dialog_content = "밧줄 푸는 건 귀찮아. 같이 움직이는 건 더 귀찮고.",
  ui_story_5028_50281001_47_dialog_content = "야! 그런 변명도 한두 번이어야지!",
  ui_story_5028_50281001_48_dialog_content = "게다가 그 사람을 풀어주면 또 무슨 엉뚱한 짓을 저지를지 몰라.",
  ui_story_5028_50281001_49_dialog_content = "그런 산만한 성격으로는 환상동물을 제대로 지킬 수 없어.",
  ui_story_5028_50281001_50_dialog_content = "그런 일은 좀 더 전문적인 사람한테 맡겨야지.",
  ui_story_5028_50281001_51_dialog_content = "음, 그건 나도 같은 생각이야. 허접 사부는 정말 못 미덥다고.",
  ui_story_5028_50281001_52_dialog_content = "이 세상의 환상동물들은 이 환상동물 마스터 피아가 지킬 거야!",
  ui_story_5028_50281001_53_dialog_content = "좋을 대로 생각해.",
  ui_story_5028_50281001_54_dialog_content = "비크는 안쪽에 있으니까 돕고 싶으면 가 봐.",
  ui_story_5028_50281001_55_dialog_content = "대신 날 방해하진 마.",
  ui_story_5028_50281001_56_dialog_content = "저 녀석 날 바보 취급하는 게 분명해!",
  ui_story_5028_50281001_57_dialog_content = "쳇... 두고 봐. 제대로 깜짝 놀라게 만들어 줄 테니까!",
  ui_story_5028_50281001_58_dialog_content = "루──!",
  ui_story_5028_50281001_59_dialog_content = "키아로, 너도 그렇게 생각하지?",
  ui_story_5028_50281001_60_dialog_content = "가자, 일단 사부를 구해주자.",
  ui_story_5028_50281001_61_dialog_content = "<color=#e8d9bb>게리의 기지 내부</color>",
  ui_story_5028_50281001_62_dialog_content = "비크 사부!",
  ui_story_5028_50281001_63_dialog_content = "이런 꼴이라니, 정말 한심하네.",
  ui_story_5028_50281001_64_dialog_content = "내키진 않지만 내가 풀어줄게.",
  ui_story_5028_50281001_65_dialog_content = "휴, 역시 너희가 날 구하러 올 줄 알았다니까.",
  ui_story_5028_50281001_66_dialog_content = "마침 딱 맞게 잘 왔어. 벌써 손이 저려서 말이야.",
  ui_story_5028_50281001_67_dialog_content = "이쪽은?",
  ui_story_5028_50281001_68_dialog_content = "안녕, 비크 씨. 난 PlayerName...",
  ui_story_5028_50281001_69_option_content = "피아한테 붙잡힌 아이테르야.",
  ui_story_5028_50281001_70_dialog_content = "맞아 맞아~",
  ui_story_5028_50281001_71_dialog_content = "이 사람은 내가 붙잡은 환상동물 아이테르야!",
  ui_story_5028_50281001_72_dialog_content = "세상에 딱 한 마리밖에 없다구.",
  ui_story_5028_50281001_73_option_content = "피아의 동료야.",
  ui_story_5028_50281001_74_dialog_content = "맞아, 내 환상동물 파트너야.",
  ui_story_5028_50281001_75_dialog_content = "세상에서 하나뿐인 아이테르라구!",
  ui_story_5028_50281001_76_dialog_content = "오? 진짜로 잡았구나.",
  ui_story_5028_50281001_77_dialog_content = "그거야 당연하지!",
  ui_story_5028_50281001_78_dialog_content = "그뿐만이 아니야. 사부가 준 임무를 전부 달성했어!",
  ui_story_5028_50281001_79_dialog_content = "그거 대단하네.",
  ui_story_5028_50281001_80_dialog_content = "당연하지. 난 미래에 「환상동물 마스터」가 될 몸이니까.\n이까짓 것들도 못 하면 어떡해?",
  ui_story_5028_50281001_81_dialog_content = "그럼 아이테르를 찾았으니까, 앞으로의 일도 이젠 가망이 있겠어.",
  ui_story_5028_50281001_82_dialog_content = "「앞으로」라니?",
  ui_story_5028_50281001_83_dialog_content = "그래. 졸업을 위한 마지막 임무로 가서 게리의 음모를 막아!",
  ui_story_5028_50281001_84_dialog_content = "잠깐, 잠깐만!",
  ui_story_5028_50281001_85_dialog_content = "저번에 준 임무를 마치면 졸업을 시켜준다고 한 거 아니었어?",
  ui_story_5028_50281001_86_dialog_content = "모든 임무를 마치고 나면 비밀 임무를 받게 된다...\n이야기란 건 대체로 그런 식 아냐?",
  ui_story_5028_50281001_87_dialog_content = "그럴 줄 알았어! 역시 사부가 하는 말은 하나도 믿을 게 못 된다니까!",
  ui_story_5028_50281001_88_dialog_content = "둘 다 대체 무슨 얘기를 하는 거야...",
  ui_story_5028_50281001_89_dialog_content = "뭐가 어떻게 된 건지 누가 설명 좀 해 줄래?",
  ui_story_5028_50281001_90_dialog_content = "비크 씨, 당신이랑 그 게리라는 사람은 대체 무슨 사이야?\n그리고 그 사람은 왜 당신을 여기 묶어 둔 건데?",
  ui_story_5028_50281001_91_dialog_content = "그건 말하자면 길어.",
  ui_story_5028_50281001_92_dialog_content = "나랑 게리는 한때 친구였어.",
  ui_story_5028_50281001_93_dialog_content = "사람들은 환상동물을 좋아하는 날 이상하다고 생각했고,\n그래서 나와 이야기하고 싶어 하는 사람은 거의 없었어.",
  ui_story_5028_50281001_94_dialog_content = "하지만 그 녀석은 내가 환상동물을 좋아한다는 걸 알고는\n종종 환상동물에 대한 지식을 들으러 날 찾아왔어.",
  ui_story_5028_50281001_95_dialog_content = "난 소중한 친구를 얻었다고 생각했고, 내가 알고 있는 것을 아낌없이 가르쳐 줬어.",
  ui_story_5028_50281001_96_dialog_content = "그러던 어느 날, 술집에서 술을 마시다가, 내가 취했을 때 녀석이 나한테 물었어.",
  ui_story_5028_50281001_97_dialog_content = "비크, 넌 환상동물에 대해 그렇게 잘 알고 있잖아?",
  ui_story_5028_50281001_98_dialog_content = "그럼 세계 최강의 동물이 뭔지 아냐?",
  ui_story_5028_50281001_99_dialog_content = "최, 최강의... 동물?",
  ui_story_5028_50281001_100_dialog_content = "하하, 좋은 질문이야. 물론 내가 알지. 끅──",
  ui_story_5028_50281001_101_dialog_content = "세계 최강의 동물은... 바로 <color=#FFB400>키아로</color>야!",
  ui_story_5028_50281001_102_dialog_content = "하하, 키아로의 신뢰를 얻을 수 있다면, 천하무적이 될 수 있다고!",
  ui_story_5028_50281001_103_dialog_content = "그렇게 되면... 끅... 자난성을 짓밟는 것도, 백야성을 무너트리는 것도,\n어...얼마든지 할 수 있다니까!",
  ui_story_5028_50281001_104_dialog_content = "그 사람이 그런 질문을 한 건 단순한 호기심이 아니었겠지?",
  ui_story_5028_50281001_105_dialog_content = "하하, 그 질문의 답은 나도 이제야 알게 됐어.",
  ui_story_5028_50281001_106_dialog_content = "그 녀석이 나한테 접근했던 것도 자기 목적을 위해서였을 뿐이었어.",
  ui_story_5028_50281001_107_dialog_content = "그게 대체 뭔데?",
  ui_story_5028_50281001_108_dialog_content = "복수, 환상동물에게 복수하겠다는 생각이었던 거지.",
  ui_story_5028_50281001_109_dialog_content = "어째서?",
  ui_story_5028_50281001_110_dialog_content = "그건 나야 모르지~",
  ui_story_5028_50281001_111_dialog_content = "아무튼 그 질문을 하고 나서 게리는 사라졌거든.",
  ui_story_5028_50281001_112_dialog_content = "이번에 날 납치할 때 처음으로 다시 나타났던 거야.",
  ui_story_5028_50281001_113_dialog_content = "비크 사부 같은 빈털터리한테 무슨 가치가 있다고 납치한 건데?",
  ui_story_5028_50281001_114_dialog_content = "피아, 네가 그렇게 말하면 내가 마음이 아프잖아...",
  ui_story_5028_50281001_115_dialog_content = "빨리 제대로 대답해!",
  ui_story_5028_50281001_116_dialog_content = "으아아악!",
  ui_story_5028_50281001_117_dialog_content = "그 녀석은 키아로의 서식지를 찾으려고 해.",
  ui_story_5028_50281001_118_dialog_content = "뭐?!",
  ui_story_5028_50281001_119_dialog_content = "설마 키아로가 있으면 천하무적이란 말을 정말 믿은 거야?",
  ui_story_5028_50281001_120_dialog_content = "그건 허접 사부가 대충 지어낸 이야기 아니었어?",
  ui_story_5028_50281001_121_dialog_content = "......",
  ui_story_5028_50281001_122_dialog_content = "만약 그게 진짜라면, 그냥 내버려 뒀다간 이 세계가 위험해질 거야...",
  ui_story_5028_50281001_123_dialog_content = "뭐, 안심해. 괜찮아.",
  ui_story_5028_50281001_124_dialog_content = "설령 게리가 이 세상의 모든 키아로를 잡는다 해도,\n녀석들을 가지고 이 세계에 영향을 미칠 일을 할 순 없을 거야.",
  ui_story_5028_50281001_125_dialog_content = "내버려 둬도 문제없어.",
  ui_story_5028_50281001_126_dialog_content = "......",
  ui_story_5028_50281001_127_dialog_content = "<size=50>안 돼──!</size>",
  ui_story_5028_50281001_128_dialog_content = "미래의 환상동물 마스터로서, 그런 일은 절대 용납할 수 없어!",
  ui_story_5028_50281001_129_dialog_content = "루!",
  ui_story_5028_50281001_130_dialog_content = "이런 이런...",
  ui_story_5028_50281001_131_dialog_content = "저 강도들은 환상동물을 가지고 나쁜 짓을 할 생각밖에 없고,\n동물들의 마음은 전혀 생각하지 않아! 게다가 아껴주지도 않는다구!",
  ui_story_5028_50281001_132_dialog_content = "키아로들이 게리의 손에 들어가면 분명히 폭력적인 방식으로\n녀석들한테 강요할 게 분명해!",
  ui_story_5028_50281001_133_dialog_content = "동물들의 본성을 거스르고... 원하지도 않는 일을 강요하는 건...\n내가 절대 용서할 수 없어!",
  ui_story_5028_50281001_134_dialog_content = "그래... 그래야지! 바로 그런 기세야!",
  ui_story_5028_50281001_135_dialog_content = "그 기세를 몰아서 단숨에 게리를 찾고 녀석의 계획을 막는 거야!",
  ui_story_5028_50281001_136_dialog_content = "키아로들을 위해서라도 마지막으로 한 번만 더 사부를 믿겠어!",
  ui_story_5028_50281001_137_dialog_content = "내 환상동물 파트너들이랑 같이 이번 사건을 해결할 거야!",
  ui_story_5028_50281001_138_dialog_content = "환상동물 마스터의 이름을 걸고!",
  ui_story_5028_50281001_139_dialog_content = "키아로, 페코, 찐찐득이, 비카, 그리고 PlayerName, 다들 날 도와줄 거지?",
  ui_story_5028_50281001_140_dialog_content = "루──!",
  ui_story_5028_50281001_141_dialog_content = "페코페코!",
  ui_story_5028_50281001_142_dialog_content = "꾸룩...",
  ui_story_5028_50281001_143_dialog_content = "하이하이!",
  ui_story_5028_50281001_144_dialog_content = "으, 응? 그래.",
  ui_story_5028_50281001_145_dialog_content = "좋아, 그럼 지금 바로 출발!",
  ui_story_5028_50281001_146_dialog_content = "아, 너희들의 기운 넘치는 걸 보니 아무래도 사부의 도움은 필요 없을 것 같네.",
  ui_story_5028_50281001_147_dialog_content = "그럼 난 먼저 돌아가서 좋은 소식을 기다리고... 으아아아파!",
  ui_story_5028_50281001_148_dialog_content = "살살, 살살 좀 해... 난 늙어서 그렇게 잡아당기면 안 돼!",
  ui_story_5028_50281001_149_dialog_content = "전에 자기는 「영원한 18세」라고 말했던 건 누구야?",
  ui_story_5028_50281001_150_dialog_content = "아하, 하하하하...",
  ui_story_5028_50281001_151_dialog_content = "결국 이번 일도 사부가 자초한 일이잖아?",
  ui_story_5028_50281001_152_dialog_content = "자기가 자초한 일이니까, 직접 뒷정리를 해야 되지 않겠어?",
  ui_story_5028_50281001_153_dialog_content = "뭐, 대신...",
  ui_story_5028_50281001_154_dialog_content = "「위대한 환상동물 마스터 피아 님, 암귀에 맞서는 걸 도와주세요!」라고 하면...",
  ui_story_5028_50281001_155_dialog_content = "내키진 않지만 내가 도와줄게.",
  ui_story_5028_50281001_156_dialog_content = "아하하, 다른 건 몰라도 그건 좀 무리네.\n그건 게리의 음모를 막은 뒤가 아니면 안 돼.",
  ui_story_5028_50281001_157_dialog_content = "그럼 순찰 중인 암귀가 돌아와도 처리는 사부가 직접 해!",
  ui_story_5028_50281001_158_dialog_content = "아하하... 아아?!",
  ui_story_5028_50281001_159_dialog_content = "크오오!",
  ui_story_5028_50281001_160_dialog_content = "으악! 살려줘!",
  ui_story_5028_50281001_161_dialog_content = "나 혼자선 안 된다고!",
  ui_story_5028_50281002_1_dialog_content = "아이고, 허리야...",
  ui_story_5028_50281002_2_dialog_content = "역시 격렬한 운동은 나한테 안 맞는다니까.",
  ui_story_5028_50281002_3_dialog_content = "너무 오버 아니야? 비크 씨는 아무리 봐도 나랑 비슷한 나이 같은데.",
  ui_story_5028_50281002_4_dialog_content = "PlayerName, 겉모습으로 사람을 판단하면 안 돼.",
  ui_story_5028_50281002_5_dialog_content = "확실히 난 영원한 18살이지만, 인생 경험은 너보다 훨씬 풍부하거든.",
  ui_story_5028_50281002_6_dialog_content = "또 시작이네. 허접 사부는 누가 의심하면 항상 저랬어.",
  ui_story_5028_50281002_7_dialog_content = "근데 다 거짓말이었잖아!",
  ui_story_5028_50281002_8_dialog_content = "으흑, 피아가 그렇게 말하면 사부는 마음이 아프단다...",
  ui_story_5028_50281002_9_dialog_content = "(금방이라도 울 것 같은데?!)",
  ui_story_5028_50281002_10_dialog_content = "큰 제자한테는 버림받고, 작은 제자한테는 미움받고...\n정말 아무도 날 좋아해 주지 않는 걸까?",
  ui_story_5028_50281002_11_dialog_content = "시라 선배가 사부를 안 구하려던 이유가 있었어. 진짜 귀찮네.",
  ui_story_5028_50281002_12_dialog_content = "아, 시라는 날 구하기 싫었던 게 아냐. 삐져서 그런 거지.",
  ui_story_5028_50281002_13_dialog_content = "삐, 삐져?",
  ui_story_5028_50281002_14_dialog_content = "어떻게 삐지면 자기 사부가 강도한테 잡혀가는 것도 모른 척하는 건데...",
  ui_story_5028_50281002_15_dialog_content = "시라 저 아이는 환상동물에 대한 애정만큼은 절대 너희보다 작지 않아.",
  ui_story_5028_50281002_16_dialog_content = "하지만 운이 좋지 않았어. 너희도 시라의 이상한 점을 눈치챘지?",
  ui_story_5028_50281002_17_dialog_content = "혹시...",
  ui_story_5028_50281002_18_dialog_content = "발 얘기야?",
  ui_story_5028_50281002_19_dialog_content = "응, 그렇게 말할 수도 있겠지.",
  ui_story_5028_50281002_20_dialog_content = "동물들이 안 좋아하는 거?",
  ui_story_5028_50281002_21_dialog_content = "그래, 관찰력이 꽤 좋잖아.",
  ui_story_5028_50281002_22_dialog_content = "시라는 사고를 겪었어. 그래서 두 다리가 함께 다니던 문어의 다리와 융합되고 말았어.",
  ui_story_5028_50281002_23_dialog_content = "원래는 동물들이 시라를 무척 좋아했어.\n그런데 문어와 융합하고 나서는 동물들이 무서워하기 시작했어.",
  ui_story_5028_50281002_24_dialog_content = "어쩌면 동물들에게 문어는 낯설고 무서운 생물이라서 그런 거겠지.",
  ui_story_5028_50281002_25_dialog_content = "그래서 시라는 큰 충격을 받았던 거야.\n하지만 그렇다고 환상동물에 대한 애정이 줄어들진 않았어.",
  ui_story_5028_50281002_26_dialog_content = "대신 그 무렵부터 시라가 환상동물을 대하는 태도가 달라졌어.",
  ui_story_5028_50281002_27_dialog_content = "어떻게 변했는데?",
  ui_story_5028_50281002_28_dialog_content = "너흰 눈치 못 챘어?",
  ui_story_5028_50281002_29_dialog_content = "시라는 지금도 항상 환상동물을 생각하고 있어. 하지만...",
  ui_story_5028_50281002_30_dialog_content = "난 시라한테 「아마추어 환상동물 애호가」라는 낙인이 찍혀버렸다고!",
  ui_story_5028_50281002_31_dialog_content = "시라는 내가 전문성이 떨어지고, 내 방식이 환상동물들한테 해가 된다고 생각하고 있어!",
  ui_story_5028_50281002_32_dialog_content = "그게 말이나 된다고 생각해?",
  ui_story_5028_50281002_33_dialog_content = "......",
  ui_story_5028_50281002_34_dialog_content = "시라 선배, 정말 고생이 많았겠네...",
  ui_story_5028_50281002_35_dialog_content = "피아 너까지 그런...",
  ui_story_5028_50281002_36_dialog_content = "뭐, 됐어. 난 오해받는 일엔 익숙하니까.",
  ui_story_5028_50281002_37_dialog_content = "아무튼 시라는 내 기분대로 하는 방식을 인정할 수 없었고,\n자신은 「진짜 환상동물 마스터」가 되겠다고 결심했어.",
  ui_story_5028_50281002_38_dialog_content = "「진짜」? 어떻게 되면 「진짜」가 되는데?",
  ui_story_5028_50281002_39_dialog_content = "시라는 많은 고대 자료를 꼼꼼히 검토하고,\n환상동물의 생태를 관측하는 여러 방법을 고안해 냈어.",
  ui_story_5028_50281002_40_dialog_content = "예를 들면 잡은 환상동물의 발에 고리를 달아준 다음에 풀어주는 거지.",
  ui_story_5028_50281002_41_dialog_content = "그러면 다음에 그 종을 포획했을 때 다리에 고리가 달린\n동물의 수를 토대로 총개체수를 계산할 수 있어.",
  ui_story_5028_50281002_42_dialog_content = "그럼 드라코리온의 다리에 붙어 있던 고리도 시라 선배가 단 거였어?",
  ui_story_5028_50281002_43_dialog_content = "음, 아마 그렇겠지. 시라 말고는 그런 걸 할 사람은 없을 테니까.",
  ui_story_5028_50281002_44_dialog_content = "그 외에도 많은 방법을 고안했어.\n그리고 그중에는 정말 유용한 것들도 많았고 말이야!",
  ui_story_5028_50281002_45_dialog_content = "하지만 나에 대한 시라의 잘못된 인식은 사라지지 않았고,\n오히려 갈수록 더 심해졌어!",
  ui_story_5028_50281002_46_dialog_content = "시라는 사고의 원인이 환상동물에 대한 이해 부족...\n그리고 나 때문이라고 생각하고 있어.",
  ui_story_5028_50281002_47_dialog_content = "그래서 시라는 내가 불성실한 녀석이라고 생각하면서, 날 엄청 싫어하게 된 거야!",
  ui_story_5028_50281002_48_dialog_content = "뭐? 시라 선배가 저렇게 된 게 사부 때문이었어?",
  ui_story_5028_50281002_49_dialog_content = "아니거든! 그건 그냥 우연한 사고였다고!",
  ui_story_5028_50281002_50_dialog_content = "시라는 자신이 어디서 왔는지 몰랐어. 그래서 그걸 조사하고 싶어 했어.",
  ui_story_5028_50281002_51_dialog_content = "난 그때 시라 곁에 항상 작은 문어가 따라다니길래,\n그 문어의 서식지부터 조사해 보라고 조언했어.",
  ui_story_5028_50281002_52_dialog_content = "근데 저 아이가 혼자서 그 문어가 서식하는 심해로 갈 줄은 몰랐어...\n그러다 거기서 폭풍을 만났던 거야...",
  ui_story_5028_50281002_53_dialog_content = "마지막엔 저 문어가 스스로 시라와 융합했고,\n그 신기한 재생 능력으로 시라의 생명을 구했어.",
  ui_story_5028_50281002_54_dialog_content = "난 사부로서 문어 무리를 찾는 방법을 가르쳐 줬을 뿐이야.\n그 외에 내가 잘못된 걸 가르친 적은 없었어.",
  ui_story_5028_50281002_55_dialog_content = "흥, 아무리 울 것 같은 얼굴을 해 봤자 난 동정 안 해.",
  ui_story_5028_50281002_56_dialog_content = "사부의 부주의 때문에 이렇게 많은 문제가 생겼던 거니까.",
  ui_story_5028_50281002_57_dialog_content = "잘못을 만회하고 싶다면 당장 우릴 키아로의 서식지로 데려가서\n게리의 사악한 계획을 막아!",
  ui_story_5028_50281002_58_dialog_content = "휴, 넌 내 제자면서 사부를 조금도 공경하질 않는구나.",
  ui_story_5028_50281002_59_dialog_content = "난 이미 한참 묶여 있었다고. 게다가 배도 고픈데 길 안내를 시키다니...",
  ui_story_5028_50281002_60_dialog_content = "사부, 배고파?",
  ui_story_5028_50281002_61_dialog_content = "그럼 이 파이 줄게!",
  ui_story_5028_50281002_62_dialog_content = "응? 이 밀가루 향기... 황금빛 윤기... 그럼 사양 안 할게!",
  ui_story_5028_50281002_63_dialog_content = "냠냠, 특별한 맛은 없는 파이라도 역시 배가 고플 땐 엄청 맛있어진다니까!",
  ui_story_5028_50281002_64_dialog_content = "그 파이... 어디서 본 것 같은데... 아니지, 너 왜 파이를 들고 다녀?!",
  ui_story_5028_50281002_65_dialog_content = "사부를 잡은 악당들은 분명히 사부한테 밥을 안 줄 거라 생각했거든.",
  ui_story_5028_50281002_66_dialog_content = "그래서 특별히 예비 물자를 준비해 온 거야!",
  ui_story_5028_50281002_67_dialog_content = "냠냠, 역시 내 제자답구나. 정말 세심하네!",
  ui_story_5028_50281002_68_dialog_content = "근데 그 파이 산 지 벌써 며칠 됐거든. 안 상했어야 할 텐데...",
  ui_story_5028_50281002_69_dialog_content = "우웁... 콜록콜록!",
  ui_story_5028_50281002_70_dialog_content = "비크 씨?!",
  ui_story_5028_50281002_71_dialog_content = "콜록콜록... 아, 괜찮아. 아무튼 이젠 괜찮아...",
  ui_story_5028_50281002_72_dialog_content = "사부, 더 먹을래? 피아, 다른 맛의 파이도 있어!",
  ui_story_5028_50281002_73_dialog_content = "괘, 괜찮아... 사부는 배가 부르단다.",
  ui_story_5028_50281002_74_dialog_content = "자, 그럼 출발하자!",
  ui_story_5028_50281002_75_dialog_content = "악당의 음모를 막으러!",
  ui_story_5028_50281002_76_dialog_content = "저게 PlayerName 녀석을 납치한 강도야?",
  ui_story_5028_50281002_77_dialog_content = "뭔가 이상한데...",
  ui_story_5028_50281002_78_dialog_content = "이상하든 말든 상관없잖아? 냅다 가서 단숨에 때려눕히면 되지.",
  ui_story_5028_50281002_79_dialog_content = "정말 무모하구나, 스모키.",
  ui_story_5028_50281002_80_dialog_content = "귀족의 우아함이라고는 조금도 없잖아.",
  ui_story_5028_50281002_81_dialog_content = "너네 싸우지 마.",
  ui_story_5028_50281002_82_dialog_content = "쳇...",
  ui_story_5028_50281002_83_dialog_content = "몰래 따라가자. 타이밍을 봐서 구해내는 거야!",
  ui_story_5028_50281101_1_dialog_content = "<color=#e8d9bb>키아로의 서식지</color>",
  ui_story_5028_50281101_2_dialog_content = "꽤 하는군. 건방진 계집이.",
  ui_story_5028_50281101_3_dialog_content = "과연 얼마나 더 버틸 수 있을까?",
  ui_story_5028_50281101_4_dialog_content = "게리",
  ui_story_5028_50281101_X4_dialog_content = "38세",
  ui_story_5028_50281101_X5_dialog_content = "이곳저곳에서 환상동물을 포획하고 있는 악당",
  ui_story_5028_50281101_5_dialog_content = "동물들을 이용해서 공격하다니, 정말 귀찮은 녀석이네.",
  ui_story_5028_50281101_6_dialog_content = "암귀를 손쉽게 소멸시킬 만큼 무서운 힘을 가지고 있으면서...",
  ui_story_5028_50281101_7_dialog_content = "동물들에 대한 가식적인 마음이 저들을 공격할 수 없게 만드는 거냐.",
  ui_story_5028_50281101_8_dialog_content = "고통을 받으면서도 차마 반격도 못 하는 꼴이라니, 정말 우습군.",
  ui_story_5028_50281101_9_dialog_content = "입 닥쳐.",
  ui_story_5028_50281101_10_dialog_content = "너만 아니었으면 이런 귀찮은 일도 없었어.",
  ui_story_5028_50281101_11_dialog_content = "환상동물이 네 노예가 돼서 억지로 다른 동물들과 서로 죽고 죽이는 일도 없었다고!",
  ui_story_5028_50281101_12_dialog_content = "노예라고? 하하, 웃기는 소리.",
  ui_story_5028_50281101_13_dialog_content = "이놈들이 노예라고 불릴 자격이나 있나?\n그저 가장 하천하고 어리석은 짐승일 뿐인데 말이야.",
  ui_story_5028_50281101_14_dialog_content = "이런 생물은 이 세상에 존재하는 것 자체가 허용되지 않는다고!",
  ui_story_5028_50281101_15_dialog_content = "당장... 그 입 다물어!",
  ui_story_5028_50281101_16_dialog_content = "후우... 후우...",
  ui_story_5028_50281101_17_dialog_content = "으윽!",
  ui_story_5028_50281101_18_dialog_content = "가서 죽여라.",
  ui_story_5028_50281101_19_dialog_content = "저 계집애를 그 바보 같은 순수한 망상에서 해방시켜 줘라.",
  ui_story_5028_50281101_20_dialog_content = "캬아악──!",
  ui_story_5028_50281101_21_dialog_content = "안 돼...",
  ui_story_5028_50281101_22_dialog_content = "놈들을 멈춰!",
  ui_story_5028_50281101_23_dialog_content = "루!",
  ui_story_5028_50281101_24_dialog_content = "잘했어! 피아!",
  ui_story_5028_50281101_25_dialog_content = "흥, 내 멋진 모습을 마음껏 놀라면서 감상하라구.",
  ui_story_5028_50281101_26_dialog_content = "시라, 괜찮아?",
  ui_story_5028_50281101_27_dialog_content = "너희들, 왜...",
  ui_story_5028_50281101_28_dialog_content = "걱정 마. 우리도 게리를 막기 위해서 온 거니까!",
  ui_story_5028_50281101_29_dialog_content = "네 이야기는 비크 씨한테 들었어.",
  ui_story_5028_50281101_30_dialog_content = "우리도 게리를 막는 걸 도와줄게!",
  ui_story_5028_50281101_31_dialog_content = "안 돼, 빨리 도망쳐... 녀석과 싸워선 안 돼.",
  ui_story_5028_50281101_32_dialog_content = "저 녀석, 엄청 성가시다고!",
  ui_story_5028_50281101_33_dialog_content = "설마 한패를 부를 줄이야.",
  ui_story_5028_50281101_34_dialog_content = "바로 도망가 버릴 줄 알았는데, 비크.",
  ui_story_5028_50281101_35_dialog_content = "난 그런 겁쟁이가 아냐.",
  ui_story_5028_50281101_36_dialog_content = "너희가 떼로 몰려온 이상, 이쪽도 조력자를 부를 수밖에.",
  ui_story_5028_50281101_37_dialog_content = "너희한테 이 짐승들의 무서움을 보여주는 것도 나쁘지 않겠지.",
  ui_story_5028_50281101_X37_dialog_content = "암귀들도 전부 불러와서 한 번에 덤벼!",
  ui_story_5028_50281101_38_dialog_content = "크오오...",
  ui_story_5028_50281101_39_dialog_content = "놈들을 찢어버려라.",
  ui_story_5028_50281101_40_dialog_content = "예, 두목님!",
  ui_story_5028_50281101_41_dialog_content = "크오오!",
  ui_story_5028_50281101_42_dialog_content = "가라! 키아로, PlayerName!",
  ui_story_5028_50281101_43_dialog_content = "루!",
  ui_story_5028_50281101_44_dialog_content = "뭐, 뭐야? 나도?!",
  ui_story_5028_50281101_45_dialog_content = "멍하니 있지 말고 얼른 지휘해!",
  ui_story_5028_50281102_1_dialog_content = "약해. 너무 약하다고.",
  ui_story_5028_50281102_2_dialog_content = "그렇게 많은 환상동물을 데리고 있으면서, 놈들의 힘을 어떻게 끌어내는지도 모르다니.",
  ui_story_5028_50281102_3_dialog_content = "이 자식!",
  ui_story_5028_50281102_4_dialog_content = "내가 가르쳐 주지. 이 짐승들이 가장 강한 힘을 내게 만들고 싶다면,\n이렇게 하면 되는 거다.",
  ui_story_5028_50281102_5_dialog_content = "어서 일어나! 게으른 자식, 가서 놈들을 때려눕히라고!",
  ui_story_5028_50281102_6_dialog_content = "캬오오오──",
  ui_story_5028_50281102_7_dialog_content = "그건... 네가 훈련시킨 드라코리온?",
  ui_story_5028_50281102_8_dialog_content = "캬오오오──!",
  ui_story_5028_50281102_9_dialog_content = "루!",
  ui_story_5028_50281102_10_dialog_content = "당장 멈춰! 환상동물들은 그런 걸 원하지 않는단 말이야!",
  ui_story_5028_50281102_11_dialog_content = "원하지 않는다고?",
  ui_story_5028_50281102_12_dialog_content = "하하하하! 이 짐승들 따위가 뭘 원하는지 내가 알 게 뭐냐!",
  ui_story_5028_50281102_13_dialog_content = "이놈들은 그저 날 두려워하고, 경외하고, 날 위해 목숨을 바치면 그만이다!",
  ui_story_5028_50281102_14_dialog_content = "너무하잖아! 환상동물 마스터인 내가 절대 용서하지 않겠어!",
  ui_story_5028_50281102_15_dialog_content = "우리 제자 멋있다! 우리 제자 파이팅──",
  ui_story_5028_50281102_16_dialog_content = "당신 격려 따윈 아무 의미도 없어. 조금의 가치도 없다고.",
  ui_story_5028_50281102_17_dialog_content = "으아아... 또 제자의 미움을 샀어...",
  ui_story_5028_50281102_18_dialog_content = "애송이 주제에 입은 잘도 놀리는군.",
  ui_story_5028_50281102_19_dialog_content = "정작 실력은 그 기세를 못 따라가는 게 문제지만 말이야.",
  ui_story_5028_50281102_20_dialog_content = "캬오오오──",
  ui_story_5028_50281102_21_dialog_content = "꺄앗!",
  ui_story_5028_50281102_22_dialog_content = "피아!",
  ui_story_5028_50281102_23_dialog_content = "으윽!",
  ui_story_5028_50281102_24_dialog_content = "이런, 완전히 열세에 몰렸잖아...",
  ui_story_5028_50281102_25_dialog_content = "우리 그냥 항복할게, 항복. 그러니까 좀 봐줘.",
  ui_story_5028_50281102_26_dialog_content = "당신이란 사람은 이제 맞서 싸우는 것조차 귀찮은 거야?",
  ui_story_5028_50281102_27_dialog_content = "진짜로 맞설 수가 없으니까 그러지.",
  ui_story_5028_50281102_28_dialog_content = "피아랑 너도 이제 한계잖아?",
  ui_story_5028_50281102_29_dialog_content = "PlayerName 저 친구는 아이테르지 오로리안이 아냐. 전투 능력이 없어.",
  ui_story_5028_50281102_30_dialog_content = "내 늙은 몸뚱이도 도움이 안 되고 말이야.",
  ui_story_5028_50281102_31_dialog_content = "그러니까 답은 항복뿐이야.",
  ui_story_5028_50281102_32_dialog_content = "최소한 발버둥이라도 쳐야 하는 거 아니냐고...",
  ui_story_5028_50281102_33_dialog_content = "어쩔 수 없어. 현실을 직시하는 게 생존의 길이니까.",
  ui_story_5028_50281102_34_dialog_content = "설마 너희가 항복만 하면 내가 여기서 순순히 보내줄 거라 생각한 거냐?",
  ui_story_5028_50281102_35_dialog_content = "아니, 너흰 여기 남아야지. 남아서 가장 중대한 순간의 증인이 되어 줘야겠어.",
  ui_story_5028_50281102_36_dialog_content = "놈들을 묶어서 도로 가둬 놔라.",
  ui_story_5028_50281102_37_dialog_content = "예, 두목님!",
  ui_story_5028_50281102_38_dialog_content = "흐흐, 지난번엔 네놈들 때문에 고생 좀 했었지.\n오늘은 그 「답례」를 충분히 해 주마.",
  ui_story_5028_50281102_39_dialog_content = "루우우──!",
  ui_story_5028_50281102_40_dialog_content = "키아로!",
  ui_story_5028_50281102_41_dialog_content = "윽!",
  ui_story_5028_50281102_42_dialog_content = "움직이지 마!",
  ui_story_5028_50281102_43_dialog_content = "좀 살살 묶어줘. 난 팔에 쥐가 잘 나거든... 아이고!",
  ui_story_5028_50281102_44_dialog_content = "쳇.",
  ui_story_5028_50281102_45_dialog_content = "끝장이야... 완전히 궁지에 몰렸어...",
  ui_story_5028_50281102_46_dialog_content = "눈을 크게 뜨고 잘 봐 둬라.",
  ui_story_5028_50281102_47_dialog_content = "난 이제 모든 사람들에게 이 짐승들의 무서움을 가르쳐 줄 거다.\n그리고 이 공포와 증오를 모든 이의 마음에 심어주겠다.",
  ui_story_5028_50281102_48_dialog_content = "아, 그게 네 목적이었어?",
  ui_story_5028_50281102_49_dialog_content = "대체 왜 환상동물한테 그런 원한을 품게 된 거야?",
  ui_story_5028_50281102_50_dialog_content = "너처럼 머릿속에 든 게 동물뿐인 놈은 이해할 수 없을 거다.",
  ui_story_5028_50281102_51_dialog_content = "이 짐승들은 내 가장 소중한 것을 빼앗아 갔다. 넌 그것만 알면 된다.",
  ui_story_5028_50281102_52_dialog_content = "가장 소중한 것...?",
  ui_story_5028_50281102_53_dialog_content = "정말 귀찮게 됐군.",
  ui_story_5028_50281102_54_dialog_content = "저 짐승들을 유인할 함정을 반 정도는 완성했었는데,\n네놈들이 전부 망가트려 버렸잖아.",
  ui_story_5028_50281102_55_dialog_content = "뭐, 상관없다. 난 인내심이 많거든.",
  ui_story_5028_50281102_56_dialog_content = "이 짐승만 도망치지 않는다면...",
  ui_story_5028_50281102_57_dialog_content = "루우우!",
  ui_story_5028_50281102_58_dialog_content = "저게 뭐지?",
  ui_story_5028_50281102_59_dialog_content = "모습은 변했지만 키아로와 울음소리가 똑같아...",
  ui_story_5028_50281102_60_dialog_content = "설마 그것도 키아로야?",
  ui_story_5028_50281102_61_dialog_content = "내 경험으로 봐도 저건 확실히 키아로와 같은 종류의 생물이야.",
  ui_story_5028_50281102_62_dialog_content = "키아로랑 같은 종류라고? 근데 왜 저런 모습인 건데?",
  ui_story_5028_50281102_63_dialog_content = "가능성은 여러 가지가 있어.",
  ui_story_5028_50281102_64_dialog_content = "돌연변이, 환경의 차이, 무리의 차이... 모두 개체 간 형태의 차이를 유발할 수 있어.",
  ui_story_5028_50281102_65_dialog_content = "하지만 키아로랑 전혀 다르게 생겼잖아. 정말 같은 종이 맞아?",
  ui_story_5028_50281102_66_dialog_content = "이런 가능성을 일으키는 원인이라면... 아, 갑자기 생각이 안 나네.",
  ui_story_5028_50281102_67_dialog_content = "이럴 때 갑자기 못 미덥게 변하지 말라고!",
  ui_story_5028_50281102_68_dialog_content = "하, 그럼 마지막 즐거움을 소중히 여겨라.",
  ui_story_5028_50281102_69_dialog_content = "대체 뭘 어쩌려는 거야?",
  ui_story_5028_50281102_70_dialog_content = "이 짐승들은 남의 말을 알아듣진 못하지만, 같은 종류의 울음소리엔 반응하지.",
  ui_story_5028_50281102_71_dialog_content = "루우우──!",
  ui_story_5028_50281102_72_dialog_content = "이 습성을 이용하면 여기 있는 키아로를 전부 유인할 수 있다.\n그리고 훈련을 시킨다면...",
  ui_story_5028_50281102_73_dialog_content = "하하, 하하하하하!",
  ui_story_5028_50281102_74_dialog_content = "온 아스트라의 오로리안들이 놈들의 무서움을 알게 될 거다!",
  ui_story_5028_50281102_75_dialog_content = "그리고 나와 같은 아픔을 맛보는 거다!",
  ui_story_5028_50281102_76_dialog_content = "놈들을 똑바로 지켜라. 절대 도망치게 두지 마라.",
  ui_story_5028_50281102_77_dialog_content = "예, 두목님!",
  ui_story_5028_50281102_78_dialog_content = "<color=#e8d9bb>게리의 기지</color>",
  ui_story_5028_50281102_79_dialog_content = "들어가!",
  ui_story_5028_50281102_80_dialog_content = "이거 너무하잖아!",
  ui_story_5028_50281102_81_dialog_content = "여길 나가기만 해 봐. 아주 제대로 밟아줄 테니까!",
  ui_story_5028_50281102_82_dialog_content = "음, 기세가 좋구나, 피아.",
  ui_story_5028_50281102_83_dialog_content = "이런 상황에서까지 잘도 태연하네.",
  ui_story_5028_50281102_84_dialog_content = "위기감 없는 인간이 제일 곤란하다니까.",
  ui_story_5028_50281102_85_dialog_content = "닥쳐! 계속 시끄럽게 하면 매달아 버린다!",
  ui_story_5028_50281102_86_dialog_content = "......",
  ui_story_5028_50281102_87_dialog_content = "......",
  ui_story_5028_50281102_88_dialog_content = "내가 들을 줄 알고? 시끄럽다 하면 더 시끄럽게 할── 우우웁!",
  ui_story_5028_50281102_89_dialog_content = "힘을 아껴 둬. 우선 방법을 생각해 보자.",
  ui_story_5028_50281102_90_dialog_content = "(어쩌지... 나 혼자서는 아무런 대책도 떠오르질 않아...)",
  ui_story_5028_50281102_91_dialog_content = "(그래! 말로 할 수 없으면 감응 능력으로 얘기하면 되잖아!)",
  ui_story_5028_50281102_92_dialog_content = "(그럼 강도들도 우리가 대책을 세우는 걸 모르겠지.)",
  ui_story_5028_50281102_93_option_content = "(강제 감응!)",
  ui_story_5028_50281102_94_dialog_content = "피아! 들려?",
  ui_story_5028_50281102_95_dialog_content = "으앗?! PlayerName... 너 이 능력, 쓰기 전에 말 좀 하면 안 돼?",
  ui_story_5028_50281102_96_dialog_content = "미안, 근데 지금은 비상 상황이잖아!",
  ui_story_5028_50281102_97_dialog_content = "비크 씨?",
  ui_story_5028_50281102_98_dialog_content = "이런, 아이테르의 감응 능력... 옛날 생각이 나는걸.",
  ui_story_5028_50281102_99_dialog_content = "그리고 시라!",
  ui_story_5028_50281102_100_dialog_content = "들려.",
  ui_story_5028_50281102_101_dialog_content = "피아, 도망칠 방법을 같이 생각해 보자!",
  ui_story_5028_50281102_102_dialog_content = "도망? 어떻게?",
  ui_story_5028_50281102_103_dialog_content = "키아로는 벌써 잡혀갔고, 남은 환상동물들은 강도들과 싸울 수 없어.",
  ui_story_5028_50281102_104_dialog_content = "시라 선배한테 물어보는 건 어때?\n선배는 괴상하지만 힘은 세. 뭔가 방법이 있을지도 몰라.",
  ui_story_5028_50281102_105_dialog_content = "시라, 뭐 좋은 생각 없어? 이 환상동물들의 힘을 빌려서 도망칠 순 없을까?",
  ui_story_5028_50281102_106_dialog_content = "이런 작고 연약한 동물한테 목숨을 걸고 강도에 맞서라고 하느니...",
  ui_story_5028_50281102_107_dialog_content = "어떻게든 알아서 이 귀찮은 밧줄을 풀 방법을 생각하는 게 좋지 않겠어?",
  ui_story_5028_50281102_108_dialog_content = "힘만 회복되면 밧줄을 벗는 건 쉬우니까.",
  ui_story_5028_50281102_109_dialog_content = "하지만 동물들이 도와줄 수 없다면... 비크 씨, 무슨 방법 없어?",
  ui_story_5028_50281102_110_dialog_content = "당황하지 마, PlayerName.",
  ui_story_5028_50281102_111_dialog_content = "지금 우린 모두 행동이 제한되어 있지만,\n넌 아이테르의 특수한 능력으로 주변을 살필 수 있잖아.",
  ui_story_5028_50281102_112_dialog_content = "우리의 운명은 너한테 맡길게, PlayerName.",
  ui_story_5028_50281102_113_dialog_content = "갑자기 운명 같은 거 맡기지 마!",
  ui_story_5028_50281102_114_dialog_content = "뭐... 그래도 노력해 볼게.",
  ui_story_5028_50281102_115_option_content = "(강제 감응!)",
  ui_story_5028_50281102_116_dialog_content = "......",
  ui_story_5028_50281102_117_dialog_content = "(이 부근엔 순찰하는 강도가 있어...)",
  ui_story_5028_50281102_118_dialog_content = "(갇혀 있는 환상동물들...)",
  ui_story_5028_50281102_119_dialog_content = "(뭐야... 키아로랑 똑같이 생긴 환상동물들이 잔뜩 있잖아?!)",
  ui_story_5028_50281102_120_dialog_content = "비크 씨, 큰일이야. 강도들이 벌써 키아로의 동족들을 많이 잡았어!",
  ui_story_5028_50281102_121_dialog_content = "이런, 정말 잡았단 말이야?",
  ui_story_5028_50281102_122_dialog_content = "뭐, 상관없어. 녀석이 키아로의 능력을 발현하는 법을 모르는 이상,\n우린 걱정할 거 없어.",
  ui_story_5028_50281102_123_dialog_content = "알겠어, 그럼 조금 더 살펴볼게... 멀리서 뭔가가 움직이는 것 같아.",
  ui_story_5028_50281102_124_dialog_content = "아, 뭐야. 잡동사니 속에 레비가 숨어 있었네.",
  ui_story_5028_50281102_125_dialog_content = "잠깐만, 레비?!",
  ui_story_5028_50281102_126_dialog_content = "PlayerName! 이제야 내 생각이 난 거야?",
  ui_story_5028_50281102_127_dialog_content = "놀다가 PlayerName 네가 갑자기 사라져 버렸잖아.",
  ui_story_5028_50281102_128_dialog_content = "아, 그랬지... 노는 도중에 피아가 억지로 날 데려가서...",
  ui_story_5028_50281102_129_dialog_content = "진짜 미안해!",
  ui_story_5028_50281102_130_dialog_content = "우리가 한참 찾았다고!",
  ui_story_5028_50281102_131_dialog_content = "「우리」? 또 누가 있는데? 감응해 볼게!",
  ui_story_5028_50281102_132_dialog_content = "제네비브구나...",
  ui_story_5028_50281102_133_dialog_content = "PlayerName, 곁에 있는 건 새로운 동료들이야?",
  ui_story_5028_50281102_134_dialog_content = "역시 PlayerName 넌 정말 인기가 많다니까.",
  ui_story_5028_50281102_135_dialog_content = "순식간에 또 그렇게 많은 사람의 마음을 묶어 버렸잖아.",
  ui_story_5028_50281102_136_dialog_content = "스모키도 있어?! 제네비브랑 안 싸웠어?!",
  ui_story_5028_50281102_137_dialog_content = "쳇, 뭐야, 동료였어?",
  ui_story_5028_50281102_138_dialog_content = "시원하게 한판 불태울 줄 알았는데.",
  ui_story_5028_50281102_139_dialog_content = "노, 농담하지 마!",
  ui_story_5028_50281102_140_dialog_content = "그래도 다행이네! 이렇게 사람이 많으면 분명히 이 상황을 역전할 수 있을 거야!",
  ui_story_5028_50281102_141_dialog_content = "우리 지금 좀 곤란해졌거든. 도움이 필요해!",
  ui_story_5028_50281102_142_dialog_content = "물론 그래야지. PlayerName 넌 내 동료잖아, 언제든지 도와줄게!",
  ui_story_5028_50281102_143_dialog_content = "다들 마찬가지야. 모두 PlayerName 널 찾으러 온 거니까.",
  ui_story_5028_50281102_144_dialog_content = "고마워!",
  ui_story_5028_50281102_145_dialog_content = "피아, 시라, 비크 씨, 방법이 생겼어!",
  ui_story_5028_50281102_146_dialog_content = "도와줄 사람을 찾았어!",
  ui_story_5028_50281102_147_dialog_content = "후후후, 너무 느리잖아!",
  ui_story_5028_50281102_148_dialog_content = "네가 쭈뼛쭈뼛 생각하는 동안 난 이미 <color=#FFB400>절묘한 계획</color>을 생각해 냈다구.",
  ui_story_5028_50281102_149_dialog_content = "어? 지, 진짜?",
  ui_story_5028_50281102_150_dialog_content = "환상동물 마스터를 얕보면 곤란해.",
  ui_story_5028_50281102_151_dialog_content = "자, 들어 봐. 일단 이렇게 하고... 그다음에는 이렇게...",
  ui_story_5028_50281201_1_dialog_content = "<color=#e8d9bb>게리의 기지 밖</color>",
  ui_story_5028_50281201_2_dialog_content = "어이, 두목님 계획이 정말 성공할까?",
  ui_story_5028_50281201_3_dialog_content = "쉿... 조용히 해.",
  ui_story_5028_50281201_4_dialog_content = "계획의 가능성을 의심하는 걸 두목님이 알면 나무에 하루 종일 매달릴 거라고.",
  ui_story_5028_50281201_5_dialog_content = "휴, 저 비크라는 녀석이 대체 무슨 소릴 했을지 모르겠단 말이지.",
  ui_story_5028_50281201_6_dialog_content = "두목님이 왜 저런 녀석 말을 믿는 거냐고!",
  ui_story_5028_50281201_7_dialog_content = "<color=#e8d9bb>휘리리── 휘리리리──</color>",
  ui_story_5028_50281201_8_dialog_content = "들었어? 두목님이 명령을 내리는 소리야.",
  ui_story_5028_50281201_9_dialog_content = "뭐야? 무슨 내용인데?",
  ui_story_5028_50281201_10_dialog_content = "<color=#e8d9bb>휘리리리── 휘리리──</color>",
  ui_story_5028_50281201_11_dialog_content = "...적이 습격했어!",
  ui_story_5028_50281201_12_dialog_content = "북서쪽 방향에서 온다!",
  ui_story_5028_50281201_13_dialog_content = "어서 가자!",
  ui_story_5028_50281201_14_dialog_content = "휴... 휴우... 적은 어디 있지?",
  ui_story_5028_50281201_15_dialog_content = "뭐야, 아무도 없잖아!",
  ui_story_5028_50281201_16_dialog_content = "<color=#e8d9bb>휘리리── 휘이── 휘리리──</color>",
  ui_story_5028_50281201_17_dialog_content = "뭐야?! 갑자기 웬 아침 식사 신호야?!",
  ui_story_5028_50281201_18_dialog_content = "누가 암호를 멋대로 쓰고 있는 건가?",
  ui_story_5028_50281201_19_dialog_content = "좋았어, 작전 1단계는 대성공!",
  ui_story_5028_50281201_20_dialog_content = "레비가 강도들의 암호 노트를 가져와 줘서 큰 도움이 됐네...",
  ui_story_5028_50281201_21_dialog_content = "암호 노트를 먹은 페코 덕도 있다구!",
  ui_story_5028_50281201_22_dialog_content = "페코페코!",
  ui_story_5028_50281201_23_dialog_content = "그럼 이제 네 차례야, 아이테르!",
  ui_story_5028_50281201_24_dialog_content = "부끄러운 이야기지만, 지금까지 수많은 사건에 휘말리면서...",
  ui_story_5028_50281201_25_dialog_content = "내 도주 능력은 엄청나게 발전했다고!",
  ui_story_5028_50281201_26_dialog_content = "야, 거기 바보 강도! 어디 잡아 보시지!",
  ui_story_5028_50281201_27_dialog_content = "뭐야? 포로가 탈출했어?",
  ui_story_5028_50281201_28_dialog_content = "거기 서라!",
  ui_story_5028_50281201_29_dialog_content = "흐익!",
  ui_story_5028_50281201_30_dialog_content = "(이쪽으로 뛰면 되겠지? 여기서 키아로의 서식지까진 별로 안 멀 거야...)",
  ui_story_5028_50281201_31_dialog_content = "(아까 게리를 찾으러 갈 때 스카이워커도 그 근처에 있었어. 게다가...)",
  ui_story_5028_50281201_32_dialog_content = "(스카이워커를 끈질기게 붙잡고 있는 그 녀석도 같이 있겠지!)",
  ui_story_5028_50281201_33_dialog_content = "캬오오오──!",
  ui_story_5028_50281201_34_dialog_content = "저기 좀 봐!",
  ui_story_5028_50281201_35_dialog_content = "뭐야?! 왜 드라코리온이 한 마리 더 있는 거야?!",
  ui_story_5028_50281201_36_dialog_content = "캬오오오──",
  ui_story_5028_50281201_37_dialog_content = "으아아악──!",
  ui_story_5028_50281201_38_dialog_content = "어서 두목님께 보고해!",
  ui_story_5028_50281201_39_dialog_content = "아, 알겠어!",
  ui_story_5028_50281201_40_dialog_content = "뭐야, 아까 그 드라코리온 녀석도 이미 가버렸는데\n왜 아직도 이렇게 어두운 거지?",
  ui_story_5028_50281201_41_dialog_content = "아이고!",
  ui_story_5028_50281201_42_dialog_content = "하이하이, 하이!",
  ui_story_5028_50281201_43_dialog_content = "그래, 그래. 앞으로는 그렇게 큰 돌 같은 건 안 먹일게...",
  ui_story_5028_50281201_44_dialog_content = "누가 소리를 지른 거야? 무슨 일인데?",
  ui_story_5028_50281201_45_dialog_content = "으악!",
  ui_story_5028_50281201_46_dialog_content = "꾸루룩...",
  ui_story_5028_50281201_47_dialog_content = "뭐야? 왜 바닥이 이렇게 미끄러워?",
  ui_story_5028_50281201_48_dialog_content = "구구구!",
  ui_story_5028_50281201_49_dialog_content = "아, 이번엔 또 뭐야?!",
  ui_story_5028_50281201_50_dialog_content = "어라... 갑자기 왜 잠이...",
  ui_story_5028_50281201_51_dialog_content = "후아암...",
  ui_story_5028_50281201_52_dialog_content = "계획은 순조롭게 진행되고 있는 것 같네.",
  ui_story_5028_50281201_53_dialog_content = "저 녀석들, 강도들을 제대로 제압해 버렸잖아.",
  ui_story_5028_50281201_54_dialog_content = "의외로 실력이 있는데?",
  ui_story_5028_50281201_55_dialog_content = "피아는 내 제자니까 우수한 게 당연하지.",
  ui_story_5028_50281201_56_dialog_content = "난 「환상동물 마스터」야. 내가 이까짓 일도 못 할 리가 없잖아.",
  ui_story_5028_50281201_57_dialog_content = "강도는 한 놈도 안 왔어.",
  ui_story_5028_50281201_58_dialog_content = "PlayerName, 조금만 기다려. 내가 얼른 풀어줄게.",
  ui_story_5028_50281201_59_dialog_content = "휴... 정말 고마워.",
  ui_story_5028_50281201_60_dialog_content = "루!",
  ui_story_5028_50281201_61_dialog_content = "키아로! 다행이야... 다친 데도 없구나!",
  ui_story_5028_50281201_62_dialog_content = "첫 번째 작전은 이걸로 성공이야.",
  ui_story_5028_50281201_63_dialog_content = "다음은 게리를 찾아서 녀석의 음모를 막아야 해.",
  ui_story_5028_50281201_64_dialog_content = "피아.",
  ui_story_5028_50281201_65_dialog_content = "뭐, 뭐야? 왜 그런 눈으로 보는 건데...",
  ui_story_5028_50281201_66_dialog_content = "무시하지 마!",
  ui_story_5028_50281201_67_dialog_content = "아니, 무시할 생각은 없어.",
  ui_story_5028_50281201_68_dialog_content = "넌 결국 어린애니까.",
  ui_story_5028_50281201_69_dialog_content = "말했잖아! 난 어린애가 아니라고!",
  ui_story_5028_50281201_70_dialog_content = "환상동물 마스터라고 불러!",
  ui_story_5028_50281201_71_dialog_content = "알 게 뭐야. 그 이름은 너무 길어. 기억하기 귀찮아.",
  ui_story_5028_50281201_72_dialog_content = "너 진짜!",
  ui_story_5028_50281201_73_dialog_content = "하지만 넌 곁의 환상동물들을 잘 이해하고 있다는 걸 행동으로 증명했어.",
  ui_story_5028_50281201_74_dialog_content = "너, 성장했구나.",
  ui_story_5028_50281201_75_dialog_content = "어?",
  ui_story_5028_50281201_76_dialog_content = "그럼 날 인정해 주겠다는 거야?",
  ui_story_5028_50281201_77_dialog_content = "세세한 지식은 확실히 기억하지 못하지만, 그, 그래도 난 재능이 있다구!",
  ui_story_5028_50281201_78_dialog_content = "내 파트너라면 확실히 이해하고 있으니까!",
  ui_story_5028_50281201_79_dialog_content = "아, 아하하... 이제 이 환상동물 마스터의 대단함을 깨달았겠지?",
  ui_story_5028_50281201_80_dialog_content = "우쭐대긴 일러. 내 인정을 받기엔 아직 멀었으니까.",
  ui_story_5028_50281201_81_dialog_content = "적어도 내 인정을 받기 전까지는...",
  ui_story_5028_50281201_82_dialog_content = "어쩐지 시끄럽다 싶더니, 네놈들이 벌인 짓이었군.",
  ui_story_5028_50281201_83_dialog_content = "루──!",
  ui_story_5028_50281201_84_dialog_content = "그 악당 아저씨가 돌아왔어!",
  ui_story_5028_50281201_85_dialog_content = "쟤가 PlayerName 납치의 진범이야?",
  ui_story_5028_50281201_86_dialog_content = "암귀를 부하로 삼다니, 정말 저질이네.",
  ui_story_5028_50281201_87_dialog_content = "어? 웬일로 우리 제니가 나랑 의견이 같잖아.",
  ui_story_5028_50281201_88_dialog_content = "누, 누가 너랑 같고 싶대?!",
  ui_story_5028_50281201_89_dialog_content = "정말 기분 나쁜 자식이네. 그냥 이 기지를 통째로 태워 버리는 건 어때?",
  ui_story_5028_50281201_90_dialog_content = "어이쿠, 그건 절대 안 되지.",
  ui_story_5028_50281201_91_dialog_content = "게리가 잡아 온 키아로가 여기 잔뜩 있어. 태워 버렸다간 키아로들도 끝장이야!",
  ui_story_5028_50281201_92_dialog_content = "호오, 머릿수가 늘어났군. 설마 거기 비실비실한 놈의 동료냐?",
  ui_story_5028_50281201_93_dialog_content = "비실비실 아니거든!",
  ui_story_5028_50281201_94_dialog_content = "너흰 대체 왜 이놈이고 저놈이고 전부 이 짐승들을 위해 싸우는 거지?",
  ui_story_5028_50281201_95_dialog_content = "얘들은 짐승이 아니야! 내 동료라고!",
  ui_story_5028_50281201_96_dialog_content = "동료? 하하... 하하하하! 아니, 이것들은 그저 열등한 짐승일 뿐이다.",
  ui_story_5028_50281201_97_dialog_content = "네가 동료라고 생각한다 해도, 놈들이 과연 그렇게 생각할까?",
  ui_story_5028_50281201_98_dialog_content = "겉모습은 무해해 보여도, 짐승은 결국 짐승일 뿐이다.",
  ui_story_5028_50281201_99_dialog_content = "이용 가치가 없다고 여기는 순간, 놈들은 거리낌 없이 널 버리고, 널 죽이겠지.",
  ui_story_5028_50281201_100_dialog_content = "헛소리하지 마!",
  ui_story_5028_50281201_101_dialog_content = "야, 꼬맹이.",
  ui_story_5028_50281201_102_dialog_content = "난 피아야!",
  ui_story_5028_50281201_103_dialog_content = "나랑 상관없잖아. 아무튼 내 말 들어.\n저 녀석은 이미 영문 모를 원한 때문에 머리가 망가져 있어.",
  ui_story_5028_50281201_104_dialog_content = "저런 놈을 설득하는 건 너무 귀찮아. 가장 직접적인 설득법이 필요해...",
  ui_story_5028_50281201_105_dialog_content = "그게 뭔데?",
  ui_story_5028_50281201_106_dialog_content = "뭔데...?",
  ui_story_5028_50281201_107_dialog_content = "물리적 설득.",
  ui_story_5028_50281201_108_dialog_content = "오오, 역시 시라다운 답이었어.",
  ui_story_5028_50281201_109_dialog_content = "싸우겠다는 거냐?",
  ui_story_5028_50281201_110_dialog_content = "하하, 그것도 좋지.",
  ui_story_5028_50281201_111_dialog_content = "몇 번이든 마찬가지다. 너흰 영원히 날 이길 수 없다.",
  ui_story_5028_50281201_112_dialog_content = "크오오──!",
  ui_story_5028_50281202_1_dialog_content = "가라, 키아로!",
  ui_story_5028_50281202_2_dialog_content = "루──!",
  ui_story_5028_50281202_3_dialog_content = "느리군.",
  ui_story_5028_50281202_4_dialog_content = "캬아악!",
  ui_story_5028_50281202_5_dialog_content = "레비! 피아를 지켜줘!",
  ui_story_5028_50281202_6_dialog_content = "마음대로 될 줄 알고!",
  ui_story_5028_50281202_7_dialog_content = "화염 채찍!",
  ui_story_5028_50281202_8_dialog_content = "어때? 내 동료들, 손발이 잘 맞지?",
  ui_story_5028_50281202_9_dialog_content = "으윽...",
  ui_story_5028_50281202_10_dialog_content = "하, 그래봤자 잔꾀일 뿐, 널 다시 볼 정도는 아니었어.",
  ui_story_5028_50281202_11_dialog_content = "오히려 그쪽 오로리안들은 확실히 성가시군.",
  ui_story_5028_50281202_12_dialog_content = "그럼 이건 어떨까?",
  ui_story_5028_50281202_13_dialog_content = "저 녀석 채찍에서 <color=#FFB400>이상한 빛</color>이 나고 있어!",
  ui_story_5028_50281202_14_dialog_content = "다들 조심해!",
  ui_story_5028_50281202_15_dialog_content = "루... 루...!",
  ui_story_5028_50281202_16_dialog_content = "키아로? 키아로!",
  ui_story_5028_50281202_17_dialog_content = "페코...",
  ui_story_5028_50281202_18_dialog_content = "이 나쁜 아저씨! 뭘 한 거야?!",
  ui_story_5028_50281202_19_dialog_content = "보채지 마라, 꼬맹아.",
  ui_story_5028_50281202_20_dialog_content = "이제 곧 네 그 귀여운 동물 친구들이 네 배를 가르는 모습을 볼 수 있을 테니까!",
  ui_story_5028_50281202_21_dialog_content = "내 동료들은 안 그래!",
  ui_story_5028_50281202_22_dialog_content = "저 채찍을 공격해!",
  ui_story_5028_50281202_23_dialog_content = "알았어!",
  ui_story_5028_50281202_24_dialog_content = "에잇!",
  ui_story_5028_50281202_25_dialog_content = "이 자식, 대체 암귀를 몇 마리나 조종하고 있는 거야...?",
  ui_story_5028_50281202_26_dialog_content = "암귀 같은 건 원하는 만큼 얼마든지 손에 넣을 수 있지.",
  ui_story_5028_50281202_27_dialog_content = "죽더라도 끊임없이 새로운 암귀가 보충된다.",
  ui_story_5028_50281202_28_dialog_content = "다들 같이 공격해!",
  ui_story_5028_50281202_29_dialog_content = "<color=#e8d9bb>루──!</color>",
  ui_story_5028_50281202_30_dialog_content = "키아로가 우는 거야?",
  ui_story_5028_50281202_31_dialog_content = "<color=#e8d9bb>루── 루우──!</color>",
  ui_story_5028_50281202_32_dialog_content = "아니야. 이건 내 키아로 소리가 아냐!",
  ui_story_5028_50281202_33_dialog_content = "키아로의 울음소리가 사방에서 들리고 있어!",
  ui_story_5028_50281202_34_dialog_content = "이런...",
  ui_story_5028_50281202_35_dialog_content = "녀석이 노리는 건 피아의 환상동물만이 아냐...\n이 기지로 끌려온 모든 키아로야!",
  ui_story_5028_50281202_36_dialog_content = "아, 그건 곤란한데.",
  ui_story_5028_50281202_37_dialog_content = "키아로들을 두고 갈 순 없어! 누가 쟤들을 데리고 가야 해!",
  ui_story_5028_50281202_38_dialog_content = "시라 선배!",
  ui_story_5028_50281202_39_dialog_content = "뭐야...?",
  ui_story_5028_50281202_40_dialog_content = "선배는 환상동물을 잘 이해한다고 했잖아?",
  ui_story_5028_50281202_41_dialog_content = "지금 선배는 다쳐서 싸울 수가 없어. 그러니까 쟤들을 데리고 도망쳐!",
  ui_story_5028_50281202_42_dialog_content = "죽음을 앞에 두고도 짐승 따위를 신경 쓰는 거냐.",
  ui_story_5028_50281202_43_dialog_content = "정말 이상한 놈들이군.",
  ui_story_5028_50281202_44_dialog_content = "캬아악──!",
  ui_story_5028_50281202_45_dialog_content = "모두 쳐라!",
  ui_story_5028_50281202_46_dialog_content = "으윽!",
  ui_story_5028_50281202_47_dialog_content = "이번엔 몇 명이나 묶였나 볼까? 하나, 둘, 셋...",
  ui_story_5028_50281202_48_dialog_content = "수확은 충분한걸.",
  ui_story_5028_50281202_49_dialog_content = "넌 너무 느려. 이런 녀석들은 한 번에 태워버리는 게 더 깔끔하다고.",
  ui_story_5028_50281202_50_dialog_content = "그래? 그럼 누가 더 많은 사냥감을 잡을지 한번 볼까?",
  ui_story_5028_50281202_51_dialog_content = "루우우!",
  ui_story_5028_50281202_52_dialog_content = "비크한테 못 들었어? 환상동물들은 나한테 다가오고 싶어 하지 않아.",
  ui_story_5028_50281202_53_dialog_content = "그럼 이 환상동물 마스터가 선언해 주겠어! 그건 이미 지나간 일이야!",
  ui_story_5028_50281202_54_dialog_content = "무슨 소리야...?",
  ui_story_5028_50281202_55_dialog_content = "와라, 드라코리온!",
  ui_story_5028_50281202_56_dialog_content = "캬오오오──!",
  ui_story_5028_50281202_57_dialog_content = "(피아가... 저 용을 불러왔잖아?)",
  ui_story_5028_50281202_58_dialog_content = "캬오...",
  ui_story_5028_50281202_59_dialog_content = "힘들게 해서 미안해. 그래도 좀 부탁할게...",
  ui_story_5028_50281202_60_dialog_content = "시라 선배를 데리고 숲속의 환상동물들을 찾아줘.\n그리고 모두를 데리고 여길 떠나는 거야!",
  ui_story_5028_50281202_61_dialog_content = "시라 선배!",
  ui_story_5028_50281202_62_dialog_content = "......",
  ui_story_5028_50281202_63_dialog_content = "(시라가 용한테 조금씩 다가가고 있어...)",
  ui_story_5028_50281202_64_dialog_content = "......!",
  ui_story_5028_50281202_65_dialog_content = "(다행이야...! 녀석이 시라를 거부하지 않았어!)",
  ui_story_5028_50281202_66_dialog_content = "어떻게 이런...",
  ui_story_5028_50281202_67_dialog_content = "그럼 이 「환상동물 마스터」한테 충분히 감사하라구!",
  ui_story_5028_50281202_68_dialog_content = "이제 얼른 가!",
  ui_story_5028_50281202_69_dialog_content = "하하... 하하하...",
  ui_story_5028_50281202_70_dialog_content = "왜 웃는 거지?",
  ui_story_5028_50281202_71_dialog_content = "역시 너흰 하나같이 모자란 철부지들이군.",
  ui_story_5028_50281202_72_dialog_content = "고작 짐승 몇 마리와 비실대는 놈이나 데리고 날 방해하려 하다니.",
  ui_story_5028_50281202_73_dialog_content = "가장 재미있는 건 마지막까지 남겨둘 생각이었는데...",
  ui_story_5028_50281202_74_dialog_content = "네놈들에겐 미리 보여줘도 괜찮겠지.",
  ui_story_5028_50281202_75_dialog_content = "나와라.",
  ui_story_5028_50281202_76_dialog_content = "루...",
  ui_story_5028_50281202_77_dialog_content = "이거... 키아로 소리 아냐?",
  ui_story_5028_50281202_78_dialog_content = "아까 그 키아로인가?",
  ui_story_5028_50281202_79_dialog_content = "그, 그런다고 내가 겁먹을 줄 알고?!",
  ui_story_5028_50281202_80_dialog_content = "루!",
  ui_story_5028_50281202_81_dialog_content = "흐이익──?!",
  ui_story_5028_50281202_82_dialog_content = "저, 저저저...저건 아무리 봐도 그냥 암귀잖아?!",
  ui_story_5028_50281202_83_dialog_content = "왜 암귀가 키아로 소리를 내는 거야?!",
  ui_story_5028_50281202_84_dialog_content = "루우우... 루우!",
  ui_story_5028_50281202_85_dialog_content = "저 녀석, 확실히 그 키아로가 맞아.",
  ui_story_5028_50281202_86_dialog_content = "키아로의 가장 큰 힘은 바로 <color=#FFB400>「의태」</color>거든.",
  ui_story_5028_50281202_87_dialog_content = "동료한테 격려를 받으면 어떤 생물의 모습으로도 변할 수 있고,\n그 대상의 능력까지도 사용할 수 있어.",
  ui_story_5028_50281202_88_dialog_content = "그렇게 중요한 건 좀 일찍 말해 줬어야지!",
  ui_story_5028_50281202_89_dialog_content = "아이참, 나도 키아로가 극도의 공포에 빠진 상태에서도\n저 힘을 쓸 수 있을 줄은 몰랐단 말이야.",
  ui_story_5028_50281202_90_dialog_content = "보통 키아로는 자신이 믿는 동료를 지키기 위해서만 능력을 사용하거든.",
  ui_story_5028_50281202_91_dialog_content = "이거 정말 엄청나게 곤란하게 됐잖아.",
  ui_story_5028_50281202_92_dialog_content = "지금 이런 상황에서 웃음이 나와?!",
  ui_story_5028_50281202_93_dialog_content = "저 녀석 그냥 봐도 엄청 무서워 보이잖아! 이제 어떻게 해?!",
  ui_story_5028_50281202_94_dialog_content = "좋은 질문이야.",
  ui_story_5028_50281202_95_dialog_content = "키아로는 희귀 환상동물이야.\n키아로의 신뢰를 얻을 수 있다면 천하무적이 될 수 있지.",
  ui_story_5028_50281202_96_dialog_content = "그리고 그 키아로에 맞설 수 있는 건 키아로뿐이야.",
  ui_story_5028_50281301_1_dialog_content = "루!",
  ui_story_5028_50281301_2_dialog_content = "루루!",
  ui_story_5028_50281301_3_dialog_content = "쳇, 저 녀석 왜 저렇게 센 거야?!",
  ui_story_5028_50281301_4_dialog_content = "더 발버둥 쳐라. 이 공포를 뼛속 깊이 새겨라!",
  ui_story_5028_50281301_5_dialog_content = "이제 이 짐승들이 온 아스트라 대륙을 유린할 테니 말이야.",
  ui_story_5028_50281301_6_dialog_content = "하하... 하하하하!",
  ui_story_5028_50281301_7_dialog_content = "잘 가라, 애송이.",
  ui_story_5028_50281301_8_dialog_content = "지금이야, PlayerName!",
  ui_story_5028_50281301_9_dialog_content = "네 힘을 써서 피아의 믿음을 키아로한테 전달하는 거야!",
  ui_story_5028_50281301_10_dialog_content = "뭐? 내, 내 힘?!",
  ui_story_5028_50281301_11_dialog_content = "머리를 써서 진지하게 생각해 봐!",
  ui_story_5028_50281301_12_dialog_content = "(내 힘...)",
  ui_story_5028_50281301_13_dialog_content = "(난 감응 능력으로 모두가 서로 소통하게 할 수 있어.)",
  ui_story_5028_50281301_14_dialog_content = "(소통... 맞아, 피아랑 키아로는 지금까지 쭉 소통할 수 없었어... 설마?!)",
  ui_story_5028_50281301_15_dialog_content = "쉽게 말해서 키아로의 생각과 감정을 감응하고, 그걸 피아한테 전하는 거야.",
  ui_story_5028_50281301_16_dialog_content = "그다음 일은 피아의 재능으로 해결할 수 있어!",
  ui_story_5028_50281301_17_dialog_content = "뭐?! 내가 키아로의 생각을 감응할 수 있다고?",
  ui_story_5028_50281301_18_dialog_content = "당연하지. 잊지 마. 넌 아이테르잖아!",
  ui_story_5028_50281301_19_dialog_content = "그, 그럼... 한번 해 볼게!",
  ui_story_5028_50281301_20_option_content = "(강제 감응!)",
  ui_story_5028_50281301_21_dialog_content = "키아로의 생각을 감응하자...",
  ui_story_5028_50281301_22_dialog_content = "루, 루우!",
  ui_story_5028_50281301_23_dialog_content = "초조해하고 있어. 왠지 어떤 힘이 억눌려 있어서 사용할 수 없는 것 같아...",
  ui_story_5028_50281301_24_dialog_content = "루루!",
  ui_story_5028_50281301_25_dialog_content = "이 감정... 지키고 싶다는 건가?",
  ui_story_5028_50281301_26_dialog_content = "지킨다... 지킨다고?",
  ui_story_5028_50281301_27_dialog_content = "피아! 키아로가 널 지키고 싶어 해!",
  ui_story_5028_50281301_28_dialog_content = "뭐?!",
  ui_story_5028_50281301_29_dialog_content = "루우우!",
  ui_story_5028_50281301_30_dialog_content = "이 말이 지키고 싶다는 뜻인 거야?!",
  ui_story_5028_50281301_31_dialog_content = "루우, 루우!",
  ui_story_5028_50281301_32_dialog_content = "지금 네 생각에 동의하는 것 같아. 그리고 엄청 초조해!",
  ui_story_5028_50281301_33_dialog_content = "초조... 동의...",
  ui_story_5028_50281301_34_dialog_content = "이 울음소리에 대응하는 게 그런 의미였어?",
  ui_story_5028_50281301_35_dialog_content = "알겠어... 피아, 이제 다 알았어!",
  ui_story_5028_50281301_36_dialog_content = "알았다니? 뭘 알았는데?",
  ui_story_5028_50281301_37_dialog_content = "네가 알려준 정보 덕분에 키아로가 내는 울음소리와 의미를 서로 맞출 수 있었어.",
  ui_story_5028_50281301_38_dialog_content = "그러니까 키아로의 말을 해독했다는 거야!",
  ui_story_5028_50281301_39_dialog_content = "성공한 거야?!",
  ui_story_5028_50281301_40_dialog_content = "루우우! 루우, 루──!",
  ui_story_5028_50281301_41_dialog_content = "지, 지금 뭐라고 하는데?",
  ui_story_5028_50281301_42_dialog_content = "「내가 피아를 지킨다」고 했어!",
  ui_story_5028_50281301_43_dialog_content = "루──!",
  ui_story_5028_50281301_44_dialog_content = "뭐? 키아로, 너 피아랑 소통하면서 새로운 힘을 얻었다고?",
  ui_story_5028_50281301_45_dialog_content = "그럼 얼른 사용해 봐!",
  ui_story_5028_50281301_46_dialog_content = "앗! 키아로가 빛나고 있어!",
  ui_story_5028_50281301_47_dialog_content = "키아로의 모습이...!",
  ui_story_5028_50281301_48_dialog_content = "피아, 키아로, 그 힘을 사용해서 게리를 쓰러트려!",
  ui_story_5028_50281301_49_dialog_content = "말 안 해도 알고 있거든!",
  ui_story_5028_50281301_50_dialog_content = "네놈들 따위가 날 쓰러트리겠다고? 꿈도 크군!",
  ui_story_5028_50281301_51_dialog_content = "가라, 짐승들아. 저놈들을 모조리 짓밟아라!",
  ui_story_5028_50281301_52_dialog_content = "캬오오오──!",
  ui_story_5028_50281301_53_dialog_content = "루!",
  ui_story_5028_50281302_1_dialog_content = "가라, 키아로! 저 악당 아저씨한테 똑바로 알려줘!\n우린 그렇게 만만하지 않다고!",
  ui_story_5028_50281302_2_dialog_content = "루!",
  ui_story_5028_50281302_3_dialog_content = "이, 이건... 어째서?!",
  ui_story_5028_50281302_4_dialog_content = "루! 루우우!",
  ui_story_5028_50281302_5_dialog_content = "게리의 키아로가 고통스러운 울음소리를 내고 있어...",
  ui_story_5028_50281302_6_dialog_content = "키아로...",
  ui_story_5028_50281302_7_dialog_content = "키아로! 녀석의 채찍을 노려!",
  ui_story_5028_50281302_8_dialog_content = "루우우!",
  ui_story_5028_50281302_9_dialog_content = "으윽!",
  ui_story_5028_50281302_10_dialog_content = "지금이야!",
  ui_story_5028_50281302_11_dialog_content = "나한테 맡겨!",
  ui_story_5028_50281302_12_dialog_content = "타올라라!",
  ui_story_5028_50281302_13_dialog_content = "화염 채찍!",
  ui_story_5028_50281302_14_dialog_content = "암귀는 전부 해치웠어!",
  ui_story_5028_50281302_15_dialog_content = "마지막 적은 내가 묶었어. 승리는 내 거야.",
  ui_story_5028_50281302_16_dialog_content = "얌체같이 실속만 챙기면 안 되지, 제니.",
  ui_story_5028_50281302_17_dialog_content = "그 녀석은 분명히 내가 먼저 때려눕혔어.",
  ui_story_5028_50281302_18_dialog_content = "넌 거기다 그냥 채찍 자국만 냈을 뿐이잖아.",
  ui_story_5028_50281302_19_dialog_content = "적을 전부 쓰러트린 거야?",
  ui_story_5028_50281302_20_dialog_content = "성공했나...?",
  ui_story_5028_50281302_21_dialog_content = "루!",
  ui_story_5028_50281302_22_dialog_content = "예~이!",
  ui_story_5028_50281302_23_dialog_content = "빌어먹을...",
  ui_story_5028_50281302_24_dialog_content = "녀석도 더는 키아로를 제어할 수 없어!",
  ui_story_5028_50281302_25_dialog_content = "PlayerName, 피아의 마음속 목소리를 저 키아로한테 전해줘.\n아까 했던 것처럼!",
  ui_story_5028_50281302_26_dialog_content = "알겠어!",
  ui_story_5028_50281302_27_option_content = "(강제 감응!)",
  ui_story_5028_50281302_28_dialog_content = "너도 키아로의 동족이지?",
  ui_story_5028_50281302_29_dialog_content = "이제 저 악당 아저씨 때문에 무서워하지 않아도 돼!",
  ui_story_5028_50281302_30_dialog_content = "우리가 널 제어하던 녀석의 능력을 없앴으니까,\n이제 누구도 너한테 싫은 일을 억지로 시키지 않을 거야!",
  ui_story_5028_50281302_31_dialog_content = "이제 억지로 싸울 필요도 없어. 우리랑 같이 가자.",
  ui_story_5028_50281302_32_dialog_content = "환상동물 마스터인 내가 지켜줄게!",
  ui_story_5028_50281302_33_dialog_content = "루... 루?",
  ui_story_5028_50281302_34_dialog_content = "루!",
  ui_story_5028_50281302_35_dialog_content = "걱정 마. 난 저 악당 아저씨랑 달라. 널 소중하게 대해줄게!",
  ui_story_5028_50281302_36_dialog_content = "......",
  ui_story_5028_50281302_37_dialog_content = "이런, 저 키아로는 오랫동안 게리한테 학대당해서 몸도 마음도 이미 한계야!",
  ui_story_5028_50281302_38_dialog_content = "어서 여길 벗어나서 쉬게 해 줘야 돼...",
  ui_story_5028_50281302_39_dialog_content = "내 복수, 내 증오를... 너희 같은 멍청한 놈들이 망치게 둘 순 없어!",
  ui_story_5028_50281302_40_dialog_content = "이 빌어먹을 짐승, 당장 일어서!",
  ui_story_5028_50281302_41_dialog_content = "아직 쉴 때가 아니란 말이다!",
  ui_story_5028_50281302_42_dialog_content = "루... 루...!",
  ui_story_5028_50281302_43_dialog_content = "이 키아로, 계속 아프다고 소리쳤던 거야...?",
  ui_story_5028_50281302_44_dialog_content = "악당 아저씨, 그만해!",
  ui_story_5028_50281302_45_dialog_content = "아파하고 있잖아!",
  ui_story_5028_50281302_46_dialog_content = "아파?",
  ui_story_5028_50281302_47_dialog_content = "물론 그래야지!",
  ui_story_5028_50281302_48_dialog_content = "아프지 않다면 어떻게 날 두려워하겠냔 말이다!",
  ui_story_5028_50281302_49_dialog_content = "오직 두려움만이 녀석의 힘을 최대한으로 끌어낼 수 있는 것이다!",
  ui_story_5028_50281302_50_dialog_content = "네 모든 힘을 끌어내서 놈들을 해치워라!",
  ui_story_5028_50281302_51_dialog_content = "죽고 싶지 않으면 똑바로 하라고!",
  ui_story_5028_50281302_52_dialog_content = "루우, 루!",
  ui_story_5028_50281302_53_dialog_content = "루!",
  ui_story_5028_50281302_54_dialog_content = "앗! 어, 어떡하지? 도움을 청하고 있어!",
  ui_story_5028_50281302_55_dialog_content = "다시 쓰러트려야 되나?",
  ui_story_5028_50281302_56_dialog_content = "루!",
  ui_story_5028_50281302_57_dialog_content = "멈춰, 피아!",
  ui_story_5028_50281302_58_dialog_content = "저 키아로는 이미 한계야. 더는 너희 공격을 견딜 수 없어!",
  ui_story_5028_50281302_59_dialog_content = "그, 그럼 어떻게 해야 되냐고! 이 허접 사부야!",
  ui_story_5028_50281302_60_dialog_content = "하아, 이렇게 된 이상 이제는 하늘에 행운을 빌 수밖에 없겠어.",
  ui_story_5028_50281302_61_dialog_content = "역시 사부 따위를 믿는 게 아니었어!",
  ui_story_5028_50281302_62_dialog_content = "하하하! 기도나 해라. 이게 너희의 마지막 기회다!",
  ui_story_5028_50281302_63_dialog_content = "이제...",
  ui_story_5028_50281302_64_dialog_content = "역시 싸움 같은 게 제일 귀찮다니까.",
  ui_story_5028_50281302_65_dialog_content = "뭐지?",
  ui_story_5028_50281302_66_dialog_content = "근데 말이야. 너 같은 놈을 내버려 두면 앞으로 더 귀찮아지겠지!",
  ui_story_5028_50281302_67_dialog_content = "캬오오오──",
  ui_story_5028_50281302_68_dialog_content = "으윽! 이런...",
  ui_story_5028_50281302_69_option_content = "하늘에 빈 행운이... 시라?!",
  ui_story_5028_50281302_70_option_content = "시라가 하늘에서 떨어져서 게리를 걷어찼어!",
  ui_story_5028_50281302_71_dialog_content = "애초에 행운 따윈 없어.",
  ui_story_5028_50281302_72_dialog_content = "그저 계속, 또 계속해서 노력해서 쌓인 것들이 지금의 변화를 가져왔을 뿐이야.",
  ui_story_5028_50281302_73_dialog_content = "시라 선배──!",
  ui_story_5028_50281302_74_dialog_content = "여, 역시 내가 똑똑한 덕분이라구!\n시라 선배랑 드라코리온한테 다른 동물을 구하러 가라고 했잖아!",
  ui_story_5028_50281302_75_dialog_content = "그 덕에 게리의 음모를 막을 수 있었어!",
  ui_story_5028_50281302_76_dialog_content = "하아, 넌 대체 성장한 걸까, 아니면 조금도 성장하지 않은 걸까?",
  ui_story_5028_50281302_77_dialog_content = "루...",
  ui_story_5028_50281302_78_dialog_content = "우와악?!",
  ui_story_5028_50281302_79_dialog_content = "루우?!",
  ui_story_5028_50281302_80_dialog_content = "아무래도 이 아이는 게리한테 상처를 많이 받은 것 같아.",
  ui_story_5028_50281302_81_dialog_content = "좀 쉬게 해 주자.",
  ui_story_5028_50281302_82_dialog_content = "그럼 이 귀찮은 놈은 어떻게 처리할까?",
  ui_story_5028_50281302_83_dialog_content = "크억! 윽!",
  ui_story_5028_50281302_84_dialog_content = "(시라가 촉수 하나로 게리의 멱살을 잡았어...)",
  ui_story_5028_50281302_85_dialog_content = "(게다가 살기가 넘치잖아!)",
  ui_story_5028_50281302_86_dialog_content = "(무, 무서워!)",
  ui_story_5028_50281302_87_dialog_content = "루우우...",
  ui_story_5028_50281302_88_dialog_content = "하하... 내가... 실패하다니...",
  ui_story_5028_50281302_89_dialog_content = "죽여라.",
  ui_story_5028_50281302_90_dialog_content = "어쩌면 이 짐승들 손에 죽는 게 내 운명이었는지도 모르겠군.",
  ui_story_5028_50281302_91_dialog_content = "이 녀석을 그냥 놔두면 귀찮은 일만 생길 뿐이야.",
  ui_story_5028_50281302_92_dialog_content = "그걸 막으려면 역시...",
  ui_story_5028_50281302_93_dialog_content = "그 녀석을 어떻게 할지는 이번 사건의 최대 공로자...\n피아의 의견부터 들어보자. 어떻게 하고 싶어?",
  ui_story_5028_50281302_94_dialog_content = "......",
  ui_story_5028_50281302_95_dialog_content = "피아?",
  ui_story_5028_50281302_96_dialog_content = "당연히... 악당 아저씨를 감옥에 보내야지!",
  ui_story_5028_50281302_97_dialog_content = "뭐?",
  ui_story_5028_50281302_98_dialog_content = "하, 감옥이라고?",
  ui_story_5028_50281302_99_dialog_content = "감옥에서 나오면 난 똑같이 이 짐승들한테 복수할 거다.",
  ui_story_5028_50281302_100_dialog_content = "그럼 이 「환상동물 마스터」가 다시 막을 거야!",
  ui_story_5028_50281302_101_dialog_content = "그리고 이 환상동물들이 「환상동물 마스터」인 내 보호 아래,\n씩씩하게 자라는 걸 보여주겠어!",
  ui_story_5028_50281302_102_dialog_content = "그거야말로 너한테 가장 큰 벌이니까!",
  ui_story_5028_50281302_103_dialog_content = "으음~ 정말 멋진 대사였어.",
  ui_story_5028_50281302_104_dialog_content = "으악! 시, 시라 선배랑 같은 문어? 문어남?!",
  ui_story_5028_50281302_105_dialog_content = "그렇게 부르면 나 상처받을 거야.",
  ui_story_5028_50281302_106_dialog_content = "클레이튼, 네가 여기 있다는 건... 섀도우마스터가...",
  ui_story_5028_50281302_107_dialog_content = "참 신기하네, PlayerName.\n너희가 잡은 이 강도, 마침 섀도우마스터가 찾고 있는 녀석이거든.",
  ui_story_5028_50281302_108_dialog_content = "이렇게 귀찮은 녀석이 섀도우마스터 눈에 안 띄는 게 더 이상하잖아.",
  ui_story_5028_50281302_109_dialog_content = "아가씨 말이 맞아.",
  ui_story_5028_50281302_110_dialog_content = "게리, 10년 전 당신 아내와 아이는 실수로 환상동물의 서식지에\n들어갔다가 난폭한 환상동물 손에 목숨을 잃었지.",
  ui_story_5028_50281302_111_dialog_content = "그 뒤로 당신은 각지에서 환상동물을 사냥하기 시작했어.",
  ui_story_5028_50281302_112_dialog_content = "단순한 사냥이라면 섀도우마스터도 간섭하진 않았을 거야.",
  ui_story_5028_50281302_113_dialog_content = "하지만 당신 행위는 선을 넘었고, 움브라톤을 위협하고 있어.",
  ui_story_5028_50281302_114_dialog_content = "움브라톤을 위협해? 그렇게 큰일이야?",
  ui_story_5028_50281302_115_dialog_content = "당연하지, 아가씨.",
  ui_story_5028_50281302_116_dialog_content = "움브라톤 주변엔 많은 환상동물들이 서식하고 있어.\n저들은 움브라톤의 안전을 유지하는 중요한 존재야.",
  ui_story_5028_50281302_117_dialog_content = "환상동물들은 자신들의 서식지를 지키기 위해 다른 위협적인 생물들을 쫓아내.\n그중엔 암귀도 포함되어 있어.",
  ui_story_5028_50281302_118_dialog_content = "그렇게 움브라톤 주변에 보이지 않는 벽을 쌓고,\n암귀와 오로리안의 세계를 격리시켜 주고 있는 거야.",
  ui_story_5028_50281302_119_dialog_content = "그런 환상동물들이 사라져 버린다면,\n움브라톤은 암귀의 공격에 직면하게 될지도 몰라.",
  ui_story_5028_50281302_120_dialog_content = "그런 거였구나...",
  ui_story_5028_50281302_121_dialog_content = "하, 섀도우마스터?",
  ui_story_5028_50281302_122_dialog_content = "섀도우마스터가 이제 와서 날 노릴 힘이 있다면,\n왜 진작에 그 짐승들을 없애서 내 아내와 아이를 지키지 않은 거지?",
  ui_story_5028_50281302_123_dialog_content = "저들은 너희가 늘 말하는 「규칙」 아래에서 살았던 자가 아니기라도 하다는 거냐?!",
  ui_story_5028_50281302_124_dialog_content = "섀도우마스터는 움브라톤의 규칙이지, 숲의 규칙은 아니야.",
  ui_story_5028_50281302_125_dialog_content = "규칙을 지키는 것 또한 규칙 그 자체니까.",
  ui_story_5028_50281302_126_dialog_content = "흥! 입만 살았군.",
  ui_story_5028_50281302_127_dialog_content = "게리.",
  ui_story_5028_50281302_128_dialog_content = "뭐냐, 너까지 나한테 설교하려는 거냐?",
  ui_story_5028_50281302_129_dialog_content = "아니면 내가 널 속였으니 복수라도 할 셈이냐?",
  ui_story_5028_50281302_130_dialog_content = "쳇, 좋을 대로 해라. 네가 뭐라고 하든 내 생각은 변하지 않으니까.",
  ui_story_5028_50281302_131_dialog_content = "아무도 날 막을 수 없어! 아무도!",
  ui_story_5028_50281302_132_dialog_content = "그건 당신이 결정할 일이 아니야.",
  ui_story_5028_50281302_133_dialog_content = "환상동물들을 서로 죽이도록 훈련시키고,\n결국 이 세상에서 모든 환상동물을 말살하려 한다면...",
  ui_story_5028_50281302_134_dialog_content = "설령 섀도우마스터가 손을 쓰지 않았더라도,\n이쪽의 아가씨처럼 누군가가 당신을 막겠지.",
  ui_story_5028_50281302_135_dialog_content = "게리.",
  ui_story_5028_50281302_136_dialog_content = "내 날개가 왜 한쪽뿐인지 알고 있어?",
  ui_story_5028_50281302_137_dialog_content = "모르지. 그게 나와 무슨 상관이냐.",
  ui_story_5028_50281302_138_dialog_content = "에?",
  ui_story_5028_50281302_139_option_content = "그러게...?",
  ui_story_5028_50281302_140_dialog_content = "나도 전부터 저게 신경이 쓰였는데, 저 사람은 매번 말을 돌렸어.",
  ui_story_5028_50281302_141_dialog_content = "어렸을 때 난 환상동물들을 너무 좋아해서, 항상 녀석들에게 다가가려고 했었어.",
  ui_story_5028_50281302_142_dialog_content = "근데 그때 난 아직 환상동물들의 습성을 잘 몰랐어.\n그러다 무심코 어떤 환상동물을 화나게 했던 거야.",
  ui_story_5028_50281302_143_dialog_content = "성난 환상동물은 날 공격했고, 내 한쪽 날개를 찢어버렸어.\n그래서 지금 같은 모습이 된 거지.",
  ui_story_5028_50281302_144_dialog_content = "그 짐승한테 그런 꼴을 당하고도 화가 안 났던 거냐?",
  ui_story_5028_50281302_145_dialog_content = "그때는 이해가 안 되고 속상했어. 하지만 그 뒤에 난 어떤 친구를 만났어.\n그 친구의 도움 덕분에 난 환상동물을 조금씩 이해할 수 있게 됐어.",
  ui_story_5028_50281302_146_dialog_content = "환상동물들의 눈에도 우리 오로리안은 마찬가지로 이해할 수 없는 생물이야.",
  ui_story_5028_50281302_147_dialog_content = "저들은 본능적으로 우릴 의심하고 두려워할 거야.\n우리가 다가가면 자기 몸을 지키기 위해 공격하겠지.",
  ui_story_5028_50281302_148_dialog_content = "이건 우리가 환상동물들을 대하는 방식과 다를 게 없어.",
  ui_story_5028_50281302_149_dialog_content = "게다가 환상동물의 입장에서 오로리안은 자신들을 사냥, 포획하고,\n자신들의 터전을 침범하는 악당이야.",
  ui_story_5028_50281302_150_dialog_content = "오로리안과 동물의 마음을 통하게 해주는 그 친구가 없었다면...",
  ui_story_5028_50281302_151_dialog_content = "나도 환상동물들이 우릴 그렇게 생각한다는 걸 평생 알 수 없었겠지.",
  ui_story_5028_50281302_152_dialog_content = "그래서 난 환상동물들을 이해하고 용서하기로 했어.",
  ui_story_5028_50281302_153_dialog_content = "그게 나와 같다고 말할 수 있나?",
  ui_story_5028_50281302_154_dialog_content = "놈들을 용서하고 말고는 네 일방적인 감정이다.",
  ui_story_5028_50281302_155_dialog_content = "하지만 내 가족은 목숨을 빼앗겼다!",
  ui_story_5028_50281302_156_dialog_content = "내가 알기로 넌 그 사건 뒤로 혼자 그 숲에서 사냥을 시작했어. 안 그래?",
  ui_story_5028_50281302_157_dialog_content = "그랬었지. 그 숲에 있던 빌어먹을 짐승들을 전부 저승으로 보내줬다.\n한 마리도 남김없이 말이야.",
  ui_story_5028_50281302_158_dialog_content = "저들을 죽였다면 네 복수는 끝난 거잖아.\n어째서 다른 환상동물들을 계속 괴롭힌 거야?",
  ui_story_5028_50281302_159_dialog_content = "그것도 모자라서 저들을 굴복시키고, 오로리안을 공격하게 만들었잖아.",
  ui_story_5028_50281302_160_dialog_content = "물론 모든 이들에게 알려주기 위해서지.\n짐승과 오로리안은 다르고, 놈들이 두려운 존재고, 사라져야 마땅하다는 걸 말이다!",
  ui_story_5028_50281302_161_dialog_content = "네 눈에 비친 환상동물은 그런 모습이구나.",
  ui_story_5028_50281302_162_dialog_content = "저들이 네 가족을 해치고, 네 행복을 앗아갔고, 네 반생을 망친 존재라면...",
  ui_story_5028_50281302_163_dialog_content = "무의미한 살육을 계속해 온 넌, 네가 그토록 증오하는 「짐승」과 무슨 차이가 있지?",
  ui_story_5028_50281302_164_dialog_content = "......!",
  ui_story_5028_50281302_165_dialog_content = "친구, 네 인생은 아직 길어. 부디 앞으로의 세월 속에서 그걸 깨닫길 바랄게.",
  ui_story_5028_50281302_166_dialog_content = "내가 해줄 말은 이걸로 끝이야. 수수께끼의 문어 씨.",
  ui_story_5028_50281302_167_dialog_content = "아, 담소가 끝난 모양이지?",
  ui_story_5028_50281302_168_dialog_content = "그럼 내 부탁을 좀 들어줄 수 있을까?",
  ui_story_5028_50281302_169_dialog_content = "여러분, 저자와 그 부하들을 섀도우마스터한테 넘겨줬으면 좋겠어.",
  ui_story_5028_50281302_170_dialog_content = "움브라톤의 안전을 지키고, 죄를 지은 자에게는 상응하는 벌을 준다.\n그건 섀도우마스터의 약속이야.",
  ui_story_5028_50281302_171_dialog_content = "이쪽 아가씨가 말한 「감옥에 넣겠다」는 의견은 내가 섀도우마스터한테 전할게.",
  ui_story_5028_50281302_172_dialog_content = "난 이의 없어. 너희들은?",
  ui_story_5028_50281302_173_dialog_content = "그분은 환상동물에는 관심이 없지만, 죄인의 처리에 있어서는 최고니까.",
  ui_story_5028_50281302_174_dialog_content = "녀석 때문에 우리가 굳이 감옥을 따로 만드는 건 귀찮잖아.",
  ui_story_5028_50281302_175_dialog_content = "섀도우마스터한테는 죄인이 살기 적당한 곳이 분명히 많이 있겠지.",
  ui_story_5028_50281302_176_dialog_content = "나도 이의는 없어.",
  ui_story_5028_50281302_177_dialog_content = "저 녀석을 감옥에 보낼 수 있다면 나도 그걸로 됐어!",
  ui_story_5028_50281302_178_option_content = "그럼 클레이튼, 부탁할게.",
  ui_story_5028_50281302_179_option_content = "고마워.",
  ui_story_5028_50281302_180_dialog_content = "거기 몇 분, 이 강도들을 움브라톤으로 호송하는 걸 좀 도와줄 수 있을까?",
  ui_story_5028_50281302_181_dialog_content = "도움이 필요해? 좋아.",
  ui_story_5028_50281302_182_dialog_content = "쳇, 또 시시한 의뢰네.",
  ui_story_5028_50281302_183_dialog_content = "여기 있어 봤자 우리가 더 도울 일은 없을 것 같아.\n남은 동물들의 구조는 전문가한테 맡기자.",
  ui_story_5028_50281302_184_dialog_content = "응!",
  ui_story_5028_50281302_185_dialog_content = "그럼 난 돌아가서 보고할게. 다들 또 봐.",
  ui_story_5028_50281302_186_dialog_content = "그 녀석이 또 귀찮은 일을 벌이지 않았으면 좋겠는데 말이야.",
  ui_story_5028_50281302_187_dialog_content = "에이, 그런 건 어차피 나중 일이잖아.",
  ui_story_5028_50281401_1_dialog_content = "아무튼 이번 일은 이걸로 해결이네. 아주 잘됐어.",
  ui_story_5028_50281401_2_dialog_content = "키아로, 너 정말 강했구나.",
  ui_story_5028_50281401_3_dialog_content = "천하무적 같은 건 분명히 사부의 거짓말이라고 생각했는데!",
  ui_story_5028_50281401_4_dialog_content = "난 내 제자를 속인 적은 없어. 시라도 피아도 나한테는 모두 소중한 제자들인걸.",
  ui_story_5028_50281401_5_dialog_content = "확실히 속이진 않아.",
  ui_story_5028_50281401_6_dialog_content = "봐, 시라도 그렇다잖아!",
  ui_story_5028_50281401_7_dialog_content = "사부가 믿을 수 없는 건 어디까지나 못 미더워서 그런 것뿐이야.",
  ui_story_5028_50281401_8_dialog_content = "시라... 사부한테 그렇게 말하면 사부 울 거야... 키힝...",
  ui_story_5028_50281401_9_dialog_content = "근데 키아로는 이렇게 강한 힘을 가지고 있으면서,\n왜 지금까지 위험할 때는 그걸 못 썼던 거야?",
  ui_story_5028_50281401_10_dialog_content = "아니지, 그것보다 더 이상한 건...",
  ui_story_5028_50281401_11_dialog_content = "사부는 이렇게 대단한 환상동물이 있으면서,\n왜 지금까지 그렇게 쓸모없게 살았어?!",
  ui_story_5028_50281401_12_dialog_content = "그래! 그거 정말 이상하잖아!",
  ui_story_5028_50281401_13_dialog_content = "......",
  ui_story_5028_50281401_14_dialog_content = "하아... 그건 내가 설명해줄게.",
  ui_story_5028_50281401_15_dialog_content = "키아로라는 생물은 매우 특별하고 강한 힘을 가지고 있어.",
  ui_story_5028_50281401_16_dialog_content = "그 힘은 서로 신뢰하는 생물과 소통할 수 있어야 다룰 수 있는 거야.",
  ui_story_5028_50281401_17_dialog_content = "다만 키아로는 그 수가 너무 적어서,\n키아로들의 언어에 대한 정보도 점차 소실됐던 거야.",
  ui_story_5028_50281401_18_dialog_content = "게다가 녀석들의 의태 특성 때문에, 사용하는 신체 언어도 저마다 달라.\n그래서 사람들은 저들의 의사를 정확하게 이해할 수 없었어.",
  ui_story_5028_50281401_19_dialog_content = "결국 키아로와 소통할 수 있는 오로리안은 거의 없게 된 거지.",
  ui_story_5028_50281401_20_dialog_content = "가끔은 키아로끼리조차도 상대의 울음소리를 이해하지 못해서\n소통할 수 없을 때도 있어.",
  ui_story_5028_50281401_21_dialog_content = "그래서 키아로의 유체가 야생에서 살아남을 확률은\n엄청나게 낮아지고 말았던 거지.",
  ui_story_5028_50281401_22_dialog_content = "네가 키아로 서식지에서 본 키아로들은 사실 전부 비크가 직접 키운 거야.",
  ui_story_5028_50281401_23_dialog_content = "사부가 그렇게 대단했던 거야?!",
  ui_story_5028_50281401_24_dialog_content = "근데 키아로와 소통할 수 없다면, 사부는 어떻게 키아로의 습성을 알았어?",
  ui_story_5028_50281401_25_dialog_content = "키아로의 마음을 읽을 방법이 하나 있거든. 바로...",
  ui_story_5028_50281401_26_option_content = "나...?",
  ui_story_5028_50281401_27_dialog_content = "정확히 말하자면 아이테르의 감응 능력 말이야.",
  ui_story_5028_50281401_28_option_content = "아이테르...?",
  ui_story_5028_50281401_29_dialog_content = "그래.",
  ui_story_5028_50281401_30_dialog_content = "아이테르의 감응 능력은 언어의 장벽을 뛰어넘어서,\n키아로의 생각과 느낌을 직접 감지할 수 있어.",
  ui_story_5028_50281401_31_dialog_content = "그런 생각을 이해하고 키아로의 울음소리를 접하면\n조금씩 키아로들의 말을 이해할 수 있게 돼...",
  ui_story_5028_50281401_32_dialog_content = "이제 알겠어, 피아. 저들을 빠르게 이해할 수 있는 게 바로 네 재능이야.",
  ui_story_5028_50281401_33_dialog_content = "그래서 사부가 준 첫 번째 임무가 바로 「아이테르 포획」이었구나?",
  ui_story_5028_50281401_34_dialog_content = "맞아. 「소통」이야말로 키아로의 진정한 능력을 이끌어내는 중요한 요소니까.",
  ui_story_5028_50281401_35_dialog_content = "근데 내가 키아로의 말을 어떻게 이해할 수 있었던 건데?",
  ui_story_5028_50281401_36_dialog_content = "아마 함께 여행을 하는 동안 키아로가 진작에 널 동료로 생각했기 때문이겠지.",
  ui_story_5028_50281401_37_dialog_content = "그럼 게리의 키아로는 어떻게 힘을 사용할 수 있었던 거야?",
  ui_story_5028_50281401_38_dialog_content = "그건 모르겠어.",
  ui_story_5028_50281401_39_dialog_content = "추측일 뿐이지만, 아마 그 채찍과 관계가 있겠지.",
  ui_story_5028_50281401_40_dialog_content = "그 채찍은 공포와 굴복의 낙인을 환상동물들의 마음속에 깊이 새겨 두었을 거야.",
  ui_story_5028_50281401_41_dialog_content = "공포는 신뢰의 반대편에 있는 또 다른 극단,\n키아로의 공포가 극에 달해서 저런 왜곡된 모습으로 변한 거겠지.",
  ui_story_5028_50281401_42_dialog_content = "흥, 그런 건 진짜 「소통」이 아냐!",
  ui_story_5028_50281401_43_dialog_content = "「환상동물 마스터」이자 키아로와 진정한 소통을 할 수 있는 나를\n녀석이 이길 수 없었던 건 분명히 그것 때문일 거야!",
  ui_story_5028_50281401_44_dialog_content = "그럼 비크 씨는 지금까지 이것들을 전부 알고 있었던 거야?",
  ui_story_5028_50281401_45_dialog_content = "전부 알았던 건 아냐.",
  ui_story_5028_50281401_46_dialog_content = "사부는 예전에 한 아이테르를 만났어.",
  ui_story_5028_50281401_47_dialog_content = "그 아이테르의 도움 덕분에 키아로와의 소통에 성공했고,\n이 환상동물을 이해할 수 있었던 거야.",
  ui_story_5028_50281401_48_dialog_content = "17년 전까지 말이야.",
  ui_story_5028_50281401_49_dialog_content = "잠깐만, 비크 씨는 자기가 영원한 18세라고 했는데?",
  ui_story_5028_50281401_50_dialog_content = "그럼 대체 몇 살인 거야?!",
  ui_story_5028_50281401_51_dialog_content = "크흠, 거기까지! 지금은 옛날이야기나 할 때가 아니야!",
  ui_story_5028_50281401_52_dialog_content = "여긴 아직 우리가 해야 할 일이 많거든.",
  ui_story_5028_50281401_53_dialog_content = "루! 루──!",
  ui_story_5028_50281401_54_dialog_content = "왜 그래? 쟤를 좀 봐달라고?",
  ui_story_5028_50281401_55_dialog_content = "루... 루...",
  ui_story_5028_50281401_56_dialog_content = "...갑자기 상태가 악화되기 시작했어.",
  ui_story_5028_50281401_57_dialog_content = "이런... 오랫동안 느낀 공포와 부상 때문에 원래부터 상태가 엉망이었을 텐데...",
  ui_story_5028_50281401_58_dialog_content = "거기에 이번 전투에서 중상을 입었으니까, 몸이 이제 한계에 도달했을 거야.",
  ui_story_5028_50281401_59_dialog_content = "누구 루미나틱스로 치료할 수 있는 사람?",
  ui_story_5028_50281401_60_dialog_content = "......",
  ui_story_5028_50281401_61_dialog_content = "서두르자, 지금 바로 움브라톤에 가서 도움을 청하면 늦지 않을 거야!",
  ui_story_5028_50281401_62_dialog_content = "드라코리온, 도와줘!",
  ui_story_5028_50281401_63_dialog_content = "너무 늦었어!",
  ui_story_5028_50281401_64_dialog_content = "루!",
  ui_story_5028_50281401_65_dialog_content = "어? 키, 키아로?!",
  ui_story_5028_50281401_66_dialog_content = "루우! 루우우!",
  ui_story_5028_50281401_67_dialog_content = "이 녀석들은... 아까 내가 풀어줬던 그 키아로들이야...",
  ui_story_5028_50281401_68_dialog_content = "다들 돌아온 거야?",
  ui_story_5028_50281401_69_dialog_content = "루! 루루!",
  ui_story_5028_50281401_70_dialog_content = "내가 쟤들이랑 이야기하면 도움을 받을 수 있다고?",
  ui_story_5028_50281401_71_dialog_content = "좋아, 한번 해볼게!",
  ui_story_5028_50281401_72_dialog_content = "키아로의 동족들아! 좀 도와줘! 이 아이를 구해줘!",
  ui_story_5028_50281401_73_dialog_content = "부탁이야...",
  ui_story_5028_50281401_74_dialog_content = "구해줘...",
  ui_story_5028_50281401_75_dialog_content = "루!",
  ui_story_5028_50281401_76_dialog_content = "루우우!",
  ui_story_5028_50281401_77_dialog_content = "이 빛... 아까 피아 네 키아로가 냈던 거랑 똑같아!",
  ui_story_5028_50281401_78_dialog_content = "다들 잘 봐.",
  ui_story_5028_50281401_79_dialog_content = "어쩌면 무엇보다 귀한 장면이 될지도 모르니까.",
  ui_story_5028_50281401_80_dialog_content = "키아로들이 아이테르의 도움으로 피아와 마음이 이어지고,\n강력한 힘을 발산하고 있어...",
  ui_story_5028_50281401_81_dialog_content = "루우우──",
  ui_story_5028_50281401_82_dialog_content = "키아로들의 빛이 다친 키아로를 감쌌어...",
  ui_story_5028_50281401_83_dialog_content = "...상처가 점점 회복되고 있어!",
  ui_story_5028_50281401_83X_dialog_content = "이게 바로 키아로의 힘이야.",
  ui_story_5028_50281401_84_dialog_content = "키아로는 다른 환상동물뿐만 아니라 오로리안의 능력까지 따라 할 수 있어.",
  ui_story_5028_50281401_85_dialog_content = "「천하무적」이라는 말도 과하지 않겠지.",
  ui_story_5028_50281401_86_dialog_content = "역시 「천하무적」이라는 말도 과한 게 아냐.",
  ui_story_5028_50281401_87_dialog_content = "그랬구나...",
  ui_story_5028_50281401_88_option_content = "정말 대단해...",
  ui_story_5028_50281401_89_dialog_content = "PlayerName 너도 대단한걸.",
  ui_story_5028_50281401_90_dialog_content = "뭐?",
  ui_story_5028_50281401_91_option_content = "정말 부럽네...",
  ui_story_5028_50281401_92_dialog_content = "나한테도 저런 강한 힘이 있으면 친구들을 더 잘 지킬 수 있을 텐데...",
  ui_story_5028_50281401_93_dialog_content = "넌 이미 충분히 강한 힘을 가지고 있잖아.\n모두의 소통을 연결하는 감응 능력 말이야.",
  ui_story_5028_50281401_94_dialog_content = "감응 능력 그 자체는 싸움에 사용할 수 없지만,\n사람들이 서로를 이해하게 만들 수 있어.",
  ui_story_5028_50281401_95_dialog_content = "오해를 풀고, 원한을 잊고, 나아가 전쟁이 일어나는 걸 막을 수도 있겠지.",
  ui_story_5028_50281401_96_dialog_content = "그런가...",
  ui_story_5028_50281401_97_dialog_content = "그래, 알겠어!",
  ui_story_5028_50281401_98_dialog_content = "봐, 키아로가 기운을 되찾은 것 같아.",
  ui_story_5028_50281401_99_dialog_content = "루... 루?",
  ui_story_5028_50281401_100_dialog_content = "이제 괜찮아!",
  ui_story_5028_50281401_101_dialog_content = "모두가 힘을 합쳐서 널 치료해준 거야!",
  ui_story_5028_50281401_102_dialog_content = "루우, 루!",
  ui_story_5028_50281401_103_dialog_content = "응응, 물론 「환상동물 마스터」인 나한테도 고마워해야지!",
  ui_story_5028_50281401_104_dialog_content = "루우우!",
  ui_story_5028_50281401_105_dialog_content = "으앗! 에헤헤, 간지러워!",
  ui_story_5028_50281401_106_dialog_content = "계속 여기에 있는 것도 곤란해.\n슬슬 녀석들을 원래 살던 곳으로 돌려보내야 해.",
  ui_story_5028_50281401_107_dialog_content = "어? 키아로들... 돌아가야 돼?",
  ui_story_5028_50281401_108_dialog_content = "루!",
  ui_story_5028_50281401_109_dialog_content = "키아로, 너도 가버릴 거야?",
  ui_story_5028_50281401_110_dialog_content = "안 가면 안 돼?!",
  ui_story_5028_50281401_111_dialog_content = "루...",
  ui_story_5028_50281401_112_dialog_content = "루우!",
  ui_story_5028_50281401_113_dialog_content = "아, 안 돼? 그, 그치만...",
  ui_story_5028_50281401_114_dialog_content = "휴, 역시 어린애라니까.",
  ui_story_5028_50281401_115_dialog_content = "환상동물의 습성과 바람을 존중하는 건 우리 연구자가 반드시 갖춰야 할 소양이야.",
  ui_story_5028_50281401_116_dialog_content = "네 생각을 환상동물한테 강요해선 안 돼.",
  ui_story_5028_50281401_117_dialog_content = "나, 난 어린애가 아니라구!",
  ui_story_5028_50281401_118_dialog_content = "루!",
  ui_story_5028_50281401_119_dialog_content = "이건...",
  ui_story_5028_50281401_120_dialog_content = "가골빼미의 능력...? 네가 이런 수를 쓸 줄... 흠냐...",
  ui_story_5028_50281401_121_dialog_content = "루루!",
  ui_story_5028_50281401_122_dialog_content = "이런 이런, 이렇게 빨리 가버린 거야?",
  ui_story_5028_50281401_123_dialog_content = "동료와 헤어졌으니까, 피아가 잠에서 깨면 분명히 엄청 울고 난리가 나겠네.",
  ui_story_5028_50281401_124_dialog_content = "어린애 달래는 건 너무 귀찮다고.",
  ui_story_5028_50281401_125_dialog_content = "사부도 아이 돌보기는 서투르니까, 피아 일은 우리 첫째 제자한테 부탁할게.",
  ui_story_5028_50281401_126_dialog_content = "하아...",
  ui_story_5028_50281401_127_dialog_content = "친구들이랑 사이좋게 지내!",
  ui_story_5028_50281401_128_dialog_content = "위험한 녀석한테는 가까이 가지 마.",
  ui_story_5028_50281401_129_dialog_content = "루!",
  ui_story_5028_50281401_130_dialog_content = "이야기는 여기서 끝났어.",
  ui_story_5028_50281401_131_dialog_content = "키아로랑 동족들은 지금도 숲속에서 행복하게 살고 있어.",
  ui_story_5028_50281401_132_dialog_content = "그리고 피아라는 소녀는 성장했고, 명실상부한 「환상동물 마스터」가 됐어.",
  ui_story_5028_50281401_133_dialog_content = "이걸로 해피 엔딩이야.",
  ui_story_5028_50281401_134_dialog_content = "그리고? 그다음엔 어떻게 됐는데?",
  ui_story_5028_50281401_135_dialog_content = "바이스... 좀 쉬면 안 될까?",
  ui_story_5028_50281401_136_dialog_content = "벌써 꼬박 3시간째 《환상동물 탐사 대모험》 이야기를 읽어주고 있잖아...",
  ui_story_5028_50281401_137_dialog_content = "목이 타버릴 것 같다고!",
  ui_story_5028_50281401_138_dialog_content = "아, 미안 미안, 그럼 잠깐 쉬어.",
