  ui_story_5028_50281401_145_dialog_content = "아이테르 넌 내 환상동물 파트너니까, 거부는 허락할 수 없어!",
  ui_story_5028_50281401_146_dialog_content = "알았어, 알았어, 알았으니까... 몇 번이나 말했어? 난 환상동물이 아니야.",
  ui_story_5028_50281401_147_dialog_content = "이제 와서 부정하는 거야? 유감이네, 이미 늦었어.",
  ui_story_5028_50281401_148_dialog_content = "이 환상동물 마스터는 너의 주인으로서 네가 멋대로 도망치는 걸 허락하지 않아!",
