  ui_story_5028_50281401_153_dialog_content = "말했잖아, 교배기가 지나면 알아서 돌아갈 거라고.",
  ui_story_5028_50281401_154_dialog_content = "환상동물의 습성과 바람을 존중하는 건 나 같은 환상동물 마스터가\n반드시 갖춰야 할 소양이야!",
  ui_story_5028_50281401_155_dialog_content = "그러니까 난 억지로 돌려보내지 않아!",
